const e=JSON.parse(`{"almond":{"common":["Wild almonds are bitter with amygdalin, which releases cyanide: about 50 bitter almonds could kill an adult. Sweet almonds exist thanks to a mutation in a single gene.","https://en.wikipedia.org/wiki/Almond"],"uncommon":["About 80% of the world's almond supply comes from a single US state, California.","https://www.almonds.org/why-almonds/ca-advantage"],"rare":["California's almond bloom in February 2024 needed an estimated 2.7 million rented honey bee colonies, about 99% of all US colonies counted that January.","https://farmdocdaily.illinois.edu/2025/02/where-have-all-the-honey-bees-gone-to-california-almond-orchards.html"],"epic":["In Exodus, the golden lampstand of the Tabernacle is described with cups made like almond blossoms, each with a calyx and a flower.","https://www.biblegateway.com/verse/en/exo+25:33"],"legendary":["In 1832 Liebig and Wöhler studied oil of bitter almonds (benzaldehyde) and found the benzoyl radical, the first group of atoms shown to pass intact through organic reactions.","https://www.sciencehistory.org/education/scientific-biographies/justus-von-liebig-and-friedrich-wohler/"]},"ambergris":{"common":["Lumps of ambergris often contain the beaks of giant squid. The waxy mass is thought to form in the sperm whale's gut to help it pass these hard, sharp remains.","https://en.wikipedia.org/wiki/Ambergris"],"uncommon":["In 2021, 35 Yemeni fishermen found a 127 kg lump of ambergris in a sperm whale carcass off Aden and sold it for more than $1.5 million.","https://www.newarab.com/news/yemen-fishermen-finds-fortune-whale-belly"],"rare":["Ambrox, the main ambergris substitute, is made from sclareol found in clary sage. Firmenich researchers later engineered E. coli bacteria to brew sclareol in bioreactors.","https://newatlas.com/ambergris-clary-sage-substitute/26409/"],"epic":["Before colonisation, Māori in New Zealand chewed ambergris found on beaches as a gum and called it mīmiha.","https://en.wikipedia.org/wiki/Ambergris"],"legendary":["A serving of eggs and ambergris was reportedly the favourite dish of King Charles II of England.","https://en.wikipedia.org/wiki/Ambergris"]},"ambrette":{"common":["Ambrette seed oil was long used in perfume as a cheaper plant substitute for animal musk, and the species name moschatus simply means musky.","https://en.wikipedia.org/wiki/Abelmoschus_moschatus"],"uncommon":["Ambrette is a yellow-flowered hibiscus in the mallow family and a relative of okra; its seed capsules have been used in soups and pickles.","https://growables.org/informationVeg/OkraGrieve.htm"],"rare":["The US Dispensatory recorded that Arabs flavoured their coffee with ambrette seeds, by then otherwise used only in perfumery.","https://www.henriettes-herb.com/eclectic/usdisp/hibiscus.html"],"epic":["In 1705 naturalist Maria Sibylla Merian recorded that young Indigenous women in Suriname strung ambrette seeds on threads to wear as armbands.","https://en.wikipedia.org/wiki/Abelmoschus_moschatus"],"legendary":["Musk ambrette, a synthetic nitro musk named after the seed, is now prohibited by IFRA and in EU cosmetics; fed to rats it caused hind-limb paralysis.","https://industrialchemicals.gov.au/sites/default/files/Benzene,%201-(1,1-dimethylethyl)-2-methoxy-4-methyl-3,5-dinitro-_Human%20health%20tier%20II%20assessment.pdf"]},"amyris":{"common":["Sold as West Indian sandalwood for its similar scent, amyris is botanically unrelated to true sandalwood; it belongs to the citrus family, Rutaceae.","https://www.edenbotanicals.com/amyris-essential-oil.html"],"uncommon":["Haitians call amyris bois chandelle, candlewood. The wood is so resinous that split sticks burned like torches for night fishing and lighting paths before kerosene arrived.","https://premierepeau.com/pages/glossary-terms/amyris"],"rare":["Amyris wood is hard and heavy, takes a high polish and repels drywood termites. It is so resinous it burns well even when green.","https://en.wikipedia.org/wiki/Amyris"],"epic":["The genus name Amyris comes from the Greek amyron, meaning intensely scented, a nod to the strong odour of its resin.","https://premierepeau.com/pages/glossary-terms/amyris"],"legendary":["The 1918 US Dispensatory warned that amyris oil was used to adulterate sandalwood oil; it gives itself away by turning polarised light right, not left like true santal oil.","https://henriettes-herb.com/eclectic/usdisp/santalum_oleu.html"]},"angelica":{"common":["European legend says an angel revealed in a monk's dream that angelica could cure the plague, and Gerard's 1597 herbal called it a singular remedy against it.","https://nutritionalgeography.faculty.ucdavis.edu/spices/angelica/"],"uncommon":["Angelica root is among the most common botanicals in gin, and it also flavours liqueurs such as Chartreuse and Bénédictine, plus vermouth.","https://en.wikipedia.org/wiki/Angelica_archangelica"],"rare":["Around Niort in the Marais Poitevin the green stems are candied as a sweet, and in 2006 candied angelica was approved by the regional agri-food quality institute.","https://www.niortmaraispoitevin.com/en/vos-experiences-au-naturel/savoir-faire/gastronomie/produits-du-terroir/"],"epic":["Angelica root holds a musky compound, under 1% of the root and under 0.5% of the seeds, that gives the root its distinctive musky aroma.","https://en.wikipedia.org/wiki/Angelica_archangelica"],"legendary":["Norway's old district laws, the oldest dating to around AD 960, protected enclosed angelica gardens, like onion and cabbage plots, against theft and damage.","https://www.medievalists.net/2012/06/27/the-plants-used-in-a-viking-age-garden-a-d-800-1050/"]},"apple":{"common":["About 25% of an apple's volume is air, which is why apples float and why bobbing for them works.","https://www.freshplaza.com/north-america/article/2162560/why-do-apples-float"],"uncommon":["DNA work in 2010 confirmed the wild Malus sieversii of Kazakhstan's Tian Shan as the ancestor of eating apples; Almaty's name is often explained as full of apples.","https://en.wikipedia.org/wiki/Malus_sieversii"],"rare":["There are more than 7,500 known apple cultivars, and the UK's National Fruit Collection alone holds over 2,000 of them.","https://en.wikipedia.org/wiki/Apple"],"epic":["Granny Smith began in 1868 in Eastwood, now a Sydney suburb, as a chance seedling that Maria Ann Smith propagated; one story says it sprouted from cores tossed out her window.","https://en.wikipedia.org/wiki/Granny_Smith"],"legendary":["Seeds from Isaac Newton's 400-year-old apple tree spent six months on the International Space Station in 2015 with Tim Peake, then grew into young trees back on Earth.","https://en.wikipedia.org/wiki/Isaac_Newton%27s_apple_tree"]},"apricot":{"common":["Turkey is the world's top apricot grower, producing about a fifth of the roughly 3.7 million tonnes harvested worldwide in 2023.","https://en.wikipedia.org/wiki/Apricot"],"uncommon":["Dried apricots not treated with sulphur dioxide turn out much darker, so the bright orange ones on shop shelves have usually been sulphured.","https://en.wikipedia.org/wiki/Apricot"],"rare":["Apricot probably comes from Latin praecoquum, 'early-ripening fruit', the same root as precocious, travelling via Greek and Arabic al-birquq.","https://www.etymonline.com/word/apricot"],"epic":["Dong Feng, a physician of China's Three Kingdoms period, asked cured patients only to plant apricot trees, growing a large grove that supplied his medicine.","https://en.wikipedia.org/wiki/Apricot"],"legendary":["US Marines treat apricots as exceptionally bad luck around tanks, a superstition dating back to the Vietnam War; some only say cots or A-fruit.","https://en.wikipedia.org/wiki/Apricot"]},"araucaria":{"common":["The monkey puzzle is the national tree of Chile. Logging it was a major threat until it was finally banned in 1990.","https://en.wikipedia.org/wiki/Araucaria_araucana"],"uncommon":["The name monkey puzzle comes from a remark made in Cornwall around 1850 by the lawyer Charles Austin: \\"It would puzzle a monkey to climb that.\\"","https://en.wikipedia.org/wiki/Araucaria_araucana"],"rare":["Its bark can be up to 15 cm thick, and adult trees are highly resistant to the upheavals of volcanic eruptions in the Andes.","https://en.wikipedia.org/wiki/Araucaria_araucana"],"epic":["The Pehuenche people of the Andes owe their name to the pehuén tree, whose large edible seeds, like big pine nuts, were the basis of their diet.","https://en.wikipedia.org/wiki/Araucaria_araucana"],"legendary":["A tree called Araucaria Madre in Chile's Conguillío National Park is said, by a sign beside it, to be 1,800 years old.","https://en.wikipedia.org/wiki/Araucaria_araucana"]},"artemisia":{"common":["Herba-alba means white herb in Latin: its leaves and stems are woolly with fine hairs that reflect sunlight and turn the shrub grey.","https://en.wikipedia.org/wiki/Artemisia_herba-alba"],"uncommon":["White wormwood grows on dry steppes from Saharan North Africa to Arabia, where it is valued as fodder for grazing sheep.","https://en.wikipedia.org/wiki/Artemisia_herba-alba"],"rare":["Pliny wrote that the Artemisia genus was named after Queen Artemisia II of Caria, a botanist and medical researcher who built the Mausoleum at Halicarnassus.","https://en.wikipedia.org/wiki/Artemisia_II_of_Caria"],"epic":["It is thought to be the wormwood of English Bibles; in Revelation a star named Wormwood falls and turns a third of the waters bitter.","https://en.wikipedia.org/wiki/Artemisia_herba-alba"],"legendary":["Tu Youyou found artemisinin in a cousin, sweet wormwood, after reading a recipe written by Ge Hong in 340 to steep it in cold water. She shared the 2015 Nobel Prize.","https://en.wikipedia.org/wiki/Tu_Youyou"]},"balsam":{"common":["Balsam of Peru is collected in Central America. It got its name because it was shipped via Callao, the port of Lima, before going on to Europe.","https://en.wikipedia.org/wiki/Balsam_of_Peru"],"uncommon":["To harvest Peru balsam, workers beat the trunk and scorch it with torches. About a week later balsam seeps into rags wrapped around the wood, which are then boiled to free it.","https://uses.plantnet-project.org/en/Myroxylon_balsamum_(PROSEA)"],"rare":["Peru balsam is used to flavour foods and drinks, including soft drinks such as cola and root beer.","https://en.wikipedia.org/wiki/Balsam_of_Peru"],"epic":["Balsam of Peru ranks among the top five allergens in patch tests; a 2001 study found 3.8% of the general population tested was allergic to it.","https://en.wikipedia.org/wiki/Balsam_of_Peru"],"legendary":["Balsam of Peru holds about 25 identified substances, such as cinnamein and benzyl benzoate, yet 30 to 40% of it is resins or esters of unknown composition.","https://en.wikipedia.org/wiki/Balsam_of_Peru"]},"bamboo":{"common":["Bamboo is a giant grass, and certain species can grow 91 cm in a single 24-hour day.","https://en.wikipedia.org/wiki/Bamboo"],"uncommon":["Thomas Edison found that a carbonised filament made from bamboo grown in Yawata, near Kyoto, could glow for over 1,200 hours, far longer than anything else he tested.","https://www.detroit.us.emb-japan.go.jp/en/bilateral/Ohio/OHedison.htm"],"rare":["The longest known bamboo mass-flowering interval is 120 years: in Japanese timber bamboo, all plants of the same stock flower at the same time.","https://en.wikipedia.org/wiki/Bamboo"],"epic":["Ang Lee's Crouching Tiger, Hidden Dragon, with its famous bamboo-forest duel, was partly shot on location in Anji, China.","https://en.wikipedia.org/wiki/Crouching_Tiger,_Hidden_Dragon"],"legendary":["In Mizoram, a bamboo flowers every 48-50 years, unleashing rat floods and famine; relief workers in the 1959 famine formed a group that became the rebel Mizo National Front.","https://en.wikipedia.org/wiki/Mautam"]},"basil":{"common":["Basil comes from the Greek basilikon, royal or kingly plant, possibly because it was used in royal perfumes; the French still call it l'herbe royale.","https://en.wikipedia.org/wiki/Basil"],"uncommon":["The clove-like note of sweet basil comes from eugenol, the same molecule that dominates clove; linalool and estragole add the rest.","https://en.wikipedia.org/wiki/Basil"],"rare":["In Portugal, a pot of dwarf bush basil is traditionally given to a sweetheart on the feast days of Saint John the Baptist and Saint Anthony of Padua.","https://en.wikipedia.org/wiki/Basil"],"epic":["In Keats's 1818 poem Isabella, or the Pot of Basil, taken from Boccaccio, Isabella buries her murdered lover's head in a pot of basil and tends it obsessively.","https://en.wikipedia.org/wiki/Isabella,_or_the_Pot_of_Basil"],"legendary":["The Greek Orthodox Church uses basil to sprinkle holy water, and some Greek Orthodox Christians avoid eating it because of its link to the legend of the Holy Cross.","https://en.wikipedia.org/wiki/Basil"]},"bay":{"common":["West Indian bay is a completely different plant from the bay laurel of European cooking, Laurus nobilis, though both have been used to scent bay rum.","https://en.wikipedia.org/wiki/Bay_rum"],"uncommon":["The bay rum tree has long been used as a painkiller in the Caribbean, and extracts show anti-inflammatory effects linked to terpenes such as lupeol.","https://en.wikipedia.org/wiki/Pimenta_racemosa"],"rare":["Bay rum was first made around 1840 on St Thomas in the Danish West Indies by distilling rum with West Indian bay leaves, and became fashionable in New York before Europe.","https://en.wikipedia.org/wiki/Bay_rum"],"epic":["A. H. Riise began making bay rum on St Thomas in 1883, and the company still makes men's products in the US Virgin Islands as St. Johns Bay Rum.","https://en.wikipedia.org/wiki/Bay_rum"],"legendary":["During Prohibition, bay rum at 58% alcohol was drunk as a legal, somewhat toxic liquor, and in 1933 Tom Ashley and Gwen Foster recorded Bay Rum Blues about it.","https://en.wikipedia.org/wiki/Bay_rum"]},"benzoin":{"common":["Gum benzoin is a major component of the incense burned in Russian churches, and similar blends are used across Orthodox and Catholic worship.","https://en.wikipedia.org/wiki/Benzoin_(resin)"],"uncommon":["A solution of benzoin is used in surgery and anaesthesia as an adhesive to keep wound and catheter dressings in place.","https://en.wikipedia.org/wiki/Benzoin_(resin)"],"rare":["Sumatran benzoin contains cinnamic acid as well as benzoic acid, while Siam benzoin from Styrax tonkinensis, grown in Laos and neighbours, lacks it.","https://en.wikipedia.org/wiki/Benzoin_(resin)"],"epic":["Benzene is named after gum benzoin: in 1833 Eilhard Mitscherlich made it by distilling benzoic acid from the resin with lime, and called it benzin.","https://en.wikipedia.org/wiki/Benzene"],"legendary":["The benz in benzene and benzoic acid traces back to Arabic lubān jāwī, frankincense from Java, the traders' name for this resin.","https://en.wikipedia.org/wiki/Benzoin_(resin)"]},"bergamot":{"common":["Earl Grey is black tea flavoured with bergamot peel oil, sprayed on the leaves or added as dried rind. Bergamot-scented tea is recorded as early as 1824.","https://en.wikipedia.org/wiki/Earl_Grey_tea"],"uncommon":["Genetic research shows bergamot is probably a hybrid of lemon and bitter orange, and the lemon is itself a bitter orange and citron cross.","https://en.wikipedia.org/wiki/Bergamot_orange"],"rare":["Psoralen from bergamot oil was used in tanning products until 1995, although it had been known since 1959 to cause cancer when skin meets sunlight.","https://en.wikipedia.org/wiki/Bergamot_orange"],"epic":["About 100 bergamot oranges yield only around 85 g of essential oil, and the fruit is grown mainly for that oil rather than to be eaten.","https://en.wikipedia.org/wiki/Bergamot_orange"],"legendary":["Bergamot is one of the most common flavourings in Swedish snus, the moist tobacco pouch tucked under the lip.","https://en.wikipedia.org/wiki/Bergamot_orange"]},"birch":{"common":["Birch tar is made by dry distillation of birch bark, and oiling tanned hides with it gave Russia leather its water resistance and smoky smell.","https://en.wikipedia.org/wiki/Birch_tar"],"uncommon":["Ötzi the Iceman, who died in the Alps over 5,000 years ago, used birch tar to fix his arrow points and copper axe to their shafts.","https://en.wikipedia.org/wiki/Birch_tar"],"rare":["Neanderthals were heating birch bark into tar at least 200,000 years ago and used it as glue to fix stone points to handles, the oldest known adhesive made by any human species.","https://livescience.com/60302-first-adhesive-invented-by-neanderthals.html"],"epic":["Birch bark tar oil repels slugs and snails, and a single application keeps working for about two weeks.","https://en.wikipedia.org/wiki/Birch_tar"],"legendary":["Scientists sequenced a complete human genome and mouth microbiome from a 5,700-year-old lump of birch tar chewed by a woman in Denmark.","https://en.wikipedia.org/wiki/Birch_tar"]},"blackberry":{"common":["Botanically a blackberry is not a berry at all but an aggregate fruit, a cluster of tiny drupelets that each hold a seed.","https://en.wikipedia.org/wiki/Blackberry"],"uncommon":["English folklore says not to pick blackberries after Michaelmas, 29 September, because the devil spits on them; autumn frosts do make the late berries mushy and mouldy.","https://folklorethursday.com/folklife/michaelmas-the-devils-blackberry-day/"],"rare":["Mexico is the world's leading blackberry producer and exports nearly its whole crop; in 2017 it supplied 97% of the fresh blackberries the US imported.","https://en.wikipedia.org/wiki/Blackberry"],"epic":["Blackberries span over 375 species, many of them apomictic microspecies that make seeds without sex, a puzzle that long confused botanists.","https://en.wikipedia.org/wiki/Blackberry"],"legendary":["Forensic study of Haraldskær Woman, a 2,500-year-old bog body from Denmark, found blackberries among the foods in her stomach.","https://en.wikipedia.org/wiki/Blackberry"]},"blackcurrant":{"common":["In 1911 the US government banned growing blackcurrants because they spread a rust disease that kills white pines. The federal ban was lifted in 1966, but some state bans remain.","https://en.wikipedia.org/wiki/Blackcurrant_production_in_the_United_States"],"uncommon":["About 95% of the blackcurrants grown in Britain go into Ribena, a name taken from the plant's Latin name, Ribes nigrum.","https://en.wikipedia.org/wiki/Blackcurrant"],"rare":["With oranges hard to import in WWII, Britain promoted blackcurrants for vitamin C, and from 1942 gave blackcurrant syrup free to children under two.","https://en.wikipedia.org/wiki/Blackcurrant"],"epic":["Kir, white wine with crème de cassis, was once called blanc-cassis. It is named after Félix Kir (1876-1968), mayor of Dijon, who served it to visiting twin-town delegations.","https://en.wikipedia.org/wiki/Kir_(cocktail)"],"legendary":["Canvasback duck served with blackcurrants was a delicacy in 19th-century New York, long before the berry was banned in parts of the US.","https://en.wikipedia.org/wiki/Blackcurrant"]},"bluecypress":{"common":["Blue cypress is grown for its blue essential oil, which is rich in guaiol and chamazulene, the compound that gives it its colour.","https://en.wikipedia.org/wiki/Callitris"],"uncommon":["Cypress pine timber can resist decay and termites for up to 50 years, so it is used for house stumps, fence posts and telephone poles.","https://www.agriculture.gov.au/sites/default/files/abares/forestsaustralia/publishingimages/forest%20profiles%202005/callitris_forests_2005.pdf"],"rare":["An early blue cypress plantation outside Darwin was abandoned after Cyclone Tracy, when the trees proved unable to stand up to strong winds.","https://en.wikipedia.org/wiki/Callitris"],"epic":["Aboriginal people of northern Australia make spears, paddles and music sticks from northern cypress pine, use its resin as glue and its bark to repel mosquitoes.","https://www.agriculture.gov.au/sites/default/files/abares/forestsaustralia/publishingimages/forest%20profiles%202005/callitris_forests_2005.pdf"],"legendary":["Writer Eric Rolls described pollination time, when hundreds of cones go off together with a sharp crack and spurt brown pollen into the air.","https://en.wikipedia.org/wiki/Callitris_intratropica"]},"boronia":{"common":["Brown boronia's cup-shaped, hanging flowers are reddish brown to purplish black on the outside and yellow on the inside.","https://en.wikipedia.org/wiki/Boronia_megastigma"],"uncommon":["About 12.5 million boronia flowers are needed to make 1 kg of absolute, which typically sells for around A$15,000.","https://theraconteur.co/blogs/news/australian-native-boronia"],"rare":["A 2013 study found that one DNA change in the receptor gene OR5A1 makes some people less sensitive to beta-ionone, boronia's key scent molecule, and they describe it as sour.","https://sciencedaily.com/releases/2013/08/130801125253.htm"],"epic":["Boronia honours Francesco Borone, a servant who became botanist James Edward Smith's assistant; he died at about 25 after falling from a window in Athens.","https://paulineconolly.com/2015/boronia-heart-stopper-and-heart-breaker-i-adore-it-even-though-i-cant-grow-it/"],"legendary":["Harvested boronia flowers lie piled 20 to 30 cm deep for about 48 hours before distilling, and in that time stamen enzymes more than double their beta-ionone.","https://theraconteur.co/blogs/news/australian-native-boronia"]},"breubranco":{"common":["Breu branco belongs to the Burseraceae, known as the frankincense and myrrh family; its genus Protium alone holds about 147 species.","https://en.wikipedia.org/wiki/Burseraceae"],"uncommon":["Riverside Amazon communities used breu resin to caulk boats and seal holes in their houses, and the residue left after distilling still caulks small boats.","https://portalamazonia.com/economia/breu-da-amazonia-extrativistas-no-amazonas-geram-renda-atraves-da-resina-das-arvores/"],"rare":["Some Amazonian Indigenous groups use breu branco resin as a nasal decongestant for severe colds, and it is also applied to the skin against infections.","https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/1140705/1/Especies-Arboreas-Brasileiras-vol-2-Almecegueira.pdf"],"epic":["Breu branco goes by dozens of popular names in Brazil, among them almácega, almíscar, incenso and pau de mosquito, the mosquito tree.","https://portalamazonia.com/amazonia-de-a-a-z/b/breu/"],"legendary":["Leaf-cutting ants disperse breu branco seeds, and research on Atta sexdens found their harvesting piles seeds together, which raises seedling deaths.","https://www.scielo.br/j/rbb/a/b8sf4fvcS9N45YNrnNrGpqc/abstract/?lang=en"]},"broom":{"common":["Spanish broom's stiff green branches are used to make brooms, and its species name junceum means rush-like, after its rush-like shoots.","https://en.wikipedia.org/wiki/Spartium"],"uncommon":["The name Spartium comes from Greek for cordage: the fibres long tied up vines and were woven into cloth, and the plant also yields a yellow dye.","https://en.wikipedia.org/wiki/Spartium"],"rare":["Plantagenet began as a nickname for Geoffrey, Count of Anjou. The popular explanation is the yellow broom plant, genista in medieval Latin and genêt in French.","https://en.wikipedia.org/wiki/House_of_Plantagenet"],"epic":["In 1836 Giacomo Leopardi, escaping cholera at a villa on the slopes of Vesuvius, wrote La Ginestra, inspired by the broom growing over the lava hillside.","https://www.unina.it/en/w/villa-delle-ginestre-torre-del-greco-1"],"legendary":["The 1969 Peruvian huayno Flor de Retama, named for this yellow flower, recalls the Huanta massacre; retama was then removed from the town's main plaza.","https://en.wikipedia.org/wiki/Spartium"]},"buchu":{"common":["Khoekhoe people rubbed powdered buchu mixed with sheep fat on the skin, and a 1668 account describes women strewing it over their heads.","https://www.environmentandsociety.org/sites/default/files/key_docs/low-13-3.pdf"],"uncommon":["Buchu oil contains 8-mercapto-p-menthan-3-one, a sulfur molecule flavourists add in low doses to boost blackcurrant, grapefruit and peach flavours.","https://www.cosmeticsandtoiletries.com/home/product/22937766/givaudan-mercapto8-pmenthane3one"],"rare":["Botanists once filed buchu under Diosma, Greek for divine smell, before it was moved to Barosma, Greek for heavy smell.","https://www.environmentandsociety.org/sites/default/files/key_docs/low-13-3.pdf"],"epic":["Around 1860 Helmbold's Buchu, a weak alcoholic brew of the leaves, sold for a dollar per six-ounce vial and shipped in car-load lots, one of America's most notorious patent medicines.","https://henriettes-herb.com/eclectic/lloyd-hist/barosma.html"],"legendary":["In /Xam San accounts recorded by the Bleek family, buchu was used to calm the rain-bull, a mythical animal of rain.","https://www.environmentandsociety.org/sites/default/files/key_docs/low-13-3.pdf"]},"buddhawood":{"common":["Buddha wood has a string of nicknames, from budtha and sandalbox to native, false and bastard sandalwood, though it is an Eremophila shrub.","https://en.wikipedia.org/wiki/Eremophila_mitchellii"],"uncommon":["The very hard timber suits woodturning: its oil lets it take a high gloss, and it keeps a pleasant scent for a long time, even after sealing.","https://en.wikipedia.org/wiki/Eremophila_mitchellii"],"rare":["Eremophila means desert-loving in Greek. Its seeds can lie dormant in the ground for years until a fire, heavy rain or even roadworks wakes them.","https://en.wikipedia.org/wiki/Eremophila_(plant)"],"epic":["Its heartwood oil, rich in eremophilone, was registered in Australia as the country's first natural termiticide, after the wood was found to resist termites.","https://www.scienceinpublic.com.au/termites/"],"legendary":["Buddha wood invades grazing land so readily that growing it is prohibited in Western Australia, and cleared shrubs regrow from roots left in the soil.","https://en.wikipedia.org/wiki/Eremophila_mitchellii"]},"cacao":{"common":["In Aztec markets cacao beans were money: one bean bought a tomato and 200 a turkey. Forgers hollowed out beans and filled them with sand.","https://www.worldhistory.org/Chocolate_in_Mesoamerica/"],"uncommon":["About 400 cacao seeds make one pound of chocolate, and a tree may yield less than 10 pounds of chocolate over its roughly 25-year life.","https://www.wxpr.org/natural-resources/2018-02-13/how-a-tiny-relative-of-the-mosquito-helps-make-chocolate-a-reality"],"rare":["Cacao flowers sprout straight from the trunk, stay open for only 1 to 2 days, and are pollinated mainly by tiny biting midges of the genus Forcipomyia.","https://www.wxpr.org/natural-resources/2018-02-13/how-a-tiny-relative-of-the-mosquito-helps-make-chocolate-a-reality"],"epic":["Ghana's cocoa industry traces to seedlings Tetteh Quarshie brought from Fernando Po in 1879; three original trees remain at his farm in Mampong.","https://www.timeout.com/accra/attractions/tetteh-quarshies-cocoa-farm"],"legendary":["Residues on pottery from Santa Ana-La Florida in Ecuador's upper Amazon show the Mayo-Chinchipe culture used domesticated cacao 5,300 to 5,450 years ago.","https://www.sciencenews.org/?p=25329"]},"cade":{"common":["Cade oil is made by destructive distillation of prickly juniper wood, giving a dark, aromatic oil with a strong smoky smell.","https://en.wikipedia.org/wiki/Cade_oil"],"uncommon":["In 19th-century France, oil of cade was a standard remedy for eczema, psoriasis and other skin complaints, and it was used even more widely on animals.","https://henriettes-herb.com/eclectic/kings/juniperus-oxyc_oleu.html"],"rare":["La Cadière-d'Azur in Provence keeps 25 dry-stone cade ovens, built in the 19th century and very active until the 1930s, where the wood was burned to tar.","https://provence-alpes-cotedazur.com/decouvrir/espaces-naturels/patrimoine-naturel/fours-a-cade-la-cadiere-dazur-fr-3261251/"],"epic":["Its Latin name oxycedrus means sharp cedar, and prickly juniper may have been the original cedar of the ancient Greeks.","https://en.wikipedia.org/wiki/Juniperus_oxycedrus"],"legendary":["Crude cade oil holds about 1,000 ppm of benzopyrenes, so perfumers may use only rectified oil, capped at 1 ppb of two such compounds in the finished product.","https://premierepeau.com/pages/glossary-terms/cade-oil"]},"calamansi":{"common":["Calamansi is a hybrid of a kumquat and another citrus, probably a mandarin orange, and it is a staple of traditional Philippine cooking.","https://en.wikipedia.org/wiki/Calamansi"],"uncommon":["Calamansi juice is very sour but its thin peel is sweet, and in the Philippines the juice even helps curdle kesong puti, a soft carabao-milk cheese.","https://en.wikipedia.org/wiki/Calamansi"],"rare":["The Philippines is the only major producer of calamansi, and it is the country's fourth most widely grown fruit crop after banana, mango and pineapple.","https://en.wikipedia.org/wiki/Calamansi"],"epic":["Calamansi is also called calamondin, from the Tagalog kalamunding, as well as golden lime, Panama orange, musk orange and, in Malay, limau kasturi.","https://en.wikipedia.org/wiki/Calamansi"],"legendary":["In Florida, where the fruit is called calamondin, calamondin cake made with the ripe fruit was a popular bake from the 1920s to the 1950s.","https://en.wikipedia.org/wiki/Calamansi"]},"calamus":{"common":["Sweet flag is named for its sweet scent and its likeness to iris flags, while calamus comes from the Greek kalamos, meaning reed.","https://en.wikipedia.org/wiki/Acorus_calamus"],"uncommon":["In 1968 the US FDA banned calamus and its oil from human food. The concern is beta-asarone, which can make up to 75% of the plant's oil.","https://en.wikipedia.org/wiki/Acorus_calamus"],"rare":["Walt Whitman named a cluster of love poems in the 1860 edition of Leaves of Grass 'Calamus', after the marsh-growing sweet flag and its pink-tinged roots.","https://en.wikipedia.org/wiki/Calamus_(poems)"],"epic":["Calamus appears in the Chester Beatty Papyrus VI from about 1300 BC. Ancient Egyptians rarely used it as medicine but did add it to perfumes.","https://en.wikipedia.org/wiki/Acorus_calamus"],"legendary":["Calamus is reputed to be hallucinogenic, yet experiments with American calamus produced no such effect, even at doses of up to 300 g of rhizome.","https://en.wikipedia.org/wiki/Acorus_calamus"]},"cannabis":{"common":["The word canvas comes from Old French chanevaz, literally 'made of hemp', which traces back through Latin to the Greek kannabis.","https://www.etymonline.com/word/canvas"],"uncommon":["Hemp is one of the earliest cultivated plants: hemp fibre imprints on Yangshao culture pottery in China date from the 5th millennium BC.","https://en.wikipedia.org/wiki/History_of_cannabis"],"rare":["In 2021 chemists traced cannabis's skunky smell mainly to prenylthiol, a sulfur molecule that also gives light-struck 'skunked' beer its notorious off-flavour.","https://www.sciencenews.org/article/marijuana-skunk-smell-cannabis-pot-plant-chemistry"],"epic":["The Greek historian Herodotus reported that the people of Scythia would often inhale the vapours of hemp-seed smoke.","https://en.wikipedia.org/wiki/History_of_cannabis"],"legendary":["Wild cannabis was estimated in a 2006 UN drug report to cover 400,000 hectares of the Chüy Valley, which stretches across Kyrgyzstan and Kazakhstan.","https://en.wikipedia.org/wiki/Chüy_Valley"]},"caramel":{"common":["Caramel forms when sugar is heated slowly to about 170 °C: the molecules lose water and break into new compounds that bring the colour and flavour.","https://en.wikipedia.org/wiki/Caramel"],"uncommon":["In 1977 pastry chef Henri Le Roux created a salted butter caramel in Quiberon, Brittany, using local demi-sel butter. It was named France's best confectionery in 1980.","https://en.wikipedia.org/wiki/Caramel"],"rare":["Maltol, a key molecule in caramel notes, is named after roasted malt, yet it also occurs naturally in the bark of larch trees and in pine needles.","https://en.wikipedia.org/wiki/Maltol"],"epic":["The word caramel came into English from French and Spanish, and its most likely root is the Late Latin calamellus, meaning sugar cane.","https://en.wikipedia.org/wiki/Caramel"],"legendary":["A 2017 University of Florida study linked salted caramel's popularity to effects on the brain's reward system and to what it called hedonic escalation.","https://en.wikipedia.org/wiki/Caramel"]},"caraway":{"common":["Caraway seeds flavour seeded rye bread, Irish soda bread, British seed cake and sauerkraut, and its leaves can be used like parsley.","https://en.wikipedia.org/wiki/Caraway"],"uncommon":["Caraway oil gives the flavour to kümmel liqueur in Germany and Russia, to Scandinavian akvavit and to Icelandic brennivín.","https://en.wikipedia.org/wiki/Caraway"],"rare":["Caraway 'seeds' are crescent-shaped fruits about 3 mm long with five pale ridges, and up to 7.5% of their weight is volatile oil, mostly S-carvone.","https://en.wikipedia.org/wiki/Caraway"],"epic":["Oxford publicans once kept caraway seeds on a tray for customers who wanted to hide the smell of drink on their breath.","https://en.wikipedia.org/wiki/Caraway"],"legendary":["In Latvia, caraway flavours Jāņi cheese, a sour-milk cheese made for Jāņi, the midsummer festival.","https://en.wikipedia.org/wiki/Caraway"]},"cardamom":{"common":["Cardamom is the world's third most expensive spice by weight, after saffron and vanilla, and growing and harvesting it is highly labour-intensive.","https://en.wikipedia.org/wiki/Cardamom"],"uncommon":["Cardamom is a staple of Nordic baking, flavouring breads such as Norwegian julekake, Swedish kardemummabullar and Finnish pulla.","https://en.wikipedia.org/wiki/Cardamom"],"rare":["In some Middle Eastern countries coffee and cardamom are ground together in a wooden mortar called a mihbaj, giving mixtures of up to 40% cardamom.","https://en.wikipedia.org/wiki/Cardamom"],"epic":["German coffee planter Oscar Majus Kloeffer brought cardamom to Guatemala before the First World War. By 1979 to 1980 Guatemala had overtaken India's output.","https://en.wikipedia.org/wiki/Cardamom"],"legendary":["Cardamom comes from Greek kardamon, cress, plus amomon. The cress word is first attested as ka-da-mi-ja on Mycenaean Linear B tablets.","https://en.wikipedia.org/wiki/Cardamom"]},"carnation":{"common":["In 1907 Anna Jarvis chose the carnation as the emblem of Mother's Day because it was her mother's favourite flower; she picked white for a mother's pure love.","https://en.wikipedia.org/wiki/Dianthus_caryophyllus"],"uncommon":["On 25 April 1974 Lisbon worker Celeste Caeiro handed carnations to rebel soldiers, who put them in their rifle barrels, giving Portugal's Carnation Revolution its name.","https://en.wikipedia.org/wiki/Celeste_Caeiro"],"rare":["Oxford students wear carnations to their exams, and a pink one marks the exams taken between the first and the last.","https://en.wikipedia.org/wiki/Dianthus_caryophyllus"],"epic":["Ohio's state flower is the scarlet carnation, chosen to honour William McKinley, the Ohio president assassinated in 1901, who often wore one on his lapel.","https://en.wikipedia.org/wiki/Dianthus_caryophyllus"],"legendary":["Around 1996 the company Florigene produced Moondust, a blue-mauve carnation, followed in 1998 by a violet variety called Moonshade.","https://en.wikipedia.org/wiki/Dianthus_caryophyllus"]},"carob":{"common":["The carat, used to weigh gemstones, takes its name via the Arabic qīrāṭ from the Greek word for the carob seed, keration.","https://en.wikipedia.org/wiki/Carob"],"uncommon":["Ground carob pods stand in for chocolate in cakes and cookies, and because carob contains no theobromine or caffeine it is sometimes used in dog treats.","https://en.wikipedia.org/wiki/Carob"],"rare":["Carob is called St John's bread from a belief that its seeds and pulp were the 'locusts' and 'honey' that John the Baptist ate in the wilderness.","https://en.wikipedia.org/wiki/Carob"],"epic":["Carob pods were a famine food around the Mediterranean, eaten by the Maltese during famine and war, and on the Iberian Peninsula they were fed to donkeys.","https://en.wikipedia.org/wiki/Carob"],"legendary":["Most carob trees are either male or female, so strictly male trees never produce pods, although some trees are hermaphrodite.","https://en.wikipedia.org/wiki/Carob"]},"carrotseed":{"common":["The garden carrot was bred from the wild carrot, and the two are still the same species, Daucus carota.","https://en.wikipedia.org/wiki/Daucus_carota"],"uncommon":["Wild carrot flowers often hide one dark purple floret in the middle. Legend calls it a drop of Queen Anne's blood from her lace needle; botanists think it mimics an insect to lure pollinators.","https://farmersalmanac.com/what-queen-annes-lace"],"rare":["Wild carrot resembles deadly poison hemlock. Tell them apart by its hairy green stems and carrot-scented root; hemlock has purple-mottled stems and smells foul.","https://en.wikipedia.org/wiki/Daucus_carota"],"epic":["The name Queen Anne's lace is not recorded before 1895, about 180 years after the death of the queen it is said to honour.","https://en.wikipedia.org/wiki/Daucus_carota"],"legendary":["As its seeds ripen, the flower head curls into a bird's-nest shape, and the dried heads can break off; botanists have likened them to tumbleweeds.","https://en.wikipedia.org/wiki/Daucus_carota"]},"cascarilla":{"common":["Cascarilla bark is used to flavour Campari and vermouth, and the bark has also long been used to aid digestion.","https://en.wikipedia.org/wiki/Croton_eluteria"],"uncommon":["Cascarilla is a Spanish diminutive of cascara, bark. In the Bahamas it was called sweet wood bark or Eleuthera bark, after the island where most was gathered.","https://henriettes-herb.com/eclectic/pereira/croton-elut.html"],"rare":["Cascarilla was used as a substitute for cinchona, the fever bark. It was weaker, but its aroma helped it stay down without the vomiting cinchona often caused.","https://henriettes-herb.com/eclectic/pereira/croton-elut.html"],"epic":["In 1693 a German professor reported that the English mixed cascarilla bark into their tobacco to make smoking more pleasant. Burned, the bark gives off a scent compared to vanilla or amber.","https://henriettes-herb.com/eclectic/pereira/croton-elut.html"],"legendary":["Its source long puzzled scholars: in 1737 Dale took it for frankincense bark and Geoffroy for a cinchona, until specimens from the Bahamas' Chief Judge settled it.","https://henriettes-herb.com/eclectic/pereira/croton-elut.html"]},"cedar":{"common":["Atlas cedar grows wild only in the Atlas and Rif mountains of Morocco and Algeria, at 1,170 to 2,200 m, and is listed as Endangered by the IUCN.","https://en.wikipedia.org/wiki/Cedrus_atlantica"],"uncommon":["Morocco's Middle Atlas cedar forests shelter the endangered Barbary macaque. When water is scarce, the monkeys strip cedar bark, which can kill young trees.","https://www.cambridge.org/core/services/aop-cambridge-core/content/view/40D6327C1957632D66AAA8492160C5A6/S0030605309990172a.pdf/decline-of-the-endangered-barbary-macaque-macaca-sylvanus-in-the-cedar-forest-of-the-middle-atlas-mountains-morocco.pdf"],"rare":["Morocco holds the most Atlas cedar on Earth, about 163,000 hectares, and around 80% of it grows in the Middle Atlas.","https://en.wikipedia.org/wiki/Cedrus_atlantica"],"epic":["An Atlas cedar grows on the White House South Lawn, where President Jimmy Carter had a self-supporting tree house built for his daughter Amy.","https://en.wikipedia.org/wiki/Cedrus_atlantica"],"legendary":["In 2003 chemists analysing embalming resin found by a 3,500-year-old Egyptian mummy detected compounds typical of Atlas cedar oil, not juniper.","https://www.spektrum.de/news/zeder-nicht-wacholder/690084"]},"cedrat":{"common":["The citron is one of the original citrus species, and lemons and many limes were created from hybrids that involve it.","https://en.wikipedia.org/wiki/Citron"],"uncommon":["Citron pulp is dry with little or no juice; the prize is the thick white rind, salted to remove bitterness and candied in sugar as succade.","https://en.wikipedia.org/wiki/Citron"],"rare":["Each summer rabbis from around the world travel to Calabria's Riviera dei Cedri to choose flawless citrons, the etrog carried in the Jewish festival of Sukkot.","https://www.timesofisrael.com/in-calabria-rabbis-and-farmers-continue-a-2000-year-old-etrog-tradition/"],"epic":["Pliny the Elder wrote that the citron's smell could penetrate clothing and repel insects, and that the fruit was never eaten but used as an antidote to poisons.","https://en.wikipedia.org/wiki/Citron"],"legendary":["The citron usually pollinates itself, and in every citrus hybrid it is the male parent, never the female.","https://en.wikipedia.org/wiki/Citron"]},"celeryseed":{"common":["Celery salt is simply ground celery seed mixed with salt. The seeds come from the same plant as the salad stalks and are only 1.5 to 2 mm long.","https://en.wikipedia.org/wiki/Celery"],"uncommon":["For people with a celery allergy, exposure to celery can trigger potentially fatal anaphylactic shock.","https://en.wikipedia.org/wiki/Celery"],"rare":["Celery leaves and flower heads were part of the garlands found in the tomb of the pharaoh Tutankhamun.","https://en.wikipedia.org/wiki/Celery"],"epic":["In Homer's Iliad, the horses of Achilles' Myrmidons graze on wild celery growing in the marshes of Troy.","https://en.wikipedia.org/wiki/Celery"],"legendary":["The Greek city of Selinus in Sicily struck coins showing a selinon (celery) leaf on both sides, its civic emblem and a pun on the town's own name.","https://coinweek.com/ancient-coins/plants-and-trees-featured-on-ancient-greek-coins-catawiki/"]},"chamomile":{"common":["In Beatrix Potter's The Tale of Peter Rabbit (1902), after his narrow escape from Mr McGregor's garden, Peter is put to bed by his mother with a dose of camomile tea.","https://standardebooks.org/ebooks/beatrix-potter/short-fiction/text/the-tale-of-peter-rabbit"],"uncommon":["A strong chamomile tea poured over the hair after shampooing is a traditional way to lighten it, and the flowers also give a yellow-brown fabric dye.","https://heritagegarden.uic.edu/german-chamomile-matricaria-recutita"],"rare":["In Spanish, manzanilla means chamomile. The pale sherry of Sanlucar de Barrameda is said to take its name from an aroma reminiscent of chamomile tea.","https://en.wikipedia.org/wiki/Manzanilla_(wine)"],"epic":["The Egypt Centre at Swansea University notes that the body and abdominal cavity of the pharaoh Ramesses II were treated with chamomile oil.","https://egypt.swan.ac.uk/?p=269"],"legendary":["White and yellow chamomile flowers give an inky blue oil: during steam distillation the compound matricin breaks down into blue-violet chamazulene.","https://en.wikipedia.org/wiki/Chamazulene"]},"champaca":{"common":["Champaca flowers are used in worship at home and in temples, and girls and women wear them in their hair as an ornament.","https://en.wikipedia.org/wiki/Magnolia_champaca"],"uncommon":["In Hindu tradition the champaka is one of the five flower-darts of Kamadeva, god of love, and the tree is held particularly sacred to Krishna.","https://flowersofindia.net/mythology.html"],"rare":["In 2021 a presumably native population was found in Yemen, making champaca the only member of the magnolia family known to grow wild in the Arabian Peninsula.","https://en.wikipedia.org/wiki/Magnolia_champaca"],"epic":["The Buddhist commentator Buddhaghosa wrote that the ancient Indian city of Campa was so called because the whole place abounded in large campaka trees.","https://www.uni-goettingen.de/de/camp%c4%81/164347.html"],"legendary":["A Sri Lankan palm civet is said to give off a pleasant scent like champaca flowers, a surprise in a family better known for very unpleasant odours.","https://en.wikipedia.org/wiki/Magnolia_champaca"]},"cherimoya":{"common":["Mark Twain, who is said to have first tasted it in Hawaii, called the cherimoya the most delicious fruit known to man.","https://www.chowhound.com/1737981/mark-twain-favorite-fruit-cherimoya"],"uncommon":["The creamy flesh holds shiny black seeds that can be toxic, so removing them is the first step in preparing the fruit.","https://www.atlasobscura.com/foods/cherimoya"],"rare":["Genetics places the cherimoya's origin in the mountains of Honduras and Guatemala, not the Andes; people carried it to South America about 4,000 years ago.","https://en.wikipedia.org/wiki/Cherimoya"],"epic":["Each flower opens female for about 24 hours, then turns male for only 1 to 1.5 hours, so growers carry pollen from flower to flower with a small paintbrush.","https://crfg.org/wp-content/uploads/How-To-Pollinate-Cherimoya-Presentation.pdf"],"legendary":["The name cherimoya comes from the Quechua word chirimuya, which means cold seeds.","https://en.wikipedia.org/wiki/Cherimoya"]},"cherry":{"common":["The world record for spitting a cherry stone is 28.51 m, set by Brian Krause at the International Cherry Pit-Spitting Championship in Eau Claire, Michigan, in 2003.","https://www.guinnessworldrecords.com/world-records/cherry-stone-spitting-greatest-distance"],"uncommon":["Michigan produces about three quarters of the United States' tart cherries, and Traverse City claims the title Cherry Capital of the World.","https://www.theculturetrip.com/north-america/usa/michigan/articles/michigan-is-home-to-the-cherry-capital-of-the-world"],"rare":["The tale of young George Washington and the cherry tree first appeared in 1806, in the fifth edition of Parson Weems's biography, sourced to an anonymous elderly woman.","https://www.nps.gov/articles/george-washington-and-the-cherry-tree.htm"],"epic":["The Roman commander Lucullus carried cherry saplings home to Rome from the Black Sea coast near Kerasus, today's Giresun, a name some link to the Greek word for cherry.","https://en.wikipedia.org/wiki/Giresun"],"legendary":["In 1987 Traverse City baked a 28,350 lb cherry pie, 17 ft 6 in across, certified by Guinness. Oliver, British Columbia, beat it in 1992 with a 39,683 lb pie.","https://www.roadsideamerica.com/story/29043"]},"cherryblossom":{"common":["Mount Yoshino holds roughly 30,000 cherry trees of about 200 varieties, many donated over the centuries by believers as sacred trees.","https://www.mlit.go.jp/tagengo-db/en/R1-01595.html"],"uncommon":["Tokyo's first 2,000 cherry trees for Washington arrived in 1910 infested with insects and were burned on President Taft's order. A replacement gift of 3,020 trees came in 1912.","https://en.wikipedia.org/wiki/National_Cherry_Blossom_Festival"],"rare":["Yoshino cherries are a hybrid of two species multiplied by grafting, so the trees are genetic clones of each other and share the same pests and diseases.","https://www.smithsonianmag.com/blogs/national-museum-of-natural-history/2022/03/25/the-hybridized-nature-of-washingtons-iconic-cherry-trees/"],"epic":["Kyoto's full-bloom dates, kept in court documents and diaries, go back to 812 CE. On 26 March 2021 the city saw its earliest peak in more than 1,200 years.","https://www.sciencealert.com/japan-s-cherry-blossoms-burst-into-color-sooner-than-they-have-in-1-200-years"],"legendary":["Cherry stones flown to the ISS in 2008 to 2009 grew into a sapling at Ganjoji temple in Gifu that bloomed at 4 years old, perhaps 6 years earlier than usual.","https://thenationalnews.com/world/cherry-tree-from-space-amazes-and-baffles-japan-1.307349"]},"chestnut":{"common":["The Christmas Song, which opens with chestnuts roasting on an open fire, was written in about 45 minutes on a sweltering July afternoon in 1945.","https://performingsongwriter.com/christmas-song/"],"uncommon":["In the Ardeche the chestnut was long known as the bread tree. Its nuts gained AOC status and then European AOP protection in 2014.","https://www.tastefrance.com/us/magazine/meet-makers/ardeche-chestnuts-continue-fly-shelves-and-constantly-reinvent-themselves"],"rare":["The chestnut's name comes from Kastania, a Greek town, while sativa in its botanical name simply means cultivated.","https://trees.stanford.edu/ENCYC/CASsa.htm"],"epic":["When disease hit the Ardeche silk industry, Clement Faugier began making marrons glaces at Privas in 1882, putting jobless textile workers to work on the chestnut harvest.","https://www.connexionfrance.com/article/Mag/Food-and-Drink/Marrons-glaces-sweet-taste-of-success"],"legendary":["On Mount Etna stands the Hundred-Horse Chestnut, perhaps 2,000 to 4,000 years old. Legend says a queen and her 100 knights sheltered beneath it from a storm.","https://en.wikipedia.org/wiki/Hundred_Horse_Chestnut"]},"cinnamon":{"common":["Cinnamon is the tree's inner bark. Peelers scrape off the outer layer and cut the thin inner layer by hand, and it curls into quills as it dries in the shade.","https://www.deccanherald.com/dhie/science/2026/07/23/why-does-cinnamon-thrive-in-sri-lanka"],"uncommon":["Herodotus and Aristotle passed on tales of giant cinnamon birds that built their nests from cinnamon sticks. Pliny later called it a traders' fiction to keep prices high.","https://en.wikipedia.org/wiki/Cinnamon"],"rare":["In 2013 Danish bakers fought EU coumarin limits that threatened their cinnamon rolls. Cheap cassia is rich in coumarin; true Ceylon cinnamon has very little.","https://www.npr.org/sections/thesalt/2013/12/25/256602581/when-is-cinnamon-spice-not-so-nice-the-great-danish-debate"],"epic":["Under the Dutch East India Company, anyone in Ceylon who peeled cinnamon shoots unlawfully faced death or 25 years' banishment to the Cape of Good Hope.","https://www.themorning.lk/articles/cinmcdEIp0kxRnOOSpmd"],"legendary":["Ten of 27 Phoenician flasks, about 3,000 years old, from sites in Israel held cinnamaldehyde, cinnamon's flavour compound, some 5,000 km from the nearest cinnamon lands.","https://www.livescience.com/39011-cinnamon-trade-found-in-israel.html"]},"civet":{"common":["Kopi luwak is made from coffee cherries eaten and passed by the Asian palm civet. Farmed beans retail for up to $100 per kg, and wild ones for about ten times that.","https://en.wikipedia.org/wiki/Kopi_luwak"],"uncommon":["The word civet reached English through French civette, from the Arabic zabad, as in sinnawr al-zabad, the civet cat.","https://en.wikipedia.org/wiki/African_civet"],"rare":["In King Lear, the mad king cries: Give me an ounce of civet, good apothecary, to sweeten my imagination.","https://internetshakespeare.uvic.ca/doc/Lr_Q2/page/69/"],"epic":["Daniel Defoe, author of Robinson Crusoe, once invested in a scheme to raise civets in captivity for their perfume secretion.","https://en.wikipedia.org/wiki/African_civet"],"legendary":["Field biologists lure jaguars to camera traps with a Calvin Klein cologne; its civetone, the key molecule of civet, is thought to resemble a territorial marking.","https://en.wikipedia.org/wiki/Civetone"]},"cloudberry":{"common":["Cloudberries are not grown on a commercial scale, so almost the whole crop is picked by hand from wild bogs and moors.","https://en.wikipedia.org/wiki/Rubus_chamaemorus"],"uncommon":["Finland's 2 euro coin, designed by Raimo Heino, shows the fruit and leaves of the cloudberry, called the golden berry of northern Finland.","https://en.wikipedia.org/wiki/Finnish_euro_coins"],"rare":["Unusually for its genus, the cloudberry is dioecious: a female plant only bears fruit if pollen arrives from a separate male plant.","https://en.wikipedia.org/wiki/Rubus_chamaemorus"],"epic":["Harvesting unripe cloudberries was illegal in Norway from 1970 to 2004, and many Norwegians still believe the rule applies.","https://en.wikipedia.org/wiki/Rubus_chamaemorus"],"legendary":["The caterpillars of the moth Coleophora thulea have no known food plant other than the cloudberry.","https://en.wikipedia.org/wiki/Rubus_chamaemorus"]},"clove":{"common":["Cloves are dried flower buds, picked when they turn bright red, and their name comes from the Latin clavus, a nail, for their shape.","https://en.wikipedia.org/wiki/Clove"],"uncommon":["Clove oil is 72 to 90% eugenol, and there is evidence that it eases toothache pain, its traditional use in dental emergencies.","https://en.wikipedia.org/wiki/Clove"],"rare":["Indonesia's kretek cigarettes are blended with cloves. In the US, clove cigarettes have been classed as cigars since the 2009 ban on flavoured cigarettes.","https://en.wikipedia.org/wiki/Clove"],"epic":["Archaeologists found cloves in a house burned down around 1720 BC at Terqa in Syria, thousands of kilometres from the Indonesian islands where cloves grew.","https://en.wikipedia.org/wiki/Clove"],"legendary":["In 1770 agents of Pierre Poivre stole clove seedlings from Afo, a tree on Ternate perhaps 350 to 400 years old, and took them to Mauritius and the Seychelles.","https://en.wikipedia.org/wiki/Clove"]},"coconut":{"common":["Botanically, the coconut is a drupe, a stone fruit like a peach, not a true nut.","https://en.wikipedia.org/wiki/Coconut"],"uncommon":["The word coconut comes from Spanish and Portuguese coco, a grinning or grimacing face, because the three dents at the base of the shell look like eyes and a mouth.","https://www.etymonline.com/word/coconut"],"rare":["In Sanskrit the coconut palm is called kalpa vriksha, the tree of the necessities of life. Hawaiians hollowed its trunks into drums and small canoes.","https://en.wikipedia.org/wiki/Coconut"],"epic":["Uniquely among trees, the coconut palm can be irrigated with sea water.","https://en.wikipedia.org/wiki/Coconut"],"legendary":["Some farmers in Thailand and Malaysia use southern pig-tailed macaques to pick coconuts; Thailand has trained them for the job for around 400 years.","https://en.wikipedia.org/wiki/Coconut"]},"coffee":{"common":["Legend says an Ethiopian goatherd named Kaldi discovered coffee after his goats grew restless from eating red berries from a coffee shrub.","https://www.mentalfloss.com/food/coffee/who-discovered-coffee"],"uncommon":["A coffee cherry usually holds two seeds, but sometimes only one grows at the branch tips, a rounded single bean called a peaberry.","https://en.wikipedia.org/wiki/Coffea_arabica"],"rare":["Yemen and southern Ethiopia were likely the pioneering regions for coffee cultivation; tradition tells of coffee slips planted at Udein in pre-Islamic times.","https://en.wikipedia.org/wiki/Coffea_arabica"],"epic":["Arabica is itself a hybrid of two wild species, Coffea canephora and C. eugenioides, a cross estimated at 1.08 million to 543,000 years ago.","https://en.wikipedia.org/wiki/Coffea_arabica"],"legendary":["Rare arabica mutants named AC1, AC2 and AC3, after geneticist Alcides Carvalho, contain only 0.76 mg of caffeine per gram of bean.","https://en.wikipedia.org/wiki/Coffea_arabica"]},"cognac":{"common":["To be called cognac, the brandy must be distilled twice in copper pot stills.","https://en.wikipedia.org/wiki/Cognac"],"uncommon":["Cognac must age at least two years in French oak barrels, mostly made from the forests of Limousin and Troncais.","https://en.wikipedia.org/wiki/Cognac"],"rare":["Alcohol evaporating from ageing cognac, the angels' share, feeds a black fungus, Baudoinia compniacensis, that darkens the walls of buildings near the distilleries.","https://en.wikipedia.org/wiki/Baudoinia_compniacensis"],"epic":["Ugni blanc, the most widely used cognac grape, is known locally as Saint-Emilion and in Italy as Trebbiano.","https://en.wikipedia.org/wiki/Cognac"],"legendary":["Oak barrels stop adding flavour after four or five decades, so ageing cognac in wood for longer may bring no benefit.","https://en.wikipedia.org/wiki/Cognac"]},"copaiba":{"common":["Copaiba oleoresin has been used in Brazilian folk medicine since at least the 16th century, swallowed or rubbed on as an ointment.","https://en.wikipedia.org/wiki/Copaiba"],"uncommon":["In 1978 Nobel chemist Melvin Calvin reported that copaiba oleoresin, tapped 15 to 20 litres at a time from a hole in the trunk, could go straight into the tank of a diesel car.","https://news.mongabay.com/bioenergy/2006/09/farmer-experiments-with-exotic-diesel.html"],"rare":["In the Peruvian Amazon near Iquitos, copaiba resin is also used as an insect repellent.","https://en.wikipedia.org/wiki/Copaiba"],"epic":["Ceramic painters mix mineral colours with a medium of copaiba, turpentine and lavender so they stick to the ware before kiln firing.","https://en.wikipedia.org/wiki/Copaiba"],"legendary":["In Yaviza, Panama, newborns are given a mixture made with copaiba resin, meant to impart knowledge and ward off hexes.","https://en.wikipedia.org/wiki/Copaiba"]},"coriander":{"common":["Coriander and cilantro are the same plant: in US English the fresh leaves are called cilantro, a Spanish word from the same Latin root, and the seeds coriander.","https://en.wikipedia.org/wiki/Coriander"],"uncommon":["Variants of the smell-receptor gene OR6A2 make coriander taste like soap to some people; 21% of East Asians and 17% of Europeans in one survey disliked it.","https://en.wikipedia.org/wiki/Coriander"],"rare":["The word coriander may come from Greek koris, a bedbug, a nod to the fetid, bug-like smell of the plant.","https://en.wikipedia.org/wiki/Coriander"],"epic":["About 500 ml of coriander seeds were recovered from Tutankhamun's tomb. Since coriander does not grow wild in Egypt, the Egyptians probably cultivated it.","https://en.wikipedia.org/wiki/Coriander"],"legendary":["Coriander is listed as one of the original ingredients in the secret formula for Coca-Cola.","https://en.wikipedia.org/wiki/Coriander"]},"cork":{"common":["Looking at thin slices of cork under his microscope, Robert Hooke discovered and named the cell. Portugal now harvests about half of the world's cork.","https://en.wikipedia.org/wiki/Cork_(material)"],"uncommon":["Cork bark is harvested every 9 to 12 years, once it is 2.7 to 4 cm thick, and a single cork oak can be stripped 5 to 17 times in its life.","https://en.wikipedia.org/wiki/Quercus_suber"],"rare":["In Portugal, cork oaks cannot legally be cut down, except for forest-management felling of old, unproductive trees.","https://en.wikipedia.org/wiki/Quercus_suber"],"epic":["In the Second World War, when Nazi Germany's blockade cut off cork imports from Europe, the shortage was deemed a threat to US national security.","https://en.wikipedia.org/wiki/Quercus_suber"],"legendary":["The Whistler Tree in Portugal, planted in 1783 or 1784, is listed by Guinness as the largest cork tree in the world; it takes at least three people to hug it.","https://en.wikipedia.org/wiki/Quercus_suber"]},"costus":{"common":["Costus root comes from a purple-flowered thistle in the daisy family, 1 to 2 m tall. Over-collection has put it on CITES Appendix I.","https://en.wikipedia.org/wiki/Dolomiaea_costus"],"uncommon":["A saying attributed to the Prophet Muhammad recommends costus, called qust or kust in Arabic: treat with the Indian incense, for it has healing for seven diseases.","https://en.wikipedia.org/wiki/Dolomiaea_costus"],"rare":["Costus essential oil has a lingering scent that turns into a more unpleasant goat-like smell as it ages.","https://en.wikipedia.org/wiki/Dolomiaea_costus"],"epic":["Romans and Byzantines flavoured wine with costus root. Pliny praised its burning taste and exquisite scent but called it otherwise useless.","https://en.wikipedia.org/wiki/Dolomiaea_costus"],"legendary":["In Ayurvedic lore the root, kushtha in Sanskrit, is considered the brother of the divine Soma, and Kashmiri Rishi mystics especially ate it.","https://en.wikipedia.org/wiki/Dolomiaea_costus"]},"cotton":{"common":["Cotton fibre is almost pure cellulose, about 91% by weight, with most of the rest water.","https://en.wikipedia.org/wiki/Cotton"],"uncommon":["About 85% of the water drawn from Tajikistan's Vakhsh river goes to irrigation, much of it for cotton; the Vakhsh carries about a quarter of the Amu Darya's flow.","https://en.wikipedia.org/wiki/Vakhsh_River"],"rare":["Cotton threads preserved inside a copper bead at Mehrgarh, Pakistan, date to the sixth millennium BC, the earliest known cotton in the Old World.","https://en.wikipedia.org/wiki/Cotton"],"epic":["Herodotus wrote of Indian trees producing wool, and in 1350 John Mandeville described an Indian tree bearing tiny lambs on the ends of its branches.","https://en.wikipedia.org/wiki/Cotton"],"legendary":["China's Chang'e 4 lander carried cotton seeds to the Moon's far side, and on 15 January 2019 China announced that one had sprouted.","https://en.wikipedia.org/wiki/Cotton"]},"creosote":{"common":["When summer monsoon rain soaks the Sonoran Desert, wet creosote bush fills the air with the fragrance many people simply call the smell of rain.","https://www.knau.org/knau-and-arizona-news/2022-06-29/earth-notes-why-the-desert-smells-like-rain"],"uncommon":["Dried creosote leaves, sold as the herbal remedy chaparral, are still widely used in Mexico, though the US FDA warns against taking them internally.","https://en.wikipedia.org/wiki/Larrea_tridentata"],"rare":["Mature creosote roots soak up water so efficiently that seeds landing nearby cannot germinate, which is why the bushes grow so evenly spaced across the desert.","https://en.wikipedia.org/wiki/Larrea_tridentata"],"epic":["The Tohono O'odham boiled the reddish lac that oozes from creosote bush to make a glue for mending broken pottery.","https://en.wikipedia.org/wiki/Larrea_tridentata"],"legendary":["A ring of creosote bush in California's Mojave Desert, known as King Clone, is estimated to be about 11,700 years old.","https://en.wikipedia.org/wiki/Larrea_tridentata"]},"cumin":{"common":["India grows about 70% of the world's cumin, producing 856,000 tons of seed in the 2020-21 fiscal year.","https://en.wikipedia.org/wiki/Cumin"],"uncommon":["Ancient Egyptians used cumin both as a spice and as a preservative in mummification.","https://en.wikipedia.org/wiki/Cumin"],"rare":["Roman emperor Antoninus Pius examined even tiny matters so carefully that, according to Cassius Dio, scoffers nicknamed him the Cummin-splitter.","https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Cassius_Dio/70*.html"],"epic":["Wild cumin seeds were found at Atlit-Yam, a Neolithic village now underwater off the coast of Israel, dating to the early 6th millennium BC.","https://en.wikipedia.org/wiki/Cumin"],"legendary":["Pliny the Elder wrote that followers of the Roman orator Porcius Latro drank a cumin brew to copy their master's pale, scholarly complexion.","https://blogs.ubc.ca/imperiallatinprose/?p=131"]},"cyclamen":{"common":["Cyclamen persicum, the cyclamen most sold by florists, is frost-tender and flowers in winter, in white, pink, red or purple.","https://en.wikipedia.org/wiki/Cyclamen"],"uncommon":["Cyclamen's old English name is sowbread, from the Medieval Latin panis porcinus, pig bread, because pigs were said to eat the plant. Similar names exist in German, French and Dutch.","https://en.wikipedia.org/wiki/Cyclamen"],"rare":["As cyclamen fruit forms, the flower stem coils or bends down towards the soil, and ants later carry off the seeds to eat their sticky coating.","https://en.wikipedia.org/wiki/Cyclamen"],"epic":["In the 16th century, women in the early stages of pregnancy avoided cyclamens for fear that the plant would cause a miscarriage.","https://en.wikipedia.org/wiki/Cyclamen"],"legendary":["Cyclamin, a compound in cyclamen tubers, kills snails: in lab tests 21 mg per litre of water was enough to kill every snail.","https://en.wikipedia.org/wiki/Cyclamin"]},"cypress":{"common":["Sarv-e Abarkuh, a Mediterranean cypress growing in the desert town of Abarkuh in central Iran, is estimated to be over 4,000 years old. Guinness lists it as the oldest cypress.","https://www.guinnessworldrecords.com/world-records/93363-oldest-cypress"],"uncommon":["In summer 1889 at Saint-Rémy, Van Gogh made cypresses the subject of one of his first painting series, likening their shape to an Egyptian obelisk.","https://www.metmuseum.org/art/collection/search/436535"],"rare":["In Greek myth Cyparissus, a favourite of Apollo, accidentally killed his beloved tame stag and was turned into a cypress, weeping sap as tears.","https://en.wikipedia.org/wiki/Cupressus_sempervirens"],"epic":["After a 2012 wildfire scorched about 50,000 acres around Andilla, Spain, a stand of 946 Mediterranean cypresses survived unscathed.","https://theolivepress.es/spain-news/2012/08/26/fireproof-trees-survive-blaze-in-valencia"],"legendary":["In 861 the caliph al-Mutawakkil had the Cypress of Kashmar, said to be planted by Zoroaster, felled; he was murdered before the camels hauling it arrived.","https://en.wikipedia.org/wiki/Cypress_of_Kashmar"]},"cypriol":{"common":["Cypriol oil, known in India as nagarmotha, has been used in Indian perfumery for centuries, especially in traditional attars.","https://premierepeau.com/pages/glossary-terms/cypriol-oil-or-nagarmotha"],"uncommon":["Cypriol's rhizomes grow in marshy, waterlogged soils; they are harvested, dried and steam-distilled into a woody, earthy oil.","https://premierepeau.com/pages/glossary-terms/cypriol-oil-or-nagarmotha"],"rare":["Cypriol belongs to Cyperus, a genus of about 700 sedges that also includes papyrus, the reed the ancient Egyptians made into paper.","https://en.wikipedia.org/wiki/Cyperus"],"epic":["Nagarmotha rhizomes give little oil: a study of Indian samples found yields of 0.20% to 0.58%, the highest from Tilakgram in Madhya Pradesh.","https://agris.fao.org/search/en/records/65df4c2f0f3e94b9e5d71b66"],"legendary":["Botanists say true Cyperus scariosus grows in Papua New Guinea and Australia, not India, where the name is commonly misapplied to Cyperus pertenuis.","https://en.wikipedia.org/wiki/Cyperus_scariosus"]},"date":{"common":["When Muslims break the Ramadan fast with the evening meal, it is traditional to eat a date first.","https://en.wikipedia.org/wiki/Date_palm"],"uncommon":["Date palms grow as separate male and female trees, so growers often pollinate the females by hand, with skilled workers up ladders.","https://en.wikipedia.org/wiki/Date_palm"],"rare":["The palm's species name dactylifera and the English word date both come from a Greek word meaning date, and also finger.","https://en.wikipedia.org/wiki/Date_palm"],"epic":["Guinness lists Saudi Arabia's Al-Ahsa as the world's largest oasis, covering 8,544 hectares and holding more than 2.5 million palm trees.","https://www.guinnessworldrecords.com/world-records/largest-oasis"],"legendary":["In 2005 a date seed about 2,000 years old, found at Herod's palace on Masada, was sprouted. The palm, named Methuselah, later pollinated a female that bore fruit.","https://en.wikipedia.org/wiki/Judean_date_palm"]},"datura":{"common":["Angel's trumpet flowers hang downwards and can grow 14 to 50 cm long and up to 35 cm across at the mouth.","https://en.wikipedia.org/wiki/Brugmansia"],"uncommon":["Most angel's trumpets turn up their fragrance in the evening to attract the moths that pollinate them.","https://en.wikipedia.org/wiki/Brugmansia"],"rare":["The scentless red angel's trumpet, Brugmansia sanguinea, is pollinated only by the sword-billed hummingbird.","https://en.wikipedia.org/wiki/Brugmansia"],"epic":["Rich in scopolamine, angel's trumpet mixed with maize beer and tobacco was used to drug wives and slaves before they were buried alive with their dead lord.","https://en.wikipedia.org/wiki/Brugmansia"],"legendary":["Angel's trumpets are listed as extinct in the wild: the megafauna that likely spread their seeds died out after the Pleistocene, and only human cultivation keeps them alive.","https://en.wikipedia.org/wiki/Brugmansia"]},"davana":{"common":["Davana is one of almost 500 Artemisia species, a genus that also gives wormwood for absinthe and tarragon for French cooking.","https://en.wikipedia.org/wiki/Artemisia_(plant)"],"uncommon":["Davana blossoms are offered to the Hindu god Shiva, and the plant's stalks and leaves are used in garlands and bouquets.","https://en.wikipedia.org/wiki/Artemisia_pallens"],"rare":["In lab studies, high oral doses of davana extract lowered blood glucose in rabbits and rats with raised blood sugar.","https://en.wikipedia.org/wiki/Artemisia_pallens"],"epic":["During the chariot festival of the Narasimha temple at Kadiri in Andhra Pradesh, devotees throw sprigs of davana onto the chariot as it passes.","https://en.wikipedia.org/wiki/Artemisia_pallens"],"legendary":["Pliny says Artemisia was named for Queen Artemisia II of Caria, a botanist who built the Mausoleum and is said to have mixed her husband's ashes into her drink.","https://en.wikipedia.org/wiki/Artemisia_II_of_Caria"]},"ebony":{"common":["Ebony is used for the black keys of pianos, organs and harpsichords, and for the bodies of some clarinets, oboes and piccolos.","https://en.wikipedia.org/wiki/Ebony"],"uncommon":["Gaboon ebony, the blackest of the ebonies, has been used since ancient Egyptian times and is still the wood of choice for orchestral fingerboards and tuning pegs.","https://en.wikipedia.org/wiki/Diospyros_crassiflora"],"rare":["Ebony belongs to Diospyros, a genus of about 750 species that includes the persimmons, and its Greek name is usually read as divine fruit.","https://en.wikipedia.org/wiki/Diospyros"],"epic":["The word ebony comes from the Ancient Egyptian hbny, which passed into English through the Ancient Greek ebenos.","https://en.wikipedia.org/wiki/Ebony"],"legendary":["Taylor Guitars won a 2014 US State Department award after its sustainable ebony mill raised the share of harvested timber it could use from 10% to 100%.","https://en.wikipedia.org/wiki/Taylor_Guitars"]},"edelweiss":{"common":["Since 2002 Austria's 2-cent euro coin has carried an edelweiss; from 1959 to 2001 the one-schilling coin showed a bunch of three.","https://en.wikipedia.org/wiki/Leontopodium_nivale"],"uncommon":["Edelweiss grows at about 1,800 to 3,400 m, and the woolly hairs on its leaves and bracts reduce water loss and block or scatter harmful UV light.","https://en.wikipedia.org/wiki/Leontopodium_nivale"],"rare":["Its genus name Leontopodium comes from the Ancient Greek for lion's paw, and the species name nivale is Latin for snowy.","https://en.wikipedia.org/wiki/Leontopodium_nivale"],"epic":["In 1907 Emperor Franz Joseph I made the edelweiss the emblem of the Imperial-Royal Mountain Troops.","https://en.wikipedia.org/wiki/Leontopodium_nivale"],"legendary":["Edelweiss was written for Broadway in 1959, Hammerstein's last lyric. When Reagan used it to toast Austria's president in 1984, Austrian papers called it kitsch.","https://en.wikipedia.org/wiki/Edelweiss_(song)"]},"elderflower":{"common":["Elderflowers are made into a syrup or cordial diluted with water, flavour liqueurs such as St-Germain, and can be battered and fried as fritters.","https://en.wikipedia.org/wiki/Sambucus_nigra"],"uncommon":["The 2018 wedding cake of Prince Harry and Meghan Markle was a layered lemon and elderflower cake by London baker Claire Ptak.","https://en.wikipedia.org/wiki/Wedding_of_Prince_Harry_and_Meghan_Markle"],"rare":["Elderflowers have no floral nectaries. A 2019 study found their scent, mostly linalool, draws tiny flower thrips that help pollinate them.","https://link.springer.com/article/10.1007/s00425-019-03176-5"],"epic":["The name elder likely comes from the Anglo-Saxon æld, fire, because its hollow young stems were used like bellows to blow air into a fire.","https://en.wikipedia.org/wiki/Sambucus_nigra"],"legendary":["In folklore, cutting down an elder tree released a spirit called the Elder Mother, who would take her revenge.","https://en.wikipedia.org/wiki/Sambucus"]},"elemi":{"common":["Elemi comes from an evergreen tree native to the Philippines that grows up to about 30 m tall; its resin is pale yellow, with a honey-like consistency.","https://en.wikipedia.org/wiki/Canarium_luzonicum"],"uncommon":["Commercially, elemi resin is used mainly in varnishes, lacquers and certain printing inks.","https://en.wikipedia.org/wiki/Canarium_luzonicum"],"rare":["The word elemi seems to come from the Greek enhaemon, an ancient medicine for stopping bleeding. The name once covered several resins, including one from a frankincense tree.","https://en.wikipedia.org/wiki/Canarium_luzonicum"],"epic":["The elemi tree bears thick-shelled nuts whose kernels can be eaten both raw and cooked.","https://en.wikipedia.org/wiki/Canarium_luzonicum"],"legendary":["Elemi oil contains elemicin, which can irritate in high doses, so its concentration in cosmetics does not exceed 1%.","https://en.wikipedia.org/wiki/Canarium_luzonicum"]},"eucalyptus":{"common":["A Tasmanian mountain ash eucalyptus nicknamed Centurion stands about 100.5 m tall, and its species is the tallest flowering plant ever measured.","https://en.wikipedia.org/wiki/Eucalyptus_regnans"],"uncommon":["Australia's Blue Mountains are named for the blue haze over them, believed to come from compounds given off by the eucalyptus forests.","https://en.wikipedia.org/wiki/Eucalyptus"],"rare":["Eucalypts have been planted to drain wet ground and so reduce malaria in places such as Algeria, Lebanon and Sicily.","https://en.wikipedia.org/wiki/Eucalyptus"],"epic":["Eucalyptus trees were brought to California by Australians in the 1850s, during the California Gold Rush.","https://en.wikipedia.org/wiki/Eucalyptus"],"legendary":["Eucalyptus roots can draw up gold from tens of metres underground, and the trees deposit it as tiny particles in their leaves and branches.","https://en.wikipedia.org/wiki/Eucalyptus"]},"fig":{"common":["In the Book of Genesis, Adam and Eve clothe themselves with fig leaves (Genesis 3:7).","https://en.wikipedia.org/wiki/Common_fig"],"uncommon":["Fig flowers bloom hidden inside the fruit, and Smyrna figs only ripen after the fig wasp Blastophaga psenes crawls in to pollinate them; female wasps die inside.","https://en.wikipedia.org/wiki/Common_fig"],"rare":["Fig sap on the skin followed by exposure to ultraviolet light can cause phytophotodermatitis, a potentially serious skin inflammation.","https://en.wikipedia.org/wiki/Common_fig"],"epic":["Rome's first emperor, Augustus, was reputed to have been poisoned with figs from his own garden.","https://en.wikipedia.org/wiki/Common_fig"],"legendary":["Seedless figs from the Neolithic village of Gilgal I, dated to 9400 to 9200 BCE, had to be planted by people, a thousand years before other crops were domesticated.","https://en.wikipedia.org/wiki/Common_fig"]},"fir":{"common":["Balsam fir is one of the most popular Christmas trees, particularly in the northeastern United States.","https://en.wikipedia.org/wiki/Abies_balsamea"],"uncommon":["Canada balsam, the resin of the balsam fir, bends light almost exactly as glass does, so it was used to seal specimens onto microscope slides and to cement lenses without distorting the view.","https://www.dictionary.com/browse/abies%20balsamea"],"rare":["Young balsam firs have smooth grey bark dotted with resin blisters, which tend to spray resin when they burst.","https://en.wikipedia.org/wiki/Abies_balsamea"],"epic":["The Abenaki stuffed balsam fir leaves, needles and wood into pillows, treating them as a cure-all.","https://en.wikipedia.org/wiki/Abies_balsamea"],"legendary":["In 1965 scientists found that paper towels made from balsam fir wood gave off vapours that disrupted insect growth, by mimicking a juvenile hormone.","https://en.wikipedia.org/wiki/Juvabione"]},"frangipani":{"common":["Frangipani flowers are threaded into leis on several Pacific islands; in Hawaii the flower is called melia.","https://en.wikipedia.org/wiki/Plumeria"],"uncommon":["Plumeria rubra is the national flower of Laos, where it is called dok champa, and also of Nicaragua.","https://en.wikipedia.org/wiki/Plumeria"],"rare":["In Indonesia and Malaysia frangipani is planted around cemeteries, in the belief that its scent wards off evil spirits by masking the smell of decay.","https://en.wikipedia.org/wiki/Plumeria"],"epic":["Frangipani flowers have no nectar. Their night scent lures sphinx moths, which carry pollen from bloom to bloom in a fruitless search for a sugary reward.","https://floracostaricensis.myspecies.info/taxonomy/term/19780/descriptions"],"legendary":["The story that frangipani was named after Mercutio Frangipani, a crewman of Columbus, was invented by the perfumer Piesse; the character never existed.","https://en.wikipedia.org/wiki/Plumeria"]},"frankincense":{"common":["In Christian tradition, frankincense was one of the three gifts the Magi brought to the infant Jesus, along with gold and myrrh.","https://en.wikipedia.org/wiki/Frankincense"],"uncommon":["Frankincense trees start giving resin at about 8 to 10 years old and are tapped two or three times a year; the final taps give the best tears.","https://en.wikipedia.org/wiki/Frankincense"],"rare":["In a 2008 study, incensole acetate from frankincense resin lowered anxiety and had antidepressant-like effects in mice by switching on TRPV3, a brain channel also involved in sensing warmth.","https://sciencedaily.com/releases/2008/05/080520110415.htm"],"epic":["Frankincense populations are declining, partly from overexploitation: seeds from heavily tapped trees germinate at a rate of only 16%.","https://en.wikipedia.org/wiki/Frankincense"],"legendary":["Herodotus reported that frankincense was dangerous to harvest because of winged snakes, which could be driven off by burning storax.","https://en.wikipedia.org/wiki/Frankincense"]},"freesia":{"common":["Freesia flowers are mainly used in wedding bouquets, prized for their fragrant, narrow funnel-shaped blooms.","https://en.wikipedia.org/wiki/Freesia"],"uncommon":["Freesia is named after Friedrich Freese (1795-1876), a German botanist and medical practitioner.","https://en.wikipedia.org/wiki/Freesia"],"rare":["Freesia's scent cannot be extracted with solvents, so in the early 1980s chemists at IFF trapped the air around living flowers with headspace technology to decode it.","https://en.wikipedia.org/wiki/Freesia"],"epic":["Modern freesia cultivars are mostly grown professionally in the Netherlands, by about 80 growers.","https://en.wikipedia.org/wiki/Freesia"],"legendary":["The common garden freesias all come from crosses made in the 19th century between just two wild species, Freesia refracta and Freesia leichtlinii.","https://en.wikipedia.org/wiki/Freesia"]},"galbanum":{"common":["Galbanum plants grow plentifully on the mountain slopes of northern Iran, and their resin smells intensely green with a turpentine edge.","https://en.wikipedia.org/wiki/Galbanum"],"uncommon":["Galbanum is named in Exodus 30:34 as one of the ingredients of the ketoret, the sacred incense burned in the Tabernacle and later the Temple in Jerusalem.","https://en.wikipedia.org/wiki/Galbanum"],"rare":["Pliny the Elder credited galbanum with extraordinary cures and claimed that its touch, mixed with oil of spondylium, was enough to kill a snake.","https://en.wikipedia.org/wiki/Galbanum"],"epic":["Galbanum's relative narthex, or giant fennel, shares its scent; in myth Prometheus brought fire to humanity in a torch made from its stalk.","https://en.wikipedia.org/wiki/Galbanum"],"legendary":["In 1858 the dancer Lola Montez recommended a plaster of galbanum and pitch for removing hair, a method much like modern waxing.","https://en.wikipedia.org/wiki/Galbanum"]},"gardenia":{"common":["Billie Holiday's signature gardenia began as a fix: in the early 1940s she scorched her hair with a curling iron, a friend covered it with a gardenia, and she wore one ever after.","https://humanflowerproject.com/gardenias-on-the-left-billie-holiday/"],"uncommon":["Gardenia's ripe fruit holds crocin, the same pigment that colours saffron, and in China it has long given a yellow dye for textiles and sweets.","https://en.wikipedia.org/wiki/Gardenia_jasminoides"],"rare":["Japanese go and shogi boards stand on legs carved like gardenia fruits: kuchinashi, gardenia, sounds like 'no mouth', a hint for onlookers to keep quiet.","https://en.wikipedia.org/wiki/Gardenia_jasminoides"],"epic":["In 1761 John Ellis proposed naming the genus Warneria after Richard Warner, the plant's English owner. Warner declined, so it honours naturalist Alexander Garden.","https://en.wikipedia.org/wiki/Gardenia_jasminoides"],"legendary":["Genipin from gardenia fruit turns blue with amino acids. A 2004 forensic study used it to develop hidden fingerprints on paper as blue prints that also fluoresce.","https://www.ojp.gov/ncjrs/virtual-library/abstracts/genipin-novel-fingerprint-reagent-colorimetric-and-fluorogenic"]},"gentian":{"common":["Gentian root extract flavours bitter liqueurs and aperitifs, among them Avèze from Limousin and Salers from Cantal in France.","https://en.wikipedia.org/wiki/Gentiana_lutea"],"uncommon":["Gentian is named after Gentius, a king of ancient Illyria who was believed to have discovered the plant's tonic powers.","https://en.wikipedia.org/wiki/Gentiana_lutea"],"rare":["Gentian root contains amarogentin, one of the most bitter natural compounds known, which is used as the reference for measuring bitterness.","https://en.wikipedia.org/wiki/Gentiana_lutea"],"epic":["Gentian roots can reach 1 m and 2 kg. Berchtesgaden diggers take only the upper rootstock and wait 7 to 15 years before digging the same plant again.","https://www.berchtesgaden.de/pois/berg-enzianbrennerei-grassl"],"legendary":["Grassl, Germany's oldest gentian distillery, dates to 1692 and still distils in five mountain huts, three of them inside Berchtesgaden National Park.","https://www.berchtesgaden.de/pois/berg-enzianbrennerei-grassl"]},"geranium":{"common":["Rose-scented geranium is distilled on a large scale for perfume, and its oil is sometimes used to stretch or fake far costlier rose oil.","https://en.wikipedia.org/wiki/Pelargonium_graveolens"],"uncommon":["Pelargonium comes from the Greek pelargos, stork, because its long pointed fruits look like a stork's bill. The plant is native to southern Africa.","https://en.wikipedia.org/wiki/Pelargonium_graveolens"],"rare":["Geraniol, the rosy molecule named after geranium, is part of the Nasonov pheromone that honeybees fan from their raised abdomens to guide foragers back to the hive.","https://en.wikipedia.org/wiki/Nasonov_pheromone"],"epic":["On Réunion, Bourbon geranium oil comes from tiny hairs on the leaves: 300 to 400 kg of leaves give just 0.5 to 1 litre, distilled over a wood fire.","https://en.reunion.fr/discover/gastronomy/fragrances-and-spices/bourbon-geranium/"],"legendary":["Japanese beetles that eat petals of the zonal geranium, a Pelargonium cousin, flip onto their backs paralysed within about 30 minutes and lie still for hours.","https://www.greenhousemag.com/news/geraniums-could-hold-key-to-controlling-japanese-beetles"]},"ginger":{"common":["The knobbly ginger we cook is a rhizome, an underground stem, from a leafy plant of the Zingiberaceae family probably native to southeastern Asia.","https://www.britannica.com/plant/ginger"],"uncommon":["In 14th-century England a pound of ginger cost about as much as a whole sheep.","https://en.wikipedia.org/wiki/Ginger"],"rare":["Drying or cooking turns gingerol into shogaol, about 160,000 Scoville units against 60,000, so dried ginger bites harder. Shogaol is named from Japanese shōga.","https://en.wikipedia.org/wiki/Shogaol"],"epic":["The first documented figure-shaped gingerbread biscuits were made at the court of Elizabeth I of England.","https://en.wikipedia.org/wiki/Gingerbread_man"],"legendary":["In 1930 Jamaica ginger extract laced with tricresyl phosphate paralysed tens of thousands of Prohibition drinkers. Blues singers recorded songs like 'Jake Leg Blues'.","https://en.wikipedia.org/wiki/Jamaica_ginger"]},"gingerlily":{"common":["The white ginger lily is Cuba's national flower, called mariposa, butterfly, for the shape of its blooms.","https://en.wikipedia.org/wiki/Hedychium_coronarium"],"uncommon":["The genus name Hedychium joins the Greek hedys, sweet, and chion, snow, a nod to the fragrant white flowers.","https://hortflora.rbg.vic.gov.au/taxon/adaef0ae-5340-11e7-b82b-005056b0018f"],"rare":["In Brazil it is said to have arrived during slavery, when enslaved Africans used its leaves as mattresses. It now grows wild in Rio de Janeiro state.","https://en.wikipedia.org/wiki/Hedychium_coronarium"],"epic":["During Spanish colonial rule, Cuban women are said to have hidden secret messages for the independence cause inside the intricate flower heads of the mariposa.","https://en.wikipedia.org/wiki/Hedychium_coronarium"],"legendary":["In 1874 J. A. Gammie wrote to Charles Darwin that sphinx moths hover over its flowers after dusk, wings vibrating the stamens, as the scent grows stronger.","https://www.darwinproject.ac.uk/letter/DCP-LETT-9609.xml"]},"grainsofparadise":{"common":["Grains of paradise are the pungent seeds of a West African plant in the ginger family. They once spiced hippocras, a wine also flavoured with ginger and cinnamon.","https://www.britannica.com/plant/grains-of-paradise"],"uncommon":["Liberia's coast from Cape Mesurado to Cape Palmas was called the Grain Coast after the early trade in grains of paradise.","https://www.britannica.com/place/Grain-Coast"],"rare":["Portuguese traders called it malagueta pepper. After 1492 the name passed to the newly arrived chilli, whose heat recalled grains of paradise.","https://en.wikipedia.org/wiki/Aframomum_melegueta"],"epic":["An 18th-century act under George III banned grains of paradise from alcoholic drinks, where it gave 'a fictitious strength' to beer and gin, and British imports collapsed.","https://en.wikipedia.org/wiki/Aframomum_melegueta"],"legendary":["In 1469 Afonso V gave Fernão Gomes a Gulf of Guinea trade monopoly, malagueta included, for 100,000 réis a year plus 160 km of new coast explored yearly.","https://en.wikipedia.org/wiki/Aframomum_melegueta"]},"grapefruit":{"common":["Grapefruit juice blocks the gut enzyme CYP3A4, letting more of some drugs, such as certain statins, reach the blood, so labels warn against it.","https://www.fda.gov/consumers/consumer-updates/grapefruit-juice-and-some-drugs-dont-mix"],"uncommon":["Grapefruit arose in 18th-century Barbados as a natural cross of pomelo and sweet orange. A 1750 history of the island described a 'forbidden fruit'.","https://en.wikipedia.org/wiki/Grapefruit"],"rare":["Odet Philippe grew grapefruit at St. Helena on Old Tampa Bay, Florida's first post-colonial commercial grove. The site is now Philippe Park.","https://floridacitrushalloffame.com/?p=5637"],"epic":["Texas's Rio Red grapefruit, released in 1984, was bred by irradiating citrus to trigger mutations. It now makes up about 75% of Texas grapefruit.","https://www.freshplaza.com/article/9865285/texas-a-m-s-radiation-breeding-created-the-rio-red-grapefruit/"],"legendary":["Grapefruit mercaptan, a sulphur molecule in the fruit, can be smelled at about 0.000034 nanograms per litre of air, one of the lowest odour thresholds ever recorded.","https://en.wikipedia.org/wiki/Grapefruit_mercaptan"]},"guaiac":{"common":["In Spanish it is palo santo, holy stick. Despite its density the wood lights easily and gives off a fragrant smoke, and small pieces are burned as incense.","https://en.wikipedia.org/wiki/Bulnesia_sarmientoi"],"uncommon":["Guaiacwood oil smells soft and rosy, like tea roses or violets, and has sometimes been used to adulterate rose oil.","https://en.wikipedia.org/wiki/Oil_of_guaiac"],"rare":["Guaiacwood oil is so rich in guaiol that it is a semi-solid mass at room temperature and melts at around 40 to 50 °C. Once melted, it can stay liquid for a long time.","https://en.wikipedia.org/wiki/Oil_of_guaiac"],"epic":["Palo santo is hard and oily enough to have been made into bearings for ships' propeller shafts, as well as pens, flooring and cigar boxes.","https://cites.org/sites/default/files/eng/cop/15/prop/E-15-Prop-42.pdf"],"legendary":["Dogfish Head built 10,000-gallon fermenting tanks of Paraguayan palo santo, the biggest wooden tanks for North American brewing since before Prohibition.","https://allaboutbeer.com/article/beer-in-holy-wood"]},"guava":{"common":["Calvillo, a town in Aguascalientes, is Mexico's largest guava producer and calls itself the world capital of the guava.","https://en.wikipedia.org/wiki/Calvillo"],"uncommon":["Raw guava holds about 228 mg of vitamin C per 100 g, roughly 254% of the recommended daily value.","https://en.wikipedia.org/wiki/Guava"],"rare":["Guava comes via Spanish guayaba from Taíno, an Arawakan language of the Caribbean, and the word has been in use since the mid-16th century.","https://en.wikipedia.org/wiki/Guava"],"epic":["Guava wood is used to smoke meat in Hawaii and at US barbecue contests, and in Cuba and Mexico the leaves go on the barbecue too.","https://en.wikipedia.org/wiki/Guava"],"legendary":["The Fragrance of Guava is a 1982 book by Colombian writer Plinio Apuleyo Mendoza, made with his friend Gabriel García Márquez.","https://en.wikipedia.org/wiki/Plinio_Apuleyo_Mendoza"]},"hawthorn":{"common":["Hawthorn is the classic farm hedge: its spines and dense branching make it livestock-proof with basic care, and it is the species most used for hedgelaying.","https://en.wikipedia.org/wiki/Crataegus_monogyna"],"uncommon":["Glastonbury's thorn was said to grow from Joseph of Arimathea's staff and flowered twice a year, in spring and after midwinter. The original was felled in the 1640s.","https://en.wikipedia.org/wiki/Crataegus_monogyna"],"rare":["The Hethel Old Thorn in Norfolk, thought to have been planted in the 13th century, is reputed to be over 700 years old, perhaps the oldest hawthorn in Britain.","https://en.wikipedia.org/wiki/Hethel"],"epic":["Hawthorn petals went into spinee, an almond-milk pottage in The Forme of Cury, the recipe roll written around 1390 by Richard II's head chef.","https://en.wikipedia.org/wiki/Crataegus_monogyna"],"legendary":["Among the South Slavs, stakes of hawthorn or blackthorn were thought to work against vampires, and Greeks put hawthorn in windows to keep witches out.","https://en.wikipedia.org/wiki/Crataegus_monogyna"]},"hay":{"common":["Damp baled hay can catch fire on its own: above about 15% moisture, bacteria feeding in the stack heat it until it can reach spontaneous combustion.","https://www.todayifoundout.com/index.php/2014/09/moist-baled-stacked-hay-catch-fire/"],"uncommon":["Part of hay's sweet smell comes from sweet vernal grass, whose coumarin and benzoic acid smell of fresh hay with a hint of vanilla, strongest once dried.","https://en.wikipedia.org/wiki/Anthoxanthum_odoratum"],"rare":["Sweet vernal grass turns up in practically every 10 km square of Britain, and it has been introduced and naturalised far beyond its Eurasian home.","https://en.wikipedia.org/wiki/Anthoxanthum_odoratum"],"epic":["As a farm grass sweet vernal grass gives a low yield, but it can grow on land too acidic for other grasses.","https://en.wikipedia.org/wiki/Anthoxanthum_odoratum"],"legendary":["On ground contaminated by mining, sweet vernal grass is undergoing parapatric speciation, diverging into new forms beside ordinary populations nearby.","https://en.wikipedia.org/wiki/Anthoxanthum_odoratum"]},"hazelnut":{"common":["Turkey grows most of the world's hazelnuts: in 2023 it harvested 650,000 of 1.13 million tonnes in shell, about 58%, far ahead of Italy and the US.","https://en.wikipedia.org/wiki/Hazelnut"],"uncommon":["In Irish myth the Salmon of Knowledge gained all wisdom by eating nine hazelnuts that fell into a well. Young Fionn mac Cumhaill got it by burning his finger on the cooking fish.","https://en.wikipedia.org/wiki/Salmon_of_Knowledge"],"rare":["Hazelnuts drop from their husks seven to eight months after pollination, and orchards may be swept up to three times in one season.","https://en.wikipedia.org/wiki/Hazelnut"],"epic":["The old name cob for a hazelnut comes from a children's game played with a hazelnut tied to a piece of string.","https://en.wikipedia.org/wiki/Hazelnut"],"legendary":["On the Scottish island of Colonsay, a pit held hundreds of thousands of burned hazelnut shells, radiocarbon dated to about 6000 BCE.","https://en.wikipedia.org/wiki/Hazelnut"]},"heather":{"common":["White heather is thought lucky in Scotland. Queen Victoria carried the custom from Balmoral to England, and sprigs still go into bridal bouquets.","https://en.wikipedia.org/wiki/Calluna"],"uncommon":["Heather honey is thixotropic: a jelly until stirred, then it sets again. That makes it hard to extract, so it is often sold in the comb.","https://en.wikipedia.org/wiki/Calluna"],"rare":["Heather's genus name, Calluna, probably comes from the Greek kallýnō, to sweep clean, because its tough stems were bound into besom brooms. It also dyed wool yellow.","https://en.wikipedia.org/wiki/Calluna"],"epic":["In 1769 Thomas Pennant recorded that Islay ale was brewed from young heather tops, two parts heath to one part malt, sometimes with hops.","https://en.wikipedia.org/wiki/Calluna"],"legendary":["Heather nectar contains callunene, which makes the bumblebee parasite Crithidia bombi lose its flagellum, the tail it swims with.","https://en.wikipedia.org/wiki/Calluna"]},"heliotrope":{"common":["Heliotrope comes from the Greek hēlios, sun, and tropos, a turn: the plant was named for the old idea that it turns its flowers to follow the sun.","https://www.etymonline.com/word/heliotrope"],"uncommon":["Gardeners call heliotrope cherry pie for its intense, vanilla-like scent, and the white-flowered form smells of almonds instead.","https://en.wikipedia.org/wiki/Heliotropium_arborescens"],"rare":["Heliotrope contains toxic pyrrolizidine alkaloids that can cause liver failure in grazing animals, known as walking disease or sleepy staggers. It is listed as toxic to horses.","https://en.wikipedia.org/wiki/Heliotropium_arborescens"],"epic":["When the poet Emily Dickinson was buried, a vanilla-scented heliotrope was laid on her coffin.","https://en.wikipedia.org/wiki/Heliotropium_arborescens"],"legendary":["In the 1918 flu pandemic, doctors called the purple-blue tinge of severely ill patients heliotrope cyanosis, after the colour of the flower.","https://en.wikipedia.org/wiki/Heliotropium_arborescens"]},"hibiscus":{"common":["Roselle calyces are a natural source of water-soluble red food dye, and hold enough pectin to make jam without adding any.","https://en.wikipedia.org/wiki/Roselle_(plant)"],"uncommon":["Dried roselle calyces make karkadeh in Egypt, zobo in Nigeria, agua fresca in Mexico and sorrel in the Caribbean, where the drink is spiced with cloves, ginger and bay.","https://en.wikipedia.org/wiki/Roselle_(plant)"],"rare":["Roselle leaves are eaten as well: Burmese cooks fry them with garlic, prawns and green chilli, and in India a variety called gongura is used as food.","https://en.wikipedia.org/wiki/Roselle_(plant)"],"epic":["Roselle is likely native to West Africa. In the 16th and early 17th centuries it spread to Asia and the West Indies, where it became naturalised.","https://en.wikipedia.org/wiki/Roselle_(plant)"],"legendary":["Roselle is also grown for its bast fibre, which is twisted into cordage and used instead of jute to make burlap.","https://en.wikipedia.org/wiki/Roselle_(plant)"]},"hinoki":{"common":["Hōryū-ji in Nara, built of hinoki in the 7th century, has the world's oldest surviving wooden buildings. Its pagoda used wood from a tree felled in 594.","https://www.atlasobscura.com/places/horyu-ji"],"uncommon":["Hinoki pollen, together with that of sugi, the Japanese cedar, is the leading source of allergenic pollen in Japan and a major cause of hay fever there.","https://en.wikipedia.org/wiki/Chamaecyparis_obtusa"],"rare":["Rot-resistant, lemon-scented hinoki is used for noh theatres, baths and masu boxes, and also for table tennis blades.","https://en.wikipedia.org/wiki/Chamaecyparis_obtusa"],"epic":["Hinoki from the Kiso valley was used for the Ise Shrine and is called go-shin-boku, divine trees.","https://en.wikipedia.org/wiki/Chamaecyparis_obtusa"],"legendary":["Hinoki has over 200 cultivars, some under 30 cm tall. Yet 'Nana Gracilis', often sold as a dwarf, has reached 11 m in cultivation in Britain.","https://en.wikipedia.org/wiki/Chamaecyparis_obtusa"]},"honey":{"common":["Honeybees visit about 2 million flowers and fly some 55,000 miles to make one pound of honey. A single worker makes only 1/12 of a teaspoon in her life.","https://extension.illinois.edu/blogs/prairies-perennials/2017-08-19-national-honey-bee-day"],"uncommon":["Bees burn through honey to build comb: a 1946 experiment found that 6.66 to 8.80 kg of honey yields one kilogram of beeswax.","https://en.wikipedia.org/wiki/Beeswax"],"rare":["Worker bees secrete wax from eight glands on the abdomen as flakes about 3 mm across, and some 1,100 flakes make a single gram.","https://en.wikipedia.org/wiki/Beeswax"],"epic":["The Fayum mummy portraits of Roman Egypt were painted in encaustic, with pigments bound in beeswax.","https://en.wikipedia.org/wiki/Beeswax"],"legendary":["The oldest intact beeswax candles north of the Alps were found at Oberflacht in Germany and date to the 6th or 7th century AD.","https://en.wikipedia.org/wiki/Beeswax"]},"honeysuckle":{"common":["Its sweetly vanilla-scented flowers are a significant food for hummingbirds, deer, rabbits and other wildlife.","https://en.wikipedia.org/wiki/Lonicera_japonica"],"uncommon":["Brought to the US from Japan in the early 1800s, Japanese honeysuckle now forms dense thickets and is classed as a noxious weed in 46 states.","https://en.wikipedia.org/wiki/Lonicera_japonica"],"rare":["In Chinese, Japanese honeysuckle is jin yin hua, the gold-silver flower, because each bloom opens white and turns yellow, so both colours hang on the vine at once.","https://www.wetlandpark.gov.hk/en/biodiversity/beauty-of-wetlands/wildlife/lonicera-japonica"],"epic":["Besides gold-silver flower, its other Chinese name is ren dong teng, the winter-enduring vine, and it is used in traditional Chinese medicine.","https://en.wikipedia.org/wiki/Lonicera_japonica"],"legendary":["Like jasmine, Japanese honeysuckle has been used to scent Chinese teas, a practice popularised in the Qing dynasty.","https://en.wikipedia.org/wiki/Lonicera"]},"hops":{"common":["The papery female cones of the hop plant flavour beer and help preserve it, which is why hops displaced older brewing herbs such as bog myrtle.","https://en.wikipedia.org/wiki/Humulus_lupulus"],"uncommon":["In 2023 Žatec and the Landscape of Saaz Hops became a UNESCO World Heritage Site; hop growing around the town is documented since 1348.","https://en.wikipedia.org/wiki/Žatec"],"rare":["Its Latin name lupulus means small wolf, for the way the climbing bine strangles other plants, mainly basket willows, like a wolf attacking a sheep.","https://en.wikipedia.org/wiki/Humulus_lupulus"],"epic":["Hops are first mentioned in 768 CE, when King Pepin donated them to a Paris monastery. Cultivation is first recorded in 859 at a monastery in Freising.","https://en.wikipedia.org/wiki/Humulus_lupulus"],"legendary":["Hops belong to the hemp family and split from Cannabis sativa over 20 million years ago, yet the two still share an estimated 73% of their genomic content.","https://en.wikipedia.org/wiki/Humulus_lupulus"]},"hyacinth":{"common":["In one Greek myth the jealous west wind Zephyrus blew Apollo's discus into young Hyacinthus, and Apollo made a flower spring from his blood, marked AI AI for alas.","https://en.wikipedia.org/wiki/Hyacinth_(mythology)"],"uncommon":["Hyacinth bulbs are packed with needle-like calcium oxalate crystals, and even a little sap on bare skin can set off the fierce rash known as hyacinth itch.","https://www3.ha.org.hk/toxicplant/en/hyacinthus_orientalis.html"],"rare":["In the 18th century Dutch growers offered over 2,000 hyacinth varieties, and in 1807 Thomas Jefferson planted a Monticello bed with double hyacinths in pink, yellow, white and blue.","https://www.monticello.org/encyclopedia/hyacinth"],"epic":["Hyacinth seeds are spread by ants, which haul them to their nests to eat a fatty attachment called an elaiosome and leave the seed behind to sprout.","https://en.wikipedia.org/wiki/Hyacinthus_orientalis"],"legendary":["The first double hyacinth turned up in Peter Voorhelm's Haarlem garden, and one early double, 'Roi de la Grande Bretagne', sold for over 1,000 florins a bulb.","https://oldhousegardens.com/blog/post/in-the-beginning-double-hyacinths-go-from-rejects-to-super-stars"]},"immortelle":{"common":["Immortelle's golden flower clusters keep their colour after picking, which is why it is called an everlasting and is used in dried flower arrangements.","https://en.wikipedia.org/wiki/Helichrysum_italicum"],"uncommon":["Immortelle's genus name, Helichrysum, joins the Greek helios, sun, and chrysos, gold, a fitting name for its small, bright golden-yellow flower heads.","https://en.wikipedia.org/wiki/Helichrysum"],"rare":["Its grey, curry-scented leaves give immortelle its garden name, curry plant, though it is a Mediterranean shrub of the daisy family, Asteraceae, not a spice plant.","https://www.worldplants.ca/display.php?id=4641"],"epic":["Immortelle flowers hold only about 0.1 to 0.17% essential oil, so a tonne of blossoms gives roughly 1 to 1.7 kg of oil.","https://www.mdpi.com/2297-8739/8/10/167/html"],"legendary":["In 2014 an immortelle rush hit Croatia: pickers hoped to earn up to 3,000 kuna a day, and in one week police seized nearly 1,400 kg of illegally picked flowers.","https://www.novilist.hr/?p=272236"]},"iris":{"common":["Iris perfume comes from the rhizome, not the flower, and one tonne of iris root yields only about 2 kg of oil, among the costliest materials in perfumery.","https://en.wikipedia.org/wiki/Orris_root"],"uncommon":["Freshly dug orris holds no irones at all; the violet-scented molecules only form as the dried rhizomes age for three to five years.","https://premierepeau.com/blogs/news/orris-root-perfumerys-5-year-wait-premiere-peau"],"rare":["In 1876 Florence exported about 10,000 tons of dried orris rhizomes to the rest of Europe and to the United States.","https://premierepeau.com/blogs/news/orris-root-perfumerys-5-year-wait-premiere-peau"],"epic":["Florence's giglio emblem was inspired by the white irises growing around the city. After the Guelphs won control in 1266, the colours were reversed to a red flower on white.","https://www.florencewithguide.com/blog/florentine-iris-symbol/"],"legendary":["In 1893 chemists Tiemann and Krüger studied cheap orris oil to find the scent of violets. They named its molecule irone and made alpha-ionone, later shown to be violet's own.","https://www.chm.bris.ac.uk/motm/irone/mot2.htm"]},"jasmine":{"common":["Jasmine oil is roughly 2.5% indole, a molecule that also contributes to the smell of faeces. Neat it smells musty; in traces it reads as rich and floral.","https://cafleurebon.com/indole-in-perfumery-fecal-florals/"],"uncommon":["Egyptian jasmine opens at night from June to December, so families in Gharbia rise around 3 a.m. to gather the blossoms.","https://egyptianstreets.com/2025/09/29/shubra-beloula-the-tiny-egyptian-village-behind-the-worlds-perfumes/"],"rare":["A single jasmine flower weighs about 0.2 g, so it takes some 6,000 picked blossoms to make up one kilogram of flowers.","https://www.givaudan.com/fragrance-beauty/fragrance-ingredients-business/natural-ingredients/jasmine-absolute-egypt"],"epic":["Shubra Beloula, a village about 100 km north of Cairo, produces around 60% of the jasmine used in the world's perfumes.","https://egyptianstreets.com/2025/09/29/shubra-beloula-the-tiny-egyptian-village-behind-the-worlds-perfumes/"],"legendary":["Methyl jasmonate, a molecule from jasmine oil, is also a plant alarm: it can drift through the air from a wounded plant and switch on defences in unharmed neighbours.","https://en.wikipedia.org/wiki/Methyl_jasmonate"]},"juniper":{"common":["Juniper berries are not berries at all but tiny cones with fleshy, fused scales. They take about 18 months to ripen from green to dusky purple-blue.","https://www.first-nature.com/trees/juniperus-communis.php"],"uncommon":["The word gin comes from the Dutch jenever or the French genièvre, both meaning juniper, the berry that still gives the spirit its signature flavour.","https://en.wikipedia.org/wiki/Juniper_berry"],"rare":["Romans used juniper berries as a cheap home-grown stand-in for costly imported pepper, and Pliny the Elder complained that pepper was adulterated with them.","https://www.bionity.com/en/encyclopedia/Juniper_berries.html"],"epic":["Juniper berries of two species that do not grow in Egypt, Juniperus oxycedrus and J. excelsa, were found in the tomb of Tutankhamun, so they must have been imported.","https://en.wikipedia.org/wiki/Juniper_berry"],"legendary":["A common juniper in Finnish Lapland with a trunk under 10 cm tall turned out to be 1,647 years old, the oldest woody plant known in Europe.","https://esa.org/blog/2025/02/05/discovered-the-oldest-plant-in-the-european-continent/"]},"karokarounde":{"common":["In West Africa, karo karounde flowers have been used for centuries to perfume hair, linen and baths.","https://fraterworks.com/products/karo-karounde-truabs"],"uncommon":["Karo karounde flowers are so delicate they must be handled quickly after picking; their absolute is made by solvent extraction of the fresh blooms, as with jasmine.","https://www.fragrenza.com/blogs/notes-in-perfumery/karo-karounde-in-perfumery"],"rare":["Karo karounde, Leptactina senegambica, belongs to the coffee family, Rubiaceae, like gardenia. Described by Joseph Hooker in 1871, it is a shrub of the wet tropics of West Africa.","https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:755248-1"],"epic":["In Labé, Guinea, the SIPAR factory drew on karo karounde covering nearly 400 hectares; in the rainy season there were too many flowers to pick. It stopped in the early 2000s.","https://guineenews.org/2023/07/16/unites-industrielles-a-labandon-sipar-de-labe-le-parfum-perdu-de-la-guinee/"],"legendary":["The original karo karounde absolute was made in tiny amounts, under 50 kg a year, and regulatory pressure has since halted its extraction in Africa.","https://fraterworks.com/products/karo-karounde-truabs"]},"kiwi":{"common":["Kiwifruit was sold in English as the Chinese gooseberry until the 1950s; the exporter Turners & Growers registered the name kiwifruit on 15 June 1959.","https://en.wikipedia.org/wiki/Kiwifruit"],"uncommon":["Kiwifruit vines are either male or female, so growers plant about 1 male vine for every 8 females, and rely on bees to carry the pollen between them.","https://www.ucanr.edu/program/uc-small-farms-network/kiwifruit"],"rare":["Raw kiwifruit contains actinidin, an enzyme that breaks down proteins: it tenderises meat but dissolves gelatine, so a jelly made with raw kiwi will not set.","https://en.wikipedia.org/wiki/Kiwifruit"],"epic":["The first identifiable description of Actinidia chinensis, the kiwifruit vine, is in a Tang dynasty poem by Cen Shen, written more than 1,000 years ago.","https://en.wikipedia.org/wiki/Kiwifruit"],"legendary":["In 2010 the bacterial disease Psa struck Bay of Plenty kiwifruit orchards, hitting gold varieties hardest; the strain found in New Zealand, Italy and Chile was traced to China.","https://en.wikipedia.org/wiki/Kiwifruit"]},"kola":{"common":["Kola nuts hold 2 to 4% caffeine and went into Coca-Cola from 1886; the whole category of cola drinks is named after them.","https://en.wikipedia.org/wiki/Kola_nut"],"uncommon":["In Igbo custom, presenting kola nuts to guests at a gathering is a sign of goodwill, and the nuts are also offered ceremonially to chiefs.","https://en.wikipedia.org/wiki/Kola_nut"],"rare":["In Sierra Leone, women resist-dye cotton gara cloth; on one 1968 cloth the blue came from indigo leaves and the light browns from crushed kola nuts.","https://risdmuseum.org/art-design/collection/gara-cloth-2023445"],"epic":["Kola nuts were traded in West Africa from at least the 11th century, and by the 13th century exports had crossed the Sahara to the Mediterranean coast of North Africa.","https://en.wikipedia.org/wiki/Kola_nut"],"legendary":["A French traveller wrote that after chewing kola, 'the bitterest, our sourest Things taste Sweet', and the nut was used to make poor drinking water taste better.","https://en.wikipedia.org/wiki/Kola_nut"]},"kumquat":{"common":["In Cantonese the gam in the kumquat's name sounds like the word for gold, so the small golden fruits are called money oranges and displayed for wealth at New Year.","https://pages.ucsd.edu/~dkjordan/chin/happiness/OrangeExcursus.html"],"uncommon":["Kumquats are usually eaten whole, skin and all: the peel is the sweet, pulpy part, while the flesh inside is slightly acidic.","https://en.wikipedia.org/wiki/Kumquat"],"rare":["Plant collector Robert Fortune brought kumquats to Europe in 1846 for the London Horticultural Society; botanists later gave them a genus of their own, Fortunella.","https://en.wikipedia.org/wiki/Kumquat"],"epic":["Kumquat trees can survive temperatures as low as -8 °C (18 °F), yet they do best with 6 to 7 hours of direct sunlight a day.","https://en.wikipedia.org/wiki/Kumquat"],"legendary":["On the Greek island of Corfu, kumquats grow mainly near the village of Nimfes; the fruit has PDO status and most of the roughly 140-tonne yearly crop becomes liqueur.","https://www.greekgastronomyguide.gr/en/item/kumquat-corfu/?mode=grid"]},"labdanum":{"common":["Labdanum is the main ingredient perfumers use to build an amber scent and chypre fragrances, prized because it smells like ambergris.","https://en.wikipedia.org/wiki/Labdanum"],"uncommon":["Rockrose seeds sprout best after a blast of heat: in tests, 15 minutes at 90 °C made every seed germinate, an adaptation to the wildfires of Mediterranean scrub.","https://pmc.ncbi.nlm.nih.gov/articles/PMC6473532"],"rare":["Herodotus wrote that ladanon, very fragrant though from a foul-smelling source, was found in the beards of he-goats, and that Arabians burned it as incense more than anything else.","https://lexundria.com/hdt/3.112/mcly"],"epic":["Genesis 37:25 and 43:11 mention labdanum carried from Canaan to Egypt, and some scholars argue the mysterious onycha of Exodus 30:34 was labdanum too.","https://en.wikipedia.org/wiki/Labdanum"],"legendary":["Egyptologist Percy Newberry speculated in 1929 that the false beard worn by Osiris and the pharaohs may first have represented a labdanum-laden goat's beard.","https://en.wikipedia.org/wiki/Labdanum"]},"labradortea":{"common":["Many Native American peoples brewed the leaves into a fragrant tea; European explorers took up the habit, and the shrub is also called Hudson's Bay tea, muskeg tea and swamp tea.","https://en.wikipedia.org/wiki/Rhododendron_groenlandicum"],"uncommon":["Labrador tea grows so slowly that careful pickers take only a single new leaf from each plant every other year, to avoid harming it.","https://en.wikipedia.org/wiki/Rhododendron_groenlandicum"],"rare":["After the Boston Tea Party in 1773, American colonists boycotting English tea brewed homegrown 'Liberty Teas', and Labrador tea was one of the substitutes.","https://www.bostonteapartyship.com/tea-blog/liberty-teas-of-colonial-boston"],"epic":["Before hops became the main flavouring and preservative in beer, Labrador tea was used in Europe to flavour ale.","https://en.wikipedia.org/wiki/Rhododendron_groenlandicum"],"legendary":["In Greenland the plant is called qajaasaq, a name described as meaning 'resembling a kayak'.","https://en.wikipedia.org/wiki/Rhododendron_groenlandicum"]},"lavender":{"common":["The word lavender traces back through Old French lavandre to the Latin lavare, to wash, and blue infusions of the plant were used for bathing.","https://en.wikipedia.org/wiki/Lavandula"],"uncommon":["In 1910 French chemist René-Maurice Gattefossé was burned in a lab explosion and treated the infected wounds with lavender oil, a story that helped launch aromatherapy.","https://roberttisserand.com/2011/04/gattefosses-burn/"],"rare":["In Roman times lavender flowers sold for 100 denarii per pound, roughly a month's wages for a farm labourer.","https://en.wikipedia.org/wiki/Lavandula"],"epic":["The herbes de Provence blend was invented by spice wholesalers in the 1970s; lavender was not used in traditional southern French cooking around 1900 and appears mainly in the North American mix.","https://en.wikipedia.org/wiki/Lavandula"],"legendary":["Spike oil, extracted from the leaves of the lavender species Lavandula latifolia, was first used as a thinner and retardant in oil paints in the 16th century.","https://cameo.mfa.org/wiki/Spike_oil"]},"lemon":{"common":["In 1747 naval surgeon James Lind gave scurvy-stricken sailors on HMS Salisbury two oranges and a lemon a day; one was fit for duty within six days.","https://www.amusingplanet.com/2025/05/james-lind-and-first-clinical-trial.html"],"uncommon":["A true lemon is a hybrid of the citron and the bitter orange; where it first arose is unknown, though northwest India has been proposed.","https://en.wikipedia.org/wiki/Lemon"],"rare":["Lemon juice is about 5 to 6% citric acid, and lemons were the main commercial source of citric acid before fermentation-based processes were developed.","https://en.wikipedia.org/wiki/Lemon"],"epic":["Christopher Columbus brought lemon seeds to Hispaniola on his voyages in 1493, introducing the lemon to the Americas.","https://en.wikipedia.org/wiki/Lemon"],"legendary":["Economists using an 1881 to 1886 inquiry covering every Sicilian town argue the mafia arose to protect lucrative orange and lemon groves from thieves, and found its presence tracked citrus output.","https://www.nottingham.ac.uk/credit/news/papers/1201.aspx"]},"lemongrass":{"common":["Lemongrass belongs to Cymbopogon, the same grass genus as citronella, whose oil is used as an insect repellent, especially against mosquitoes and houseflies.","https://en.wikipedia.org/wiki/Cymbopogon"],"uncommon":["Lemongrass oil mimics the Nasonov pheromone that worker honeybees release to guide each other home, so beekeepers dab it in empty hives to attract swarms.","https://blog.glorybee.com/use-this-one-strange-trick-to-catch-a-swarm/"],"rare":["Lemongrass oil from Cymbopogon flexuosus is an important source of citral, the principal source of beta-ionone, which is used extensively to synthesise vitamin A.","https://patents.google.com/patent/USPP16712P3/en"],"epic":["East Indian lemongrass, Cymbopogon flexuosus, is also called Cochin grass or Malabar grass, and is native to India, Sri Lanka, Burma and Thailand.","https://en.wikipedia.org/wiki/Cymbopogon_flexuosus"],"legendary":["The genus name Cymbopogon comes from the Greek kymbe, boat, and pogon, beard.","https://en.wikipedia.org/wiki/Cymbopogon"]},"lemonmyrtle":{"common":["Aboriginal Australians have long used lemon myrtle in food and as a healing plant, and today it is sometimes called the Queen of the lemon herbs.","https://en.wikipedia.org/wiki/Backhousia_citriodora"],"uncommon":["Lemon myrtle oil is 90 to 98% citral, the highest natural source of the lemony molecule, ahead of litsea cubeba at 70 to 80% and lemongrass at 65 to 85%.","https://www.intechopen.com/chapters/55939"],"rare":["Ferdinand von Mueller gave lemon myrtle its botanical name, Backhousia citriodora, in 1853, after his friend the English botanist James Backhouse.","https://en.wikipedia.org/wiki/Backhousia_citriodora"],"epic":["During the Second World War the Australian soft-drink maker Tarax became the first company to use lemon myrtle oil as a lemon flavouring.","https://en.wikipedia.org/wiki/Backhousia_citriodora"],"legendary":["Lemon myrtle has two oil chemotypes: the common citral type grown for flavouring, and an uncommon citronellal type that can be used as an insect repellent.","https://en.wikipedia.org/wiki/Backhousia_citriodora"]},"licorice":{"common":["Glycyrrhizin, the main sweetener in liquorice root, is 30 to 50 times sweeter than sugar, with a slower onset and a longer finish.","https://en.wikipedia.org/wiki/Liquorice"],"uncommon":["Pontefract in Yorkshire is where liquorice mixed with sugar first became a sweet in the modern way. Liquorice is also nicknamed Spanish, supposedly as Spanish monks grew it at Rievaulx Abbey.","https://en.wikipedia.org/wiki/Liquorice"],"rare":["The genus name Glycyrrhiza comes from Greek words meaning 'sweet root', and the root is harvested in autumn two to three years after planting.","https://en.wikipedia.org/wiki/Liquorice"],"epic":["Liquorice gives tobacco products a natural sweetness and a distinctive flavour that blends readily with the leaf.","https://en.wikipedia.org/wiki/Liquorice"],"legendary":["In 2020 doctors reported that a 54-year-old Massachusetts man who ate a bag and a half of black licorice daily for weeks died after its glycyrrhizic acid crashed his potassium.","https://www.boston.com/news/health/2020/09/23/black-licorice-death"]},"lilac":{"common":["The common lilac was chosen as the state flower of New Hampshire, as a symbol of the hardy character of the people of the Granite State.","https://en.wikipedia.org/wiki/Syringa_vulgaris"],"uncommon":["Common lilac flowers are edible and are used to flavour honeys, sugars and other sweets.","https://en.wikipedia.org/wiki/Syringa_vulgaris"],"rare":["Lilac's genus name, Syringa, comes from the Greek syrinx, a pipe or tube, after the hollow branches of the common lilac.","https://en.wikipedia.org/wiki/Syringa"],"epic":["Lilacs reached northern European gardens from Ottoman gardens; ambassador Busbecq is credited with sending cuttings to the Dutch horticulturist Carolus Clusius about 1562.","https://en.wikipedia.org/wiki/Syringa_vulgaris"],"legendary":["The breeder Victor Lemoine introduced over 153 named lilac cultivars between 1876 and 1927.","https://en.wikipedia.org/wiki/Syringa_vulgaris"]},"lily":{"common":["Every part of a true lily is poisonous to cats: one or two leaves, or pollen licked off the fur, can cause kidney failure within 24 to 72 hours.","https://www.petpoisonhelpline.com/uncategorized/are-lilies-poisonous-to-cats/"],"uncommon":["The white Madonna lily, Lilium candidum, has been linked with the Virgin Mary since at least medieval times and often appears beside her in paintings of the Annunciation.","https://en.wikipedia.org/wiki/Lilium"],"rare":["Lily bulbs are food in East Asia: China's Lanzhou lily is prized for its sweet bulbs, dried bulbs flavour soups, and Japanese cooks use the bulb as yuri-ne.","https://en.wikipedia.org/wiki/Lilium"],"epic":["In the Priest-King fresco at Knossos on Minoan Crete, the figure's crown is covered with white lilies.","https://en.wikipedia.org/wiki/Lilium"],"legendary":["Comparing meiosis in lilies and mice led scientists in 1977 to conclude that very different eukaryotes share a common pattern of chromosome crossing-over.","https://en.wikipedia.org/wiki/Lilium"]},"lime":{"common":["Lime juice holds furocoumarins that react with sunlight: a spill on skin followed by sunshine can redden it within a day and raise blisters within 3 days, a reaction nicknamed margarita burn.","https://poison.org/articles/lime-juice-and-sun-can-cause-skin-rashes"],"uncommon":["British sailors ate citrus, including limes, to prevent scurvy, which is the origin of the nickname limey.","https://en.wikipedia.org/wiki/Lime_(fruit)"],"rare":["Dried limes, called limoo or black lime, are used in Persian cooking and in Iraqi and Eastern Arabian spice blends.","https://en.wikipedia.org/wiki/Lime_(fruit)"],"epic":["Lime juice holds about 47 grams of citric acid per litre, roughly twice as much as grapefruit juice and five times as much as orange juice.","https://en.wikipedia.org/wiki/Lime_(fruit)"],"legendary":["In Mexico's Michoacán the Knights Templar cartel set lime prices and taxed growers; one buyer said he paid about $2,000 a week, roughly 10% of his sales.","https://www.kunc.org/npr-news/2014-05-19/with-cartels-on-the-run-mexican-lime-farmers-keep-more-of-the-green"]},"linden":{"common":["In Britain the linden is called a lime tree, yet it has nothing to do with citrus limes: the name comes from the Middle English lind, meaning flexible.","https://www.ashridgetrees.co.uk/garden-trees/lime-tilia"],"uncommon":["In Proust's Swann's Way, Aunt Léonie dips her little madeleine in an infusion of lime blossom: the linden tisane behind literature's most famous taste memory.","https://standardebooks.org/ebooks/marcel-proust/in-search-of-lost-time/c-k-scott-moncrieff/text/chapter-1-2"],"rare":["Dead bumblebees often litter the ground under flowering silver limes. Botanists now blame late-season nectar running low, not poisonous nectar as once suspected.","https://stories.rbge.org.uk/archives/5389"],"epic":["Most lindens on Berlin's Unter den Linden were cut down in 1934-35 for an S-Bahn tunnel; the rest were felled for firewood in the last days of the war, and today's trees date from the 1950s.","https://en.wikipedia.org/wiki/Unter_den_Linden"],"legendary":["Carl Linnaeus owes his name to a linden: his father took the surname Linnaeus after a lime tree, lind in Swedish, growing in a stone cairn on the family farm at Jonsboda.","https://uu.se/en/linnaeus-garden/our-plants-and-attractions/our-plants/the-jonsboda-lime"]},"lingonberry":{"common":["Swedish meatballs are traditionally served with bright red lingonberries, as whole berries, a sauce or a jam whose sweet-tart taste balances the dish.","https://scandinaviafacts.com/5-great-things-to-serve-with-swedish-meatballs/"],"uncommon":["Sweden's allemansrätten, the right of public access, lets anyone roam the countryside and pick wild berries, and lingonberries ripen across the country in August and September.","https://visitsweden.com/what-to-do/nature-outdoors/nature/blueberries-superfoods-swedish-nature"],"rare":["Lingonberries are rich in benzoic acid, so they keep well without added preservatives, and Swedes stir them raw with sugar into rårörda lingon without any boiling.","https://en.wikipedia.org/wiki/Lingonberry_jam"],"epic":["The species name vitis-idaea means grape of Mount Ida, an old name first used by Theophrastus in the 4th century BC for a shrub on Mount Ida in Anatolia.","https://www.treesandshrubsonline.org/articles/vaccinium/vaccinium-vitis-idaea/"],"legendary":["Each summer thousands of Thai seasonal workers travel to Sweden to pick its wild lingonberries, blueberries and cloudberries.","https://scandasia.com/working-conditions-improve-for-thai-berry-pickers-in-sweden-but-concerns-remain/"]},"lotus":{"common":["Lotus root is eaten across Asia, and every slice reveals a pinwheel of symmetrical air pockets running through it.","https://www.justonecookbook.com/lotus-root-renkon/"],"uncommon":["Lotus leaves are rough with microscopic wax bumps, so water beads up and rolls off, carrying dirt with it. Bonn botanists Barthlott and Neinhuis named it the Lotus-Effect.","https://www.fuveszkert.u-szeged.hu/lotus-effect"],"rare":["Sacred lotus flowers heat themselves to between 30 and 35 °C, holding that range on a cold 10 °C day and even when the daytime heat reaches 45 °C.","https://www.botany.one/nelumbo-nucifera/"],"epic":["A UCLA team led by Jane Shen-Miller recovered sacred lotus seeds from a dry lake bed in north-eastern China, and one almost 1,300 years old sprouted.","https://www.chemistry.ucla.edu/news/scientists-sequence-genome-sacred-lotus/"],"legendary":["On Myanmar's Inle Lake, weavers pull fine filaments from lotus stems and roll them into thread by hand; pure lotus cloth is so rare it can sell for up to US$400.","https://thetextileatlas.com/craft-stories/lotus-weaving-myanmar"]},"lotv":{"common":["Every part of lily of the valley is poisonous: it holds cardiac glycosides such as convallatoxin, which act on the heart much like digitalis.","https://www.medicinenet.com/lily_of_the_valley/article.htm"],"uncommon":["France's May Day muguet custom is traced to 1 May 1561, when Charles IX received a sprig and gave lily of the valley to every lady at his court.","https://www.frenchentree.com/blog/muguet-a-mayday-tradition-dating-back-to-1561/"],"rare":["No usable essential oil can be extracted from lily of the valley, so perfumers rebuild its scent from synthetics such as hydroxycitronellal.","https://premierepeau.com/pages/glossary-terms/lily-of-the-valley"],"epic":["In Sussex legend, St Leonard fought a dragon in St Leonard's Forest, and lilies of the valley grew where his blood fell; part of the forest is still called the Lily Beds.","https://wikishire.co.uk/wiki/St_Leonards_Forest"],"legendary":["Bourgeonal, a molecule that smells of lily of the valley, attracts human sperm in the lab: a 2003 study found sperm carry a smell receptor, OR1D2, and swim towards it.","https://en.wikipedia.org/wiki/Bourgeonal"]},"lychee":{"common":["Lychees belong to the soapberry family with rambutans and longans, and have been grown in southern China and northern Vietnam for more than 3,000 years.","https://foodprint.org/?p=15827"],"uncommon":["Lychee shares 12 aroma compounds with Gewürztraminer wine; the most potent is cis-rose oxide, which also lends the wine its rose-petal smell.","https://www.winewithseth.com/winewiki/tropical-fruit-aromas/"],"rare":["Tang emperor Xuanzong had relays of galloping horses rush fresh lychees over 700 km to the capital for his consort Yang Guifei, a scene Du Mu recalled in his poem Passing Huaqing Palace.","https://saigoneer.com/saigon-food-culture/13698-the-wild,-wondrous-history-of-lychee"],"epic":["Exiled to Huizhou in Guangdong, the Song poet Su Dongpo wrote that if he could eat 300 lychees a day, he would gladly live on in the far south for good.","https://www.theworldofchinese.com/2020/03/food-fit-for-a-poet/"],"legendary":["A 2017 Lancet study traced a deadly yearly brain illness in children of Muzaffarpur, India, to lychee toxins that crash blood sugar in undernourished kids who ate fallen fruit.","https://www.foodnavigator.com/Article/2017/04/11/Lychees-to-blame-for-hundreds-of-mysterious-child-deaths-in-Bihar/"]},"macadamia":{"common":["Macadamias are Australian natives. Hawaiʻi's crop began in 1882, when William Purvis planted imported seeds at Kapulena on the Hāmākua Coast.","https://imagesofoldhawaii.com/the-perfect-nut"],"uncommon":["Macadamias are the world's hardest edible nut to crack: the shell needs a force of around 2,000 newtons and is five times harder than a hazelnut shell.","https://en.wikipedia.org/wiki/Macadamia"],"rare":["Macadamias are toxic to dogs: even a small amount can cause back-leg weakness, vomiting and diarrhoea, and severe cases with shaking or fever need a vet hospital.","https://www.aspca.org/news/animal-poison-control-alert-macadamia-nuts-are-toxic-dogs"],"epic":["In 2014 a Korean Air vice president, served macadamias in a bag instead of on a plate, had her jet return to the gate at New York's JFK; she was later jailed for it.","https://en.wikipedia.org/wiki/Nut_rage_incident"],"legendary":["DNA studies traced most Hawaiian macadamia varieties, the source of about 70% of those grown worldwide, to a wild population, maybe a single tree, at Mooloo near Gympie.","https://qaafi.uq.edu.au/node/5801"]},"mace":{"common":["Grenada's flag carries a nutmeg, the islands' signature export; Grenada is the world's second-largest nutmeg producer after Indonesia.","https://en.wikipedia.org/wiki/Flag_of_Grenada"],"uncommon":["Mace is the lacy, bright red web wrapped around the nutmeg seed; peeled off and dried, it turns orange-gold.","https://solidstarts.com/foods/mace/"],"rare":["Hurricane Ivan's 2004 strike on Grenada did about US$11.2 million of damage to the nutmeg crop, the largest single crop loss on the island.","https://cimh.edu.bb/~monthly/CarAgMet2/impacts/Grenada_Gren/1/Ivan_impact.htm"],"epic":["To monopolise nutmeg and mace, then grown only on the Banda Islands, the Dutch East India Company conquered them in 1621; about 15,000 islanders were cut to about 1,000.","https://en.wikipedia.org/wiki/Dutch_conquest_of_the_Banda_Islands"],"legendary":["Under the 1667 Treaty of Breda, the Dutch gave up their claim to Manhattan in exchange for England's claim to Run, a nutmeg island about 3 km long.","https://spiceislandsblog.com/2017/07/30/the-forgotten-indonesian-island-that-was-swapped-for-manhattan/"]},"magnolia":{"common":["Magnolias are so ancient, with family fossils dating back 95 million years, that they are thought to have evolved to be pollinated by beetles before bees existed.","https://en.wikipedia.org/wiki/Magnolia"],"uncommon":["Magnolia honours Pierre Magnol of Montpellier, the botanist who in 1689 set out the idea of grouping plants into families by their shared features.","https://en.wikipedia.org/wiki/Pierre_Magnol"],"rare":["The southern magnolia is Mississippi's state tree and Louisiana's state flower; the national champion, in Smith County, Mississippi, stands 37 m tall.","https://en.wikipedia.org/wiki/Magnolia_grandiflora"],"epic":["Mark Catesby brought the southern magnolia to Britain in 1726, and the first young plants propagated from it in England sold for five guineas each.","https://en.wikipedia.org/wiki/Magnolia_grandiflora"],"legendary":["A White House magnolia planted in honour of Rachel Jackson appeared on the back of the US $20 bill from 1928 to 1998; it was removed in 2025.","https://en.wikipedia.org/wiki/Jackson_Magnolia"]},"mahogany":{"common":["Mahogany's huge trunks give wide reddish boards, and its colour, durability and workability made it known as the premier cabinetwood of the world.","https://en.wikipedia.org/wiki/Mahogany"],"uncommon":["Belize's coat of arms shows two woodcutters with axe and paddle beneath a mahogany tree, over the motto Sub Umbra Floreo: under the shade I flourish.","https://www.worldatlas.com/webimage/countrys/namerica/camerica/belize/bzsymbols.htm"],"rare":["Philip II of Spain used mahogany for joinery at El Escorial from 1584, and in 1622 Spain declared a royal monopoly on it for shipbuilding in Havana.","https://en.wikipedia.org/wiki/Mahogany"],"epic":["After Britain's Naval Stores Act of 1721 dropped duties on colonial timber, its mahogany imports rose from 525 tons in 1740 to over 30,000 tons in 1788.","https://en.wikipedia.org/wiki/Mahogany"],"legendary":["Mahogany first appears in print around 1670 as Mohogeney; its origin is still debated, with one theory tracing it to the Yoruba word oganwo via enslaved Africans.","https://en.wikipedia.org/wiki/Mahogany"]},"mandarin":{"common":["The tangerine, a kind of mandarin, is named after Tangier in Morocco: the word first meant of Tangier and was applied to mandarins shipped from that port.","https://en.wikipedia.org/wiki/Tangerine"],"uncommon":["The mandarin is one of the original wild citrus species, and the sweet orange is a hybrid of mandarin and pomelo.","https://en.wikipedia.org/wiki/Mandarin_orange"],"rare":["Mandarins in Canadian Christmas stockings trace back to 1880s New Year gifts sent to Japanese immigrants; shipments came in boxcars painted orange.","https://en.wikipedia.org/wiki/Mandarin_orange"],"epic":["The clementine arose in the garden of Brother Clément Rodier's orphanage at Misserghin, Algeria, and was formally named after him in 1902.","https://en.wikipedia.org/wiki/Clementine"],"legendary":["Aged mandarin peel, chenpi, from Xinhui gains value for decades: in late 2014, 65-year-old peel fetched about 23,000 yuan per tael.","https://en.wikipedia.org/wiki/Chenpi"]},"mango":{"common":["The mango is the national fruit of India, Pakistan and the Philippines, and India grows about 43% of the world's mangoes, mangosteens and guavas.","https://en.wikipedia.org/wiki/Mango"],"uncommon":["Mango sap, leaves and skin can cause an itchy rash, and people sensitive to urushiol, the irritant in poison ivy, are most at risk.","https://en.wikipedia.org/wiki/Mango"],"rare":["The Alphonso mango is named after Afonso de Albuquerque, viceroy of Portuguese India, and Jesuits in Goa brought the grafting that let it be reproduced.","https://en.wikipedia.org/wiki/Alphonso_mango"],"epic":["The Mughal emperor Akbar, who reigned from 1556 to 1605, is said to have planted an orchard of 100,000 mango trees near Darbhanga in eastern India.","https://en.wikipedia.org/wiki/Mango"],"legendary":["In 1968 Mao gave a box of mangoes from Pakistan's foreign minister to Beijing workers. The fruit was preserved in formaldehyde and wax replicas were paraded across China like relics.","https://en.wikipedia.org/wiki/Mango_cult"]},"manuka":{"common":["Mānuka honey is made by honeybees foraging on mānuka flowers, and New Zealand exported about NZ$387 million worth of it in 2024.","https://en.wikipedia.org/wiki/M%C4%81nuka_honey"],"uncommon":["Mānuka honey's prized methylglyoxal (MGO) forms from dihydroxyacetone, a compound that occurs naturally in mānuka nectar.","https://en.wikipedia.org/wiki/M%C4%81nuka_honey"],"rare":["New Zealand produces about 1,700 tonnes of mānuka honey a year, yet roughly six times that amount is marketed around the world as mānuka.","https://en.wikipedia.org/wiki/M%C4%81nuka_honey"],"epic":["In 1773 Captain Cook's crew brewed New Zealand's first beer in Dusky Sound to fight scurvy, flavoured with rimu leaves and leaves of the 'tea plant', mānuka.","https://www.odt.co.nz/lifestyle/food-wine/brew-recalls-drop-which-spruced-cooks-crew"],"legendary":["Kākāriki parakeets chew mānuka and kānuka leaves and bark, then rub them into their feathers to deal with parasites.","https://en.wikipedia.org/wiki/Leptospermum_scoparium"]},"maple":{"common":["The sugar maple's leaf is a symbol of Canada and sits on its flag, and Canada makes more than 75% of the world's maple syrup.","https://en.wikipedia.org/wiki/Maple_syrup"],"uncommon":["In 2011 and 2012 thieves stole nearly 3,000 tonnes of maple syrup, worth C$18.7 million, from a Quebec producers' warehouse, trucking it off to Vermont and New Brunswick.","https://en.wikipedia.org/wiki/Great_Canadian_Maple_Syrup_Heist"],"rare":["Indigenous peoples of north-eastern North America, the first known maple syrup makers, celebrated the Sugar Moon, the first full moon of spring, with a Maple Dance.","https://en.wikipedia.org/wiki/Maple_syrup"],"epic":["Before the Civil War, US abolitionists used maple sugar and syrup because most cane sugar and molasses was produced by enslaved people in the South.","https://en.wikipedia.org/wiki/Maple_syrup"],"legendary":["Maple syrup urine disease is named for the maple smell of affected babies' urine and earwax, caused by sotolon; up to 1 in 200 Old Order Mennonite births are affected.","https://en.wikipedia.org/wiki/Maple_syrup_urine_disease"]},"massoia":{"common":["Massoia bark oil is about 68% massoia lactone, a molecule with a dense, creamy smell of coconut.","https://premierepeau.com/pages/glossary-terms/massoia"],"uncommon":["Stripping massoia bark kills the tree, so synthetic massoia lactone has largely replaced the natural oil.","https://en.wikipedia.org/wiki/Massoia_lactone"],"rare":["The same coconut-like massoia lactone also turns up in cane sugar molasses, cured tobacco, sweet osmanthus flowers and blackberries.","https://premierepeau.com/pages/glossary-terms/massoia"],"epic":["In Java and Bali, women made a warming body ointment from massoia bark and rubbed it on after childbirth.","https://premierepeau.com/pages/glossary-terms/massoia"],"legendary":["Massoia oil and pure massoia lactone are prohibited by the perfume body IFRA: the lactone irritated skin so badly that standard sensitisation tests could not be completed.","https://premierepeau.com/pages/glossary-terms/massoia"]},"mastic":{"common":["The word mastic comes, indirectly, from the Ancient Greek mastichē, which may be related to a Greek verb meaning to chew.","https://en.wikipedia.org/wiki/Mastic_(plant_resin)"],"uncommon":["From July, Chios growers cut the bark of the mastic trees with an iron tool; once the resin hardens, women gather the tears, picking the largest first.","https://ich.unesco.org/en/RL/know-how-of-cultivating-mastic-on-the-island-of-chios-00993"],"rare":["During the Chios massacre of 1822 the mastic villages were spared, because their people supplied mastic to the Ottoman Sultan and his harem.","https://lykourinos.students.acg.edu/Temp/masticvillages.html"],"epic":["In 2014 UNESCO added the know-how of cultivating mastic on Chios, passed from older villagers to the young, to its list of the Intangible Cultural Heritage of Humanity.","https://ich.unesco.org/en/RL/know-how-of-cultivating-mastic-on-the-island-of-chios-00993"],"legendary":["A 1998 paper in the New England Journal of Medicine was titled Mastic gum kills Helicobacter pylori, the bacterium behind most stomach ulcers.","https://en.wikipedia.org/wiki/Mastic_(plant_resin)"]},"mate":{"common":["Maté is sipped from a hollowed gourd filled about three-quarters with leaves, topped with water at 70 to 80 °C and drunk through a straw called a bombilla.","https://en.wikipedia.org/wiki/Yerba_mate"],"uncommon":["Maté is a holly: Ilex paraguariensis belongs to the holly genus Ilex and grows from a shrub into a tree up to about 15 m tall.","https://en.wikipedia.org/wiki/Yerba_mate"],"rare":["Uruguay is the world's biggest maté drinker, at about 10 kg per person a year, double Argentina's roughly 5 kg.","https://en.wikipedia.org/wiki/Yerba_mate"],"epic":["Maté seeds are so hard to sprout that the Jesuit missions, drawing on Guaraní knowledge, fed them to farm birds to wear down the shells, and became the first to domesticate the plant.","https://daily.jstor.org/plant-of-the-month-yerba-mate/"],"legendary":["Maté is popular among Druze and Alawite communities in Syria and Lebanon, a habit brought home by 19th-century Syrian emigrants to Argentina.","https://en.wikipedia.org/wiki/Yerba_mate"]},"melon":{"common":["In May 2026 two Yubari King melons sold at the season's first auction in Sapporo for a record ¥5.8 million.","https://en.wikipedia.org/wiki/Yubari_King"],"uncommon":["The cantaloupe takes its name from Cantalupo, a papal summer estate where these melons were first grown in the 18th century; the word reached English in 1739.","https://en.wikipedia.org/wiki/Cantaloupe"],"rare":["Cavaillon's melon has its own order of knights: the Confrérie des chevaliers de l'ordre du melon, founded in 1988, which joins the town's melon festival each July.","https://fr.wikipedia.org/wiki/Melon_de_Cavaillon"],"epic":["In 1943, after a worldwide search, a mouldy cantaloupe from a market in Peoria, Illinois, yielded the highest-producing penicillin mould strain.","https://en.wikipedia.org/wiki/Cantaloupe"],"legendary":["In 1864 Alexandre Dumas gave Cavaillon's library his published works in exchange for a lifetime annuity of 12 melons a year, paid until his death in 1870.","https://fr.wikipedia.org/wiki/Melon_de_Cavaillon"]},"mimosa":{"common":["Sprigs of mimosa are given to women on International Women's Day in Italy, Albania, Russia and Georgia.","https://en.wikipedia.org/wiki/Acacia_dealbata"],"uncommon":["The Riviera's famous mimosa is an Australian wattle: the first Acacia dealbata was planted in a Cannes garden in 1864, and by 1880 it lined the boulevards of Cannes.","https://acacia-world.net/index.php/europe/acacias-introduction-to-france"],"rare":["Mimosa's feathery leaves are made of tiny leaflets that fold up at night, and also in strong heat.","https://fr.wikipedia.org/wiki/Mimosa_d'hiver"],"epic":["Mimosa is a pyrophyte: the heat of a wildfire opens its pods and releases seeds that germinate in the burnt ground.","https://fr.wikipedia.org/wiki/Mimosa_d'hiver"],"legendary":["Henri Matisse, who lived in Nice and painted mimosa, designed a mimosa rug, his only carpet design, made in an edition of 500.","https://fr.wikipedia.org/wiki/Mimosa_d'hiver"]},"mint":{"common":["Menthol does not chill your skin: it switches on TRPM8, the nerve receptor that normally fires when temperatures drop below about 20 to 26 °C, so the brain reads cold.","https://en.wikipedia.org/wiki/TRPM8"],"uncommon":["Peppermint is a hybrid of watermint and spearmint; it is usually sterile, produces no seeds and spreads by runners.","https://en.wikipedia.org/wiki/Peppermint"],"rare":["Peppermint was first identified by a Dr Eales in Hertfordshire, England, and the botanist John Ray published the find in 1696.","https://en.wikipedia.org/wiki/Peppermint"],"epic":["In Greek myth Minthe, a nymph loved by Hades, became mint: Strabo says a jealous Persephone transformed her, while Oppian says Demeter trampled her.","https://en.wikipedia.org/wiki/Minthe"],"legendary":["Todd's Mitcham, a peppermint that resists verticillium wilt, came from an atomic gardening breeding programme at Brookhaven National Laboratory begun in the mid-1950s.","https://en.wikipedia.org/wiki/Peppermint"]},"molle":{"common":["The pink peppercorns in many spice blends are molle berries, yet the tree is unrelated to the black pepper vine, Piper nigrum.","https://en.wikipedia.org/wiki/Schinus_molle"],"uncommon":["California's oldest pepper tree grew from seeds a sailor brought from Peru to Mission San Luis Rey in 1830. Planted by Father Antonio Peyri, it still stands.","https://www.hmdb.org/m.asp?m=295218"],"rare":["The molle tree secretes a fragrant resin once known as American mastic, long valued for therapeutic uses.","https://trees.stanford.edu/ENCYC/SCHmo.htm"],"epic":["The Inca used oil from the leaves of the molle tree in early mummification, and the earlier Wari state brewed chicha from its fruit.","https://en.wikipedia.org/wiki/Schinus_molle"],"legendary":["In 16th-century Mexico the tree already had a Nahuatl name, pelonquauitl. Tradition says Viceroy Mendoza sent seeds from Peru after 1550, but no document proves it.","https://masaamerica.com/2022/07/18/pulque-curado-tolonche/"]},"mulberry":{"common":["White mulberry leaves are the preferred food of silkworms, and China began growing the tree to feed them more than 4,700 years ago.","https://en.wikipedia.org/wiki/Morus_alba"],"uncommon":["In Ovid's tale of Pyramus and Thisbe, white mulberries turned dark red with the lovers' blood. Shakespeare parodied the story in A Midsummer Night's Dream.","https://www.moruslondinium.org/research/faq"],"rare":["James I planted several acres of mulberries where Buckingham Palace garden now lies, hoping to start English silk. He chose black mulberries, but silkworms thrive on white.","https://onlondon.co.uk/vic-keegans-lost-london-112-james-is-mulberry-tree-mistake"],"epic":["Marco Polo reported that Kublai Khan's paper money was made from the bark of the mulberry tree, pressed into black, paper-like sheets.","https://www.cabinet.ox.ac.uk/node/6959"],"legendary":["White mulberry stamens catapult their pollen in about 25 microseconds at roughly half the speed of sound, the fastest known movement in the plant kingdom.","https://en.wikipedia.org/wiki/Morus_alba"]},"musk":{"common":["Natural musk comes from the musk pod, a gland in a pouch under the belly skin of the male musk deer. Only the males produce it.","https://en.wikipedia.org/wiki/Musk"],"uncommon":["The first synthetic musk was found by accident in 1888, when chemist Albert Baur was trying to make a more effective form of the explosive TNT.","https://en.wikipedia.org/wiki/Synthetic_musk"],"rare":["The word musk comes via Persian from Sanskrit muska, testicle, because the deer's gland was thought to look like a scrotum.","https://en.wikipedia.org/wiki/Musk"],"epic":["Builders once mixed musk into the mortar of mosques, so the walls gave off the scent when the sun heated them.","https://dev.rubinmuseum.org/spiral/aromatic-landscape"],"legendary":["Male Kashmir musk deer grow fang-like tusks for rutting fights. Last recorded in Afghanistan in 1948, the species was confirmed there again some 60 years later.","https://www.nbcnews.com/science/weird-science/vampire-bambi-rare-fanged-deer-confirmed-afghanistan-after-60-years-n240446"]},"myrrh":{"common":["Myrrh is one of the three gifts, with gold and frankincense, that the Gospel of Matthew says the Magi brought to the infant Jesus.","https://en.wikipedia.org/wiki/Myrrh"],"uncommon":["In Ovid's Metamorphoses, Myrrha is turned into a tree and keeps weeping. Her tears become myrrh, and the infant Adonis is born from the split trunk.","https://eclecticlight.co/2017/11/03/changing-stories-ovids-metamorphoses-on-canvas-54-the-making-of-myrrh/"],"rare":["Queen Hatshepsut's expedition to Punt brought home thirty-one live myrrh trees, roots packed in baskets: the first recorded attempt to transplant foreign trees.","https://solarspell-dls.sfis.asu.edu/mea/wikipedia/wp/h/Hatshepsut.htm"],"epic":["Herodotus wrote that Egypt's priciest embalming filled the body cavity with the purest crushed myrrh, cassia and every spice except frankincense.","https://www.livius.org/sources/content/herodotus/mummification/"],"legendary":["In 1996, University of Florence scientists found two myrrh compounds, furanoeudesma-1,3-diene and curzarene, that eased pain in mice by acting on opioid receptors.","https://archive.archaeology.org/9605/newsbriefs/myrrh.html"]},"myrtle":{"common":["Myrtle was sacred to Aphrodite. In one of Aesop's fables, when the gods chose their trees, Jupiter took the oak and Venus the myrtle.","https://ftp.theoi.com/Olympios/AphroditeTreasures.html"],"uncommon":["Queen Victoria planted a sprig of myrtle at Osborne House, and since her daughter's wedding in 1858 royal brides have carried myrtle in their bouquets.","https://themortonreport.com/home-away/gardening/royal-wedding-myths-dispelled/"],"rare":["Mirto, the liqueur of Sardinia and Corsica, is made by soaking myrtle berries in alcohol. Legend credits Sardinian bandits with carrying the custom to Corsica.","https://en.wikipedia.org/wiki/Mirto_(liqueur)"],"epic":["Hadassah, the Hebrew name given to Queen Esther in the Book of Esther, means myrtle.","https://en.wikipedia.org/wiki/Hadassah"],"legendary":["Roman legend says Romans and Sabines made peace at the shrine of Venus Cloacina, goddess of Rome's great sewer, purifying themselves with myrtle branches.","https://en.wikipedia.org/wiki/Cloacina"]},"narcissus":{"common":["Narcissus is also the Greek youth who died of love for his own reflection. In Ovid's telling, his body is replaced by a flower with white petals around a yellow heart.","https://www.morrisarboretum.org/blog/plant-names-and-provenance-narcissus-spp-daffodils"],"uncommon":["Pliny the Elder traced the name narcissus to the Greek narkao, I grow numb, a nod to the flower's heady, stupefying scent and the same root as the word narcotic.","https://www.morrisarboretum.org/blog/plant-names-and-provenance-narcissus-spp-daffodils"],"rare":["The word daffodil probably grew from affodell, a variant of asphodel, and playful names such as daffadown dilly were in use by the 16th century.","https://en.wikipedia.org/wiki/Narcissus_(plant)"],"epic":["Narcissus plants make defensive alkaloids, and these led to galantamine, a drug used to treat Alzheimer's dementia.","https://en.wikipedia.org/wiki/Narcissus_(plant)"],"legendary":["Narcissus viridiflorus has green flowers that open at night and are pollinated by moths flying at dusk.","https://en.wikipedia.org/wiki/Narcissus_(plant)"]},"nasturtium":{"common":["Every above-ground part of the nasturtium is edible. The flowers taste peppery, like watercress, and go into salads and stir-fries.","https://en.wikipedia.org/wiki/Tropaeolum_majus"],"uncommon":["Unripe nasturtium seed pods can be pickled in spiced vinegar and used in place of capers.","https://en.wikipedia.org/wiki/Tropaeolum_majus"],"rare":["Orange nasturtiums seem to flash at dusk, an effect discovered by Linnaeus's 19-year-old daughter Elisabeth and now thought to be an optical illusion.","https://en.wikipedia.org/wiki/Tropaeolum_majus"],"epic":["Linnaeus named the genus Tropaeolum after the Roman trophy pole hung with a beaten foe's armour: the round leaves suggested shields, the flowers blood-stained helmets.","https://en.wikipedia.org/wiki/Tropaeolum"],"legendary":["Nasturtium leaves show the lotus effect: rain gathers into beads that roll off, leaving the leaf dry and clean.","https://en.wikipedia.org/wiki/Tropaeolum_majus"]},"neroli":{"common":["Neroli is named after Anne Marie Orsini, princess of Nerola, who made bitter orange blossom essence fashionable in the late 17th century by scenting her gloves and bath with it.","https://en.wikipedia.org/wiki/Neroli"],"uncommon":["Bitter orange blossoms are usually picked by hand in late April and early May. Tunisia, Morocco and Egypt are the leading producers of neroli.","https://en.wikipedia.org/wiki/Neroli"],"rare":["The tree that gives neroli also bears Seville oranges, prized for British marmalade because their high pectin gives a better set.","https://en.wikipedia.org/wiki/Bitter_orange"],"epic":["Bitter orange spread from southern China and Southeast Asia through India and Iran, reaching the Islamic world as early as 700 AD.","https://en.wikipedia.org/wiki/Bitter_orange"],"legendary":["A recipe This American Life published in 2011, said to be Coca-Cola's original 7X flavouring, calls for 10 drops of neroli oil.","https://en.wikipedia.org/wiki/Coca-Cola_formula"]},"nutmeg":{"common":["Under the 1667 Treaty of Breda, England kept Manhattan, which it had seized from the Dutch, and gave up its claim to Run, a tiny nutmeg island in the Banda Sea.","https://en.wikipedia.org/wiki/Run_(island)"],"uncommon":["Nutmeg and mace come from the same fruit: nutmeg is the seed, and mace is the spice made from the lacy red covering, or aril, that wraps around it.","https://en.wikipedia.org/wiki/Nutmeg"],"rare":["Nutmeg contains myristicin. A pinch does nothing, but large doses of raw nutmeg can be psychoactive; the effects take hours to peak and may last for days.","https://en.wikipedia.org/wiki/Nutmeg"],"epic":["To win a nutmeg monopoly, the Dutch East India Company waged a bloody war on the Banda Islands in 1621. By one estimate, about 15,000 islanders lived there before and only 1,000 were left.","https://en.wikipedia.org/wiki/Nutmeg"],"legendary":["To stop rival planting, the Dutch soaked nutmeg seeds in lime before export so they could not sprout. In 1770 a French raid took 400 trees and thousands of untreated seeds to Mauritius.","https://www.saveur.com/article/Kitchen/Pasha-in-the-Spice-Rack/"]},"oak":{"common":["Some oaks are believed to be more than 1,500 years old; the Stelmužė and Granit oaks may be the oldest oaks in Europe.","https://en.wikipedia.org/wiki/Quercus_robur"],"uncommon":["For about 1,400 years Europe wrote in iron gall ink, made with tannin from oak galls. Most medieval manuscripts and many of Leonardo da Vinci's drawings used it.","https://en.wikipedia.org/wiki/Iron_gall_ink"],"rare":["In the UK an estimated 2,300 species of insects, lichens, birds, mammals and more are linked to the English oak, including at least 400 insect herbivores.","https://en.wikipedia.org/wiki/Quercus_robur"],"epic":["In Scandinavia oaks were 'thunderstorm trees' linked to Thor, and people believed lightning would strike the oak instead of their nearby homes.","https://en.wikipedia.org/wiki/Quercus_robur"],"legendary":["France's Tronçais forest was organised by Colbert in 1670 to grow ship timber for the navy centuries later. Today its oaks are prized for cognac barrels.","https://en.wikipedia.org/wiki/Forest_of_Tron%C3%A7ais"]},"oakmoss":{"common":["Oakmoss is a bushy lichen, not a moss. Its English name is a translation of the French mousse de chêne.","https://www.britannica.com/science/oak-moss"],"uncommon":["Oakmoss is a key part of chypre and fougère perfumes, but its use is now highly restricted by IFRA rules, and people with skin sensitisation are told to avoid it.","https://en.wikipedia.org/wiki/Evernia_prunastri"],"rare":["Baskets filled with oakmoss have been found in ancient Egyptian royal tombs. No one knows if it was packed as perfume or as food: the lichen contains an edible starch.","https://www.britannica.com/science/oak-moss"],"epic":["A mixture of acids extracted from oakmoss is used in drugs for treating external wounds and infections.","https://www.britannica.com/science/oak-moss"],"legendary":["Though used extensively in modern perfumery, oakmoss is critically endangered in Iceland, where it is found in only one location.","https://en.wikipedia.org/wiki/Evernia_prunastri"]},"okoume":{"common":["Okoumé makes up more than 60% of timber production in Gabon and Equatorial Guinea, and in the 1960s Gabon exported 1.1 to 1.4 million cubic metres of it a year.","https://uses.plantnet-project.org/en/Aucoumea_klaineana_(PROTA)"],"uncommon":["Light, flexible okoumé plywood is considered perhaps the finest plywood for building boats, and it has also been used to build light aircraft such as the Jodel.","https://en.wikipedia.org/wiki/Aucoumea_klaineana"],"rare":["Okoumé has many of the tonal properties of maple, and guitars made from it are noticeably lighter than those of mahogany or rosewood.","https://en.wikipedia.org/wiki/Aucoumea_klaineana"],"epic":["In Gabon and Equatorial Guinea, okoumé bark resin is used to fuel torches and oil lamps.","https://uses.plantnet-project.org/en/Aucoumea_klaineana_(PROTA)"],"legendary":["Okoumé bark resin is applied to superficial wounds and abscesses, and it is also used as a water disinfectant.","https://uses.plantnet-project.org/en/Aucoumea_klaineana_(PROTA)"]},"olive":{"common":["Raw olives are very bitter and astringent, mainly from oleuropein. They must be cured first, which takes a few days with lye or a few months with brine or salt.","https://en.wikipedia.org/wiki/Olive"],"uncommon":["Olympic champions in ancient Greece won a wreath cut from the sacred wild olive beside the temple of Zeus, snipped with golden scissors by a boy whose parents were both alive.","https://en.wikipedia.org/wiki/Olive_wreath"],"rare":["When frost strikes an olive tree, its rootstock can survive and send up new shoots, which can grow into new trees.","https://en.wikipedia.org/wiki/Olive"],"epic":["The word olive comes from the Latin oliva, and the English word oil originally meant olive oil.","https://en.wikipedia.org/wiki/Olive"],"legendary":["An olive tree at Ano Vouves in Crete has a trunk 12.5 m around. Its exact age is unknown, but University of Crete scientists estimated it at 4,000 years, and it still produces olives.","https://en.wikipedia.org/wiki/Olive_tree_of_Vouves"]},"omumbiri":{"common":["Himba women in Namibia mix omumbiri resin with animal fat and ochre and spread it on their bodies.","https://travelnam.com/?p=16077"],"uncommon":["Omumbiri, or Namibian myrrh, is endemic to Namibia: a low-growing shrub with thick, semi-succulent stems that branch near the ground.","https://travelnam.com/commiphora-2006/"],"rare":["The first commercial harvest of Namibian myrrh in Kunene was made in 2007: 5 tonnes of resin worth US$50,000.","https://travelnam.com/?p=16077"],"epic":["Omumbiri shrubs are so plentiful in Kunene that most Himba women gather a whole year's supply of resin in a single morning, during the October to December harvest.","https://travelnam.com/commiphora-2006/"],"legendary":["Omumbiri resin is picked off branches or from the ground, so there is no need to cut the plants. Each plant gave about 85 ml, and a litre took about four hours to gather.","https://travelnam.com/commiphora-2006/"]},"oolong":{"common":["Oolong sits between green and black tea. Depending on the variety and style, its leaves are oxidised anywhere from 8% to 85%.","https://en.wikipedia.org/wiki/Oolong"],"uncommon":["Taiwan's Alishan oolong is a high-mountain tea, grown at 1,000 to 1,400 m in the mountains of central Taiwan.","https://en.wikipedia.org/wiki/Oolong"],"rare":["No one agrees where the name oolong comes from. One account says the dark, long, curly leaves earned it the name Black Dragon tea.","https://en.wikipedia.org/wiki/Oolong"],"epic":["In 2005, 20 g of Da Hong Pao oolong from one of its mother trees sold for ¥208,000. In 2006 the six remaining mother trees were insured for 100 million RMB.","https://en.wikipedia.org/wiki/Da_Hong_Pao"],"legendary":["Taiwan's Oriental Beauty oolong is made from leaves bitten by tiny leafhoppers. The bites make the plant release terpenes that give the tea its honeyed taste.","https://en.wikipedia.org/wiki/Dongfang_meiren"]},"orange":{"common":["About 67 million tonnes of oranges were grown worldwide in 2024, and Brazil produced 23% of them, more than any other country.","https://en.wikipedia.org/wiki/Orange_(fruit)"],"uncommon":["Seedless navel oranges spread only by grafting. Riverside's parent navel tree, grown from Brazilian buds, was planted in 1873, kept alive on dishwater, and still stands and fruits.","https://ucanr.edu/node/153918"],"rare":["The sweet orange is a cross between a mandarin and a hybrid pomelo; its ancestry is about 42% pomelo and 58% mandarin.","https://en.wikipedia.org/wiki/Orange_(fruit)"],"epic":["In warm climates a ripe orange can stay entirely green. Ethylene gas is used to turn the green skin orange, though it cannot ripen the fruit inside.","https://en.wikipedia.org/wiki/Orange_(fruit)"],"legendary":["The word orange traces back to the Dravidian languages of South India, travelling through Sanskrit, Persian and Arabic. Orange was first recorded as a colour name in English in 1512.","https://en.wikipedia.org/wiki/Orange_(fruit)"]},"orchid":{"common":["The orchid family has about 28,000 accepted species in around 700 genera, some 6 to 11% of all seed plant species.","https://en.wikipedia.org/wiki/Orchidaceae"],"uncommon":["Some orchids pack over a million dust-fine seeds into one capsule. The seeds carry almost no food store, so most can only germinate with the help of a fungus.","https://en.wikipedia.org/wiki/Orchidaceae"],"rare":["Ophrys orchids attract male insects by mimicking a receptive female, with a lip whose colour, shape and odour copy hers.","https://en.wikipedia.org/wiki/Orchidaceae"],"epic":["The name orchid comes from the Ancient Greek orkhis, meaning testicle, after the shape of the tubers of some Orchis species.","https://en.wikipedia.org/wiki/Orchidaceae"],"legendary":["In 2017 scientists described Succinanthera baltica, an orchid preserved in Baltic amber about 40 to 55 million years old.","https://en.wikipedia.org/wiki/Orchidaceae"]},"oregano":{"common":["The origin of the name oregano is disputed, but some trace it to the Greek words oros, mountain, and ganos, joy.","https://en.wikipedia.org/wiki/Oregano"],"uncommon":["Mexican oregano is not in the mint family like true oregano but in the related vervain family, and it has a stronger savoury flavour.","https://en.wikipedia.org/wiki/Oregano"],"rare":["American GIs came home from Italy with a taste for oregano, and US oregano sales rose by about 5,200% between 1948 and 1956.","https://www.npr.org/sections/thesalt/2015/05/09/405302961/gis-helped-bring-freedom-to-europe-and-a-taste-for-oregano-to-america"],"epic":["Greek myth says Aphrodite created oregano as a symbol of happiness, and the ancient Greeks used it in wedding ceremonies and as funerary offerings.","https://en.wikipedia.org/wiki/Oregano"],"legendary":["Most of Türkiye's oregano now comes from the mountains around Denizli, where farmers took it up as the tobacco industry shifted in the early 2000s.","https://www.sniaa.org/files/articles/2023/03/IFEATWORLD-Socio-Economic-Report-Oregano-from-Turkey.pdf"]},"osmanthus":{"common":["Sweet osmanthus flowers carry the scent of ripe peaches or apricots, and they are infused with green or black tea to make osmanthus tea.","https://en.wikipedia.org/wiki/Osmanthus_fragrans"],"uncommon":["Chinese legend says a sweet osmanthus grows on the moon, where Wu Gang is condemned to chop at it forever; each cut heals at once, so the tree never falls.","https://en.wikipedia.org/wiki/Wu_Gang"],"rare":["Sweet osmanthus blooms around the Mid-Autumn Festival, and osmanthus wine is a traditional choice for the reunion wine drunk with family.","https://en.wikipedia.org/wiki/Osmanthus_fragrans"],"epic":["Over 20% of the scent compounds of osmanthus flowers are apocarotenoids. Its two main ones, alpha- and beta-ionone, are made by breaking down alpha- and beta-carotene.","https://abp.ptbioch.edu.pl/index.php/abp/article/view/2176"],"legendary":["In imperial China, to pluck osmanthus in the Toad Palace on the moon was a refined way of saying someone had passed the exam, which was held in the 8th lunar month.","https://en.wikipedia.org/wiki/Osmanthus_fragrans"]},"oud":{"common":["Agarwood forms when an Aquilaria tree is wounded or infected and fills its heartwood with dark resin. Before infection the wood is pale and almost scentless.","https://en.wikipedia.org/wiki/Agarwood"],"uncommon":["First-grade agarwood can sell for as much as US$100,000 per kilogram, and its distilled oil is nicknamed liquid gold.","https://daily.jstor.org/plant-of-the-month-agarwood"],"rare":["In kōdō, the Japanese way of incense codified in the Muromachi period, guests are invited to listen to agarwood rather than smell it, and play games comparing its scents.","https://www.daiichiarts.com/blog/116-kodo-the-way-of-fragrance/"],"epic":["Grand Duke Ferdinando II of Tuscany paid so much for one large piece of agarwood that an average Florentine worker of 1600 would have needed about 77 years to earn it.","https://daily.jstor.org/plant-of-the-month-agarwood"],"legendary":["Ranjatai, a 156 cm log of agarwood, has been kept in Nara's Shōsōin treasure house since the 8th century. Warlord Oda Nobunaga was allowed to cut a 5 cm piece from it in 1574.","https://en.wikipedia.org/wiki/Ranjatai"]},"palosanto":{"common":["Palo santo belongs to the Burseraceae, the same plant family as frankincense and myrrh. One subspecies grows only on the Galápagos Islands.","https://en.wikipedia.org/wiki/Bursera_graveolens"],"uncommon":["Peru bans cutting live palo santo trees: only naturally fallen or dead wood may be collected, and the aged heartwood is rich in limonene and α-terpineol.","https://en.wikipedia.org/wiki/Bursera_graveolens"],"rare":["In a 2025 study, palo santo essential oil cut egg-laying by Asian tiger mosquitoes by 64%. Limonene made up 46% of the oil.","https://pmc.ncbi.nlm.nih.gov/articles/PMC11857052"],"epic":["Besides incense sticks, palo santo wood has been used to make barrels for ageing whiskey.","https://en.wikipedia.org/wiki/Bursera_graveolens"],"legendary":["One account of the name holy stick: after months of bare grey branches, the tree comes into leaf and flower around Christmas, as the rainy season begins.","https://www.ulethbridge.ca/lib/digitized_collections/ourheritage/Great_Adventures/Adventures_Abroad/Ecuador_and_the_Galapagos/Galapagos4/G4_5_Palo_santo.html"]},"papaya":{"common":["Green papaya and its milky latex are rich in papain, a protein-cutting enzyme that goes into powdered meat tenderisers.","https://en.wikipedia.org/wiki/Papaya"],"uncommon":["When papaya ringspot virus ravaged Hawaii's Puna papaya farms in the 1990s, scientists released the genetically engineered, virus-resistant Rainbow papaya in 1998 and saved the industry.","https://www.apsnet.org/edcenter/apsnetfeatures/Documents/2004/HawaiianRainbow.pdf"],"rare":["Papaya plants come in three sexes: male, female and hermaphrodite. Males make only pollen, while hermaphrodites can pollinate themselves.","https://en.wikipedia.org/wiki/Papaya"],"epic":["In 2008 scientists sequenced SunUp, a virus-resistant papaya, the first time the genome of a genetically engineered crop had been read.","https://www.ars.usda.gov/news-events/news/research-news/2008/papayas-genome-unmasked-by-ars-scientists-colleagues/"],"legendary":["Chymopapain, isolated from papaya latex in 1941, was injected into herniated spinal discs to dissolve their core, a treatment called chemonucleolysis.","https://go.drugbank.com/drugs/DB06752"]},"paramela":{"common":["Patagonia's Indigenous peoples have long valued paramela: its tea is widely drunk as a digestive, and its leaves are added to mate.","https://rid.unrn.edu.ar/bitstream/20.500.12049/6773/1/Informe%20RED%20SEGURIDAD%20ALIMENTARIA-%20PARAMELA%20-%202017-03-03.pdf"],"uncommon":["Paramela oil has supplied the perfume industry since 2005, and Mapuche-Tehuelche families now grow the slow-growing shrub in their home orchards.","https://repositoriosdigitales.mincyt.gob.ar/vufind/Record/RIDUNRN_982e06041975100f5a9c2bfbef491e6d"],"rare":["Since 2019 Argentina's food code has allowed paramela as a flavouring in alcoholic drinks, at no more than 1% of stems and leaves.","https://www.cira.org.ar/?p=3308"],"epic":["Joseph Dalton Hooker first described paramela in 1847 in his Flora Antarctica; Mapuche speakers call the shrub eter-loncko.","https://es.wikipedia.org/wiki/Adesmia_boronioides"],"legendary":["Chemists who found a new compound in paramela oil named it esquelenone, in homage to one of the Patagonian places where the shrub grows wild.","https://rid.unrn.edu.ar/bitstream/20.500.12049/6773/1/Informe%20RED%20SEGURIDAD%20ALIMENTARIA-%20PARAMELA%20-%202017-03-03.pdf"]},"passionfruit":{"common":["Passion fruit is named for its flower, in which missionaries saw Christ's Passion: the corona as the crown of thorns, five stamens as the wounds and three styles as the nails.","https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:675370-1/general-information"],"uncommon":["Yellow passion fruit flowers are self-sterile, and pollination works best with large carpenter bees; some growers leave rotting logs nearby to house them.","https://en.wikipedia.org/wiki/Passiflora_edulis"],"rare":["A passion fruit typically holds around 250 brown seeds, each about 2.4 mm long, wrapped in juicy pulp.","https://en.wikipedia.org/wiki/Passiflora_edulis"],"epic":["Yellow passion fruit contains prunasin and other cyanogenic glycosides in its peel and juice, compounds that can release cyanide.","https://en.wikipedia.org/wiki/Passiflora_edulis"],"legendary":["Frank Dicksee's 1884 painting Romeo and Juliet shows a passion fruit vine at the balcony, an anachronism for a story set long before the American plant reached Italy.","https://en.wikipedia.org/wiki/Passiflora_edulis"]},"patchouli":{"common":["Patchouli oil and incense surged in popularity in the 1960s and 1970s, becoming signature scents of the counterculture.","https://en.wikipedia.org/wiki/Patchouli"],"uncommon":["Kashmir shawls were shipped packed in dried patchouli leaves to keep moths away. European buyers learned to recognise genuine Indian shawls by the smell, and by the 1820s patchouli was a fashion in itself.","https://blog.herbsociety.org/?p=16055"],"rare":["Indonesia supplies about 80 to 90% of the world's patchouli oil, traditionally distilled in iron vats that darken it.","https://www.indesso.com/en/our-business/botanical-detail/patchouli-pogostemon-cablin"],"epic":["Robert Holton's 1994 synthesis of the cancer drug Taxol began from patchoulene oxide, made from patchouli alcohol and already holding 15 of the 20 carbons of Taxol's ring core.","https://en.wikipedia.org/wiki/Holton_Taxol_total_synthesis"],"legendary":["Mattel infused the plastic of Stinkor, a 1980s He-Man skunk villain, with patchouli oil so the smell would never rub off. Original figures are said to smell even today.","https://www.oafe.net/yo/motustink.php"]},"peach":{"common":["In Chinese myth the peaches of immortality take about 3,000 years to ripen, and gods eat them to stay immortal; in Journey to the West the Monkey King gorges on them.","https://en.wikipedia.org/wiki/Peaches_of_Immortality"],"uncommon":["The name persica means Persian, but peaches came from China, where they were domesticated as early as 6000 BCE in Zhejiang.","https://en.wikipedia.org/wiki/Peach"],"rare":["Nectarines are not a separate fruit: genetic studies show their smooth skin comes from a single recessive allele in the peach.","https://en.wikipedia.org/wiki/Peach"],"epic":["In the 1864 campaign against the Navajo, Kit Carson's troops destroyed thousands of peach trees. The Navajo later saved pits and replanted their orchards.","https://en.wikipedia.org/wiki/Peach"],"legendary":["Fossil peach stones found in Kunming, China, are 2.6 million years old and match modern peaches, long before the fruit was domesticated.","https://en.wikipedia.org/wiki/Peach"]},"pear":{"common":["For the pear-in-the-bottle eau-de-vie, empty bottles are tied over young fruit on the tree in spring, so each pear grows inside its own bottle.","https://en.wikipedia.org/wiki/Poire_Williams"],"uncommon":["European pears are harvested green, before they are ripe, and finish ripening off the tree. Ethylene from a banana in the fruit bowl speeds them up.","https://en.wikipedia.org/wiki/Pear"],"rare":["Pearwood is the favoured wood for architects' rulers because it does not warp, and it is one of the preferred woods for fine woodwind instruments.","https://en.wikipedia.org/wiki/Pear"],"epic":["Traces of pears have been found in prehistoric pile dwellings around Lake Zurich, villages built on stilts at the water's edge.","https://en.wikipedia.org/wiki/Pear"],"legendary":["Planted in Massachusetts between 1628 and 1639, the Endicott Pear Tree is thought to be North America's oldest living cultivated fruit tree. Vandals cut it to 1.8 m in 1964.","https://en.wikipedia.org/wiki/Endicott_Pear_Tree"]},"peony":{"common":["Peony buds often attract ants, which feed on their nectar. The ants do not harm the plant, and the nectar is not needed for pollination.","https://en.wikipedia.org/wiki/Peony"],"uncommon":["In 1957 Indiana's General Assembly made the peony the state flower, replacing the zinnia, which had held the title since 1931.","https://en.wikipedia.org/wiki/Peony"],"rare":["Legend says Empress Wu Zetian ordered every flower to bloom for a winter banquet. Only the peony refused, so she exiled it to Luoyang, where it thrived as the King of Flowers.","https://www.sixthtone.com/news/1018419"],"epic":["In 1948 Toichi Itoh of Tokyo used pollen from the yellow tree peony Alice Harding on a herbaceous peony, creating the first intersectional, or Itoh, peonies.","https://en.wikipedia.org/wiki/Peony"],"legendary":["An old superstition held that anyone gathering peony fruit must take great care not to be seen by a woodpecker while doing it.","https://en.wikipedia.org/wiki/Peony"]},"pepper":{"common":["Black, green and white pepper all come from the same plant: black and green from unripe fruit dried in different ways, white from the seed of the ripe fruit.","https://en.wikipedia.org/wiki/Black_pepper"],"uncommon":["Pepper's heat comes mostly from piperine, found in both the fruit's skin and its seed. Some sources say piperine also irritates the nostrils and causes sneezing.","https://en.wikipedia.org/wiki/Black_pepper"],"rare":["When Ramesses II was mummified after his death in 1213 BCE, embalmers stuffed black peppercorns into his nostrils.","https://en.wikipedia.org/wiki/Black_pepper"],"epic":["When Alaric, king of the Visigoths, besieged Rome in the 5th century, his ransom demand included 3,000 pounds of pepper.","https://en.wikipedia.org/wiki/Black_pepper"],"legendary":["Archaeologists have recovered more than 2,000 peppercorns from Gribshunden, the Danish king's flagship that sank off what is now Sweden in 1495.","https://en.wikipedia.org/wiki/Black_pepper"]},"persimmon":{"common":["Unripe persimmons are mouth-puckeringly astringent because they contain a soluble tannin called shibuol.","https://en.wikipedia.org/wiki/Persimmon"],"uncommon":["To make Japanese hoshigaki, persimmons are peeled, hung from strings by their stems and massaged daily as they dry.","https://en.wikipedia.org/wiki/Hoshigaki"],"rare":["In Korean folklore the dried persimmon, gotgam, has a reputation for scaring away tigers.","https://en.wikipedia.org/wiki/Persimmon"],"epic":["A persimmon tree that survived the 1945 Nagasaki atomic bomb lives on in saplings: since 1996 the Kaki Tree Project has planted them in Japan and 26 other countries.","https://www.fujibi.or.jp/en/about/peace/kaki-tree-project/"],"legendary":["Unripe persimmons can form hard masses called bezoars in the stomach. Coca-Cola has been used to dissolve them, fully clearing 91% of cases in one review.","https://en.wikipedia.org/wiki/Bezoar"]},"petitgrain":{"common":["Petitgrain means little grain in French: the oil was first distilled from the bitter orange's small, unripe green fruits, before producers switched to leaves and twigs.","https://en.wikipedia.org/wiki/Petitgrain"],"uncommon":["The bitter orange tree gives perfumers three materials: neroli from its flowers, an oil pressed from its peel, and petitgrain from its leaves and twigs.","https://en.wikipedia.org/wiki/Petitgrain"],"rare":["Paraguay and France are the main producers of petitgrain oil, and the Paraguayan oil is noted for its greater odour tenacity.","https://en.wikipedia.org/wiki/Petitgrain"],"epic":["Petitgrain bigarade oil is about 45% linalyl acetate and 20% linalool, with smaller amounts of pinene, terpineol and geranyl acetate.","https://en.wikipedia.org/wiki/Petitgrain"],"legendary":["In Cuba the wood of the bitter orange, the tree whose leaves give petitgrain, is made into baseball bats. The trees can live for as long as 600 years.","https://en.wikipedia.org/wiki/Bitter_orange"]},"pimento":{"common":["Jamaicans traditionally smoke jerk meat over allspice wood, and the tree's leaves and wood are used to smoke meat wherever it grows.","https://en.wikipedia.org/wiki/Allspice"],"uncommon":["Allspice is a single berry, not a mix: the English had coined the name by 1621 because it tastes like cinnamon, nutmeg and clove combined.","https://en.wikipedia.org/wiki/Allspice"],"rare":["In the United States, allspice is what gives Cincinnati-style chili its distinctive aroma and flavour.","https://en.wikipedia.org/wiki/Allspice"],"epic":["In Poland allspice is commonly called English herb, because Britain was its major exporter.","https://en.wikipedia.org/wiki/Allspice"],"legendary":["Early attempts to grow allspice from seed all failed. Passing through a bird's digestive tract turned out to be essential for the seeds to germinate.","https://en.wikipedia.org/wiki/Allspice"]},"pineapple":{"common":["Pineapples were so expensive in Georgian Britain that hosts rented one to display at a dinner party, and the same fruit was hired out again and again.","https://www.ianvisits.co.uk/articles/when-lononders-would-rent-pineapples-instead-of-eating-them-36529/"],"uncommon":["Pineapple contains bromelain, a group of protein-digesting enzymes found in its fruit, stem, core, crown and leaves.","https://en.wikipedia.org/wiki/Pineapple"],"rare":["In the wild, pineapple flowers are pollinated mainly by hummingbirds.","https://en.wikipedia.org/wiki/Pineapple"],"epic":["A pineapple's scales form interlocking spirals, often 8 one way and 13 the other, both Fibonacci numbers. Each fruit grows from up to about 200 flowers.","https://en.wikipedia.org/wiki/Pineapple"],"legendary":["The Earl of Dunmore built a stone cupola 14 m tall in the shape of a pineapple on his Scottish estate. It is known as the Dunmore Pineapple.","https://en.wikipedia.org/wiki/Pineapple"]},"pinkpepper":{"common":["Pink peppercorns are not related to black pepper: they were named for looking like peppercorns and tasting peppery.","https://en.wikipedia.org/wiki/Pink_peppercorn"],"uncommon":["The pink pepper tree belongs to the cashew family, and its sap contains urushiol-type compounds like poison ivy's, which can cause itchy rashes in sensitive people.","https://en.wikipedia.org/wiki/Schinus_terebinthifolia"],"rare":["In 1982 the US FDA banned imports of these pink peppercorns from France, citing poison-ivy-like reactions, while France maintained they were safe to eat.","https://en.wikipedia.org/wiki/Pink_peppercorn"],"epic":["Burning Brazilian pepper trees is strongly discouraged because the smoke releases airborne irritants with a mace-like effect on people nearby.","https://en.wikipedia.org/wiki/Schinus_terebinthifolia"],"legendary":["The fruit of the Brazilian pepper tree has been reported to have narcotic and paralysing effects on the birds that eat it.","https://en.wikipedia.org/wiki/Schinus_terebinthifolia"]},"pistachio":{"common":["When a pistachio ripens, its shell turns yellow-red and suddenly splits partly open, with an audible pop.","https://en.wikipedia.org/wiki/Pistachio"],"uncommon":["Pistachios are so oily that, if damp and stored with a fabric such as jute, they can heat up on their own and spontaneously catch fire.","https://en.wikipedia.org/wiki/Pistachio"],"rare":["Pistachio trees are either male or female, and one male tree produces enough pollen for 8 to 12 nut-bearing females.","https://en.wikipedia.org/wiki/Pistachio"],"epic":["Pistachio shells were first dyed red to hide stains left by hand-picking. Most are now machine-harvested and keep their natural beige.","https://en.wikipedia.org/wiki/Pistachio"],"legendary":["The Hanging Gardens of Babylon were said to contain pistachio trees, in the reign of King Marduk-apla-iddina II around 700 BCE.","https://en.wikipedia.org/wiki/Pistachio"]},"plum":{"common":["Traditional plum pudding contains no plums in the modern sense: 'plum' was the old word for what has been called a raisin since the 18th century.","https://en.wikipedia.org/wiki/Christmas_pudding"],"uncommon":["Since 2001 US growers have been allowed to sell prunes as dried plums, and some brands dropped the word prune because of its link with constipation.","https://en.wikipedia.org/wiki/Prune"],"rare":["Plums are Serbia's national fruit and šljivovica, plum brandy, its national drink; the tradition of making it is on UNESCO's Intangible Cultural Heritage list.","https://en.wikipedia.org/wiki/Slivovitz"],"epic":["Before the Second World War, Poland's Jewish community distilled slivovitz in large quantities, and the plum brandy became a popular Passover drink.","https://en.wikipedia.org/wiki/Slivovitz"],"legendary":["Bulgaria's Troyan Monastery has distilled plum spirit since its founding in the 14th century; its original recipe reportedly used 40 herbs, passed from abbot to abbot.","https://en.wikipedia.org/wiki/Slivovitz"]},"pomegranate":{"common":["The hand grenade was probably named after the pomegranate, French grenade, either for its shape or because a seed-packed fruit suggested a powder-filled bomb that bursts into fragments.","https://www.etymonline.com/word/grenade"],"uncommon":["The word garnet may come from the Latin pomum granatum, pomegranate, after the deep red colour of the fruit's pulp.","https://en.wikipedia.org/wiki/Pomegranate"],"rare":["A popular tradition says a pomegranate holds 613 seeds, one for each commandment, but the number is not in rabbinic sources; real fruits hold about 200 to 1,400.","https://en.wikipedia.org/wiki/Pomegranate"],"epic":["A large, dried pomegranate was found in the Egyptian tomb of Djehuty, butler to Queen Hatshepsut.","https://en.wikipedia.org/wiki/Pomegranate"],"legendary":["Pomegranate remains lay among perfume, ivory and gold jewellery on the Uluburun wreck, sunk off Turkey around the 14th century BCE, so the fruit may have been a luxury good.","https://en.wikipedia.org/wiki/Pomegranate"]},"pomelo":{"common":["The pomelo is the largest citrus fruit; depending on the variety, a single fruit weighs from 0.26 to 1.95 kg.","https://en.wikipedia.org/wiki/Pomelo"],"uncommon":["In the Caribbean the pomelo was long called shaddock, reputedly after an East India Company captain who brought it to Barbados in the 1640s.","https://en.wikipedia.org/wiki/Pomelo"],"rare":["Like grapefruit, pomelo can inhibit cytochrome P450, the enzymes the body uses to break down many medicines, so it can interact with some drugs.","https://en.wikipedia.org/wiki/Pomelo"],"epic":["At Lunar New Year pomelos are offered to ancestors, because the fruit's Chinese name sounds like the word for to have, making it a symbol of prosperity.","https://en.wikipedia.org/wiki/Pomelo"],"legendary":["The pomelo is one of three wild ancestors of most cultivated citrus. Grapefruit is a pomelo and sweet orange hybrid, with about 63% of its genome from pomelo.","https://en.wikipedia.org/wiki/Pomelo"]},"priprioca":{"common":["Priprioca is a sedge that grows in or beside rivers, streams and swamps. Its perfume comes from its roots, which give off a light woody, spicy scent with floral notes.","https://en.wikipedia.org/wiki/Cyperus_articulatus"],"uncommon":["On São João's eve or day, 24 June, Belém's Ver-o-Peso herb sellers mix priprioca, patchouli and other forest herbs into a banho de cheiro, a scented bath for luck and love.","https://sbtnews.sbt.com.br/noticia/brasil/251067-belem-mantem-viva-tradicao-centenaria-do-banho-de-cheiro"],"rare":["Chef Alex Atala worked with Givaudan to put priprioca into sweet and savoury dishes at D.O.M., his two-Michelin-star São Paulo restaurant, though Amazonian peoples had not eaten it.","https://americasquarterly.org/fulltextarticle/the-food-worlds-hottest-ingredient-has-roots-in-seduction/"],"epic":["Amazonian lore names priprioca after Piripiri, a warrior whose scent drew women to him, and Belém market sellers long sold its fragrant oil as a love potion.","https://americasquarterly.org/content/magic-priprioca"],"legendary":["When Natura brought priprioca into perfume, its olfactive manager said it was the first scented oil obtained from a new botanical species in 40 years.","https://americasquarterly.org/fulltextarticle/the-food-worlds-hottest-ingredient-has-roots-in-seduction/"]},"quince":{"common":["The word marmalade comes from Portuguese marmelada, a preserve named after marmelo, the Portuguese word for quince.","https://en.wikipedia.org/wiki/Quince"],"uncommon":["Raw quince is hard, sour and inedible, so it is peeled and poached in syrup, which can take about 40 minutes or twice that before a knife slides in easily.","https://www.countrylife.co.uk/gardens/quince-perfect-autumn-fruit-205417"],"rare":["Plutarch records an Athenian law, credited to Solon, that a bride should eat a quince before being shut in the chamber with her new husband.","https://lexundria.com/plut_sol/20/prr"],"epic":["Quince was first recorded in Britain in 1275, when Edward I had four trees planted at the Tower of London.","https://wythamwoods.site.ox.ac.uk/article/quince-cydonia-oblonga-0"],"legendary":["Quince is used as a rootstock for some pear varieties, so some pear trees are really a pear grafted onto quince roots.","https://en.wikipedia.org/wiki/Quince"]},"raspberry":{"common":["A raspberry is a cluster of about 100 drupelets, each holding one seed. Its core stays on the plant when picked, which is why the fruit is hollow.","https://en.wikipedia.org/wiki/Raspberry"],"uncommon":["Arilje, a Serbian town of about 17,000 people, is known as the country's raspberry capital. About 90% of Serbian raspberries are exported frozen.","https://wtop.com/national/2026/06/a-serbian-town-is-known-for-raspberries-that-are-exported-around-the-world/"],"rare":["Natural raspberry ketone, a key raspberry aroma molecule, can cost as much as $20,000 per kg, because a kilo of raspberries yields only about 1 to 4 mg of it.","https://en.wikipedia.org/wiki/Raspberry_ketone"],"epic":["Rubus idaeus nods to Mount Ida. Legend says raspberries were white until the nymph Ida, picking fruit for the infant Zeus, pricked her finger on a thorn and stained them red.","https://www.rhs.org.uk/advice/grow-your-own/features/fascinating-facts-raspberries"],"legendary":["Astronomers found ethyl formate, a molecule that helps give raspberries their flavour, in Sagittarius B2, a vast dust cloud near the centre of the Milky Way.","https://www.howitworksdaily.com/the-milky-way-smells-of-rum-and-tastes-like-raspberries/"]},"rhododendron":{"common":["All azaleas are rhododendrons, but not all rhododendrons are azaleas. The genus holds about a thousand species.","https://rhododendron.org/classification.htm"],"uncommon":["Bhutan has 48 rhododendron species, and more than 46 of them grow in the Royal Botanical Park at Lamperi, which hosts an annual rhododendron festival in April.","https://thebhutanese.bt/?p=12869"],"rare":["Rhododendron ponticum reached the UK via Gibraltar in 1763 and ran wild. Clearing it from Snowdonia National Park alone was estimated to cost over £30 million.","https://insideecology.com/2017/09/06/invasive-non-native-species-uk-rhododendron-ponticum/"],"epic":["In 65 BC Mithridates' troops left combs of rhododendron \\"mad honey\\" for pursuing Romans; Strabo says three maniples were slain after eating it.","https://en.wikipedia.org/wiki/Mad_honey"],"legendary":["Joseph Hooker was held prisoner in Sikkim for nearly two months in 1849 while hunting rhododendrons. His seeds, raised at Kew, set off a rhododendron craze in Britain.","https://thegardenhistory.blog/2025/04/12/joseph-hooker-rhododendrons/"]},"rhubarb":{"common":["Rhubarb leaves contain oxalic acid and are poisonous. When they were wrongly recommended as food in Britain during the First World War, people were poisoned.","https://en.wikipedia.org/wiki/Rhubarb"],"uncommon":["Yorkshire forced rhubarb is harvested by candlelight, since brighter light disrupts the forcing. In the dark sheds it can grow more than an inch a day, fast enough to hear.","https://www.smithsonianmag.com/travel/the-english-farmers-who-harvest-rhubarb-by-candlelight-180984141/"],"rare":["In 1947 a US Customs Court in Buffalo, New York, ruled rhubarb a fruit because it is mostly eaten in sweet dishes, so imports paid a lower duty than vegetables.","https://www.specialtyproduce.com/produce/Rhubarb_3378.php"],"epic":["In medieval Europe, rhubarb root cost several times as much as cinnamon, opium or saffron, largely because of the cost of hauling it across Asia.","https://en.wikipedia.org/wiki/Rhubarb"],"legendary":["In 1839 China's commissioner Lin Zexu proposed withholding tea and rhubarb from the British, believing they could not live without them. He later decided only tea mattered.","https://victorianweb.org/history/empire/opiumwars/rhubarb.html"]},"rice":{"common":["Rice is the staple food for over half of the world's population, and more than 2 billion people in Asia get 60 to 70% of their calories from it.","https://www.fao.org/4/Y5167E/y5167e02.htm"],"uncommon":["To be exported as Thai Hom Mali, jasmine rice must be at least 92% genetically pure, and Thai laboratories check samples with DNA markers.","https://dna.kps.ku.ac.th/research/articles/how-dna-technology-helps-control-the-premium-quality-of-thai-hom-mali-rice"],"rare":["Chinese builders mixed sticky rice into lime mortar about 1,500 years ago. Its amylopectin made walls such as Nanjing's 600-year-old city wall tougher and more water-resistant.","https://www.nationalgeographic.com/history/article/100608-sticky-rice-mortar-china-science"],"epic":["Thung Kula Rong Hai means the field where the Kula wept: legend says Kula traders crossing the waterless, shadeless plain broke down in tears. It now grows prized Hom Mali rice.","https://en.wikipedia.org/wiki/Thung_Kula_Ronghai"],"legendary":["Binturong urine smells of buttered popcorn. A 2016 study traced it to 2-acetyl-1-pyrroline, the same molecule that gives jasmine rice its floral scent.","https://www.popsci.com/bearcats-pee-smells-like-hot-buttered-popcorn/"]},"rooibos":{"common":["Rooibos is Afrikaans for red bush, and the tea brewed from its needle-like leaves contains no caffeine.","https://en.wikipedia.org/wiki/Rooibos"],"uncommon":["Rooibos gets its reddish-brown colour from oxidising the cut leaves. Skip that step and you get green rooibos, which tastes malty and grassy.","https://en.wikipedia.org/wiki/Rooibos"],"rare":["Rooibos was the first African food added to the EU's list of protected designations of origin, joining Champagne, Greek feta and Colombian coffee.","https://kuow.org/stories/rooibos-tea-is-africa-s-first-food-to-join-the-eu-s-list-of-protected-products"],"epic":["In 1994 a US company registered Rooibos as a trademark. Herbal trade groups and importers fought it until 2005, when the name was surrendered to the public domain.","https://en.wikipedia.org/wiki/Rooibos"],"legendary":["When rooibos pioneer Dr Nortier paid a shilling per matchbox of wild seed, one old woman kept bringing it in: she had found it by robbing the ants, who hoard the seeds underground.","https://www.klipopmekaar.co.za/fascinating-perspectives-on-the-history-of-rooibos/"]},"rose":{"common":["Rose petals for oil are picked by hand in the morning before sunrise and distilled the same day. The yield is roughly 1 part oil to 3,000 parts flowers.","https://en.wikipedia.org/wiki/Rose_oil"],"uncommon":["Real rose otto congeals at around 20 °C: 10 to 15% of it is stearoptene, an odourless wax, so a bottle left somewhere cool turns semi-solid.","https://henriettes-herb.com/eclectic/bpc1911/rosa_oleu.html"],"rare":["DNA analysis shows the damask rose descends from three wild species, Rosa gallica, Rosa moschata and Rosa fedtschenkoana, probably first crossed in Central Asia or Iran.","https://en.wikipedia.org/wiki/Rosa_%C3%97_damascena"],"epic":["Crusader Robert de Brie, who fought at the Siege of Damascus in 1148, is sometimes credited with bringing the damask rose from Syria to Europe.","https://en.wikipedia.org/wiki/Rosa_%C3%97_damascena"],"legendary":["Beta-damascenone shapes the scent of rose oil even at very low concentration. In 2008 it was identified as a primary odorant of Kentucky bourbon.","https://en.wikipedia.org/wiki/Damascenone"]},"rose_centifolia":{"common":["Centifolia means hundred-leaved: Rose de Mai, also called the cabbage rose, has round flowers packed with many thin, overlapping petals.","https://en.wikipedia.org/wiki/Provence_Rose"],"uncommon":["Grasse was a leather-tanning town. Tanner Jean de Galimard offered scented gloves to Catherine de' Medici, and the fashion spread through the royal court.","https://en.wikipedia.org/wiki/Grasse"],"rare":["In Vigée Le Brun's 1783 portrait, Marie Antoinette holds a pink Rosa × centifolia, the many-petalled rose developed by Dutch breeders from the 17th century.","https://en.wikipedia.org/wiki/Provence_Rose"],"epic":["The original centifolia rose was sterile. New forms came from sports, or chance mutations, including a single-flowered one in 1769 and the moss rose with resin-haired buds.","https://en.wikipedia.org/wiki/Provence_Rose"],"legendary":["In the 1940s Grasse harvested about 5,000 tons of flowers a year. By early 2000 the harvest of all its flowers combined had fallen below 30 tons.","https://en.wikipedia.org/wiki/Grasse"]},"rose_turkey":{"common":["Isparta's roses are turned into rose oil, rose water and rose wax, and its rose jam and rose Turkish delight have been served since Ottoman times.","https://www.dailysabah.com/travel/2018/04/14/isparta-anatolias-most-aromatic-city/amp"],"uncommon":["About 1,350 rose species grow worldwide, and 24 of them are native to Turkey. Isparta's oil rose itself is the damask rose, Rosa damascena.","https://www.dailysabah.com/travel/2018/04/14/isparta-anatolias-most-aromatic-city/amp"],"rare":["Isparta, nicknamed the City of Roses, built its economy on two crafts: rose water and handmade carpets, which remain core local trades.","https://en.wikipedia.org/wiki/Isparta"],"epic":["Isparta's rose industry began around 1889 when trader İsmail Efendi learned the craft by letter from an official from Bulgaria's Kazanlak; frost and snow wiped out his first fields.","https://www.dailysabah.com/travel/2018/04/14/isparta-anatolias-most-aromatic-city/amp"],"legendary":["Isparta's modern rose oil factory was founded in 1935 on the order of Mustafa Kemal Atatürk, given during his visit to the city.","https://www.dailysabah.com/travel/2018/04/14/isparta-anatolias-most-aromatic-city/amp"]},"rosehip":{"common":["Rose hips are the fruit of the rose. On sweet briar they are red, 1 to 2 cm across, and cling to the bare stems well into winter.","https://en.wikipedia.org/wiki/Rosa_rubiginosa"],"uncommon":["Sweet briar, Rosa rubiginosa, takes the sweet in its name from its leaves, which give off an apple-like scent. The briar part refers to its hooked prickles.","https://en.wikipedia.org/wiki/Rosa_rubiginosa"],"rare":["In the Second World War the British relied on rose hips and hops for vitamins, giving rise to the saying \\"We are getting by on our hips and hops\\".","https://en.wikipedia.org/wiki/Rosa_rubiginosa"],"epic":["Sweet briar is invasive across most of Argentine Patagonia and southern Chile, where cattle spread its seeds, causing several million dollars of damage a year.","https://en.wikipedia.org/wiki/Rosa_rubiginosa"],"legendary":["While sweet briar is a costly weed in Patagonia and a banned plant in parts of New Zealand, in Portugal it is critically endangered and found only in the Serra da Estrela range.","https://en.wikipedia.org/wiki/Rosa_rubiginosa"]},"rosemary":{"common":["Rosemary's old Latin name, ros marinus, is traditionally read as dew of the sea, a fitting name for a shrub said to thrive best on the coast.","https://en.wikipedia.org/wiki/Rosemary"],"uncommon":["In Hamlet, Ophelia says there's rosemary, that's for remembrance. The herb is still tied to memory: Australians wear sprigs of it on ANZAC Day.","https://en.wikipedia.org/wiki/Rosemary"],"rare":["In 2017 DNA evidence moved rosemary into the sage genus Salvia, so its botanical name changed from Rosmarinus officinalis to Salvia rosmarinus.","https://en.wikipedia.org/wiki/Rosemary"],"epic":["Hungary Water, made mainly from distilled rosemary in the 14th century, was one of Europe's first alcohol-based perfumes.","https://en.wikipedia.org/wiki/Rosemary"],"legendary":["In 1338 Countess Joan of Hainault sent rosemary cuttings to her daughter, Queen Philippa of England, and they were planted at the old palace of Westminster.","https://en.wikipedia.org/wiki/Rosemary"]},"rosewood":{"common":["The bois de rose tree is listed as Endangered by the IUCN, and both its wood and its essential oil are covered by CITES Appendix II trade controls.","https://en.wikipedia.org/wiki/Aniba_rosaeodora"],"uncommon":["Rosewood trees are cut from wild stands near the Amazon and its tributaries, sawn into logs about 1 m long and floated to mobile distilleries.","https://en.wikipedia.org/wiki/Aniba_rosaeodora"],"rare":["Bois de rose comes from a tree in the laurel family whose purple fruit is spread by toucans. It is not related to the Dalbergia rosewoods prized for guitars.","https://en.wikipedia.org/wiki/Aniba_rosaeodora"],"epic":["The tree once grew more widely, including in French Guiana, but most of the world's rosewood oil comes from Brazil; other regions have produced only minor amounts since the 1960s.","https://en.wikipedia.org/wiki/Aniba_rosaeodora"],"legendary":["Bois de rose can grow 30 m tall and 2 m across, yet distilling its wood gives only about 1% of its weight as oil.","https://en.wikipedia.org/wiki/Aniba_rosaeodora"]},"rum":{"common":["The Royal Navy issued its last daily rum ration on 31 July 1970. Sailors wore black armbands and some buried their final tots at sea.","https://www.mentalfloss.com/article/56595/day-royal-navy-ended-its-daily-rum-ration"],"uncommon":["Most rum is distilled from molasses, a by-product of sugar refining, but Martinique's rhum agricole is made from freshly squeezed sugar cane juice.","https://en.wikipedia.org/wiki/Rhum_agricole"],"rare":["Around 1811 France began making sugar from beets and cane sugar prices fell, so Caribbean sugar factories turned their fresh cane juice into rum instead.","https://en.wikipedia.org/wiki/Rhum_agricole"],"epic":["On 26 January 1808 about 400 soldiers of the New South Wales Corps, nicknamed the Rum Corps, arrested Governor William Bligh, who had banned paying for goods with spirits.","https://en.wikipedia.org/wiki/Rum_Rebellion"],"legendary":["On 8 May 1902 Mount Pelée's blast killed nearly all of Saint-Pierre's 28,000 people, its fires fed by countless casks of rum. A prisoner in a windowless cell survived.","https://en.wikipedia.org/wiki/1902_eruption_of_Mount_Pel%C3%A9e"]},"saffron":{"common":["It takes about 150,000 crocus flowers, and some 440,000 hand-picked stigmas, to make a single kilogram of saffron.","https://en.wikipedia.org/wiki/Saffron"],"uncommon":["Iran grows around 90% of the world's saffron, and was the largest producer in 2024.","https://en.wikipedia.org/wiki/Saffron"],"rare":["Saffron Walden in Essex is named after the crop it once grew and traded in the 16th and 17th centuries. Cultivation there died out and was revived around 2013.","https://en.wikipedia.org/wiki/Saffron"],"epic":["The saffron crocus has three sets of chromosomes and sets no viable seed. It spreads only when people dig up and replant its corms, each making up to ten new ones.","https://en.wikipedia.org/wiki/Saffron"],"legendary":["Nuremberg's Safranschou code punished merchants who adulterated saffron with fines, prison, and even execution.","https://en.wikipedia.org/wiki/Saffron"]},"sage":{"common":["Clary sage is a short-lived biennial that grows 0.9 to 1.2 m tall, with flower spikes wrapped in bracts from pale mauve and lilac to white and pink.","https://en.wikipedia.org/wiki/Salvia_sclarea"],"uncommon":["In the United States, clary sage for oil is grown mostly on a large scale around Bertie County, North Carolina.","https://en.wikipedia.org/wiki/Salvia_sclarea"],"rare":["Culpeper called clary sage clear-eye: its seeds grow a sticky coat when wet, and old herbals advised putting one in the eye so grit would stick to it and lift out.","https://en.wikipedia.org/wiki/Salvia_sclarea"],"epic":["In 16th-century Germany, clary infused with elderflowers was added to Rhine wines to make a stronger drink called Muscatel.","https://en.wikipedia.org/wiki/Salvia_sclarea"],"legendary":["Sclareol, made in tiny glands on clary sage's flower calyces and named after the plant, is the main starting material for ambroxide, sold as Ambrox, a fixative in commercial perfumes.","https://en.wikipedia.org/wiki/Sclareol"]},"sambac":{"common":["Jasmine sambac became the national flower of the Philippines, as sampaguita, in 1934, and is one of Indonesia's three national flowers, as melati putih.","https://en.wikipedia.org/wiki/Jasminum_sambac"],"uncommon":["In China, jasmine sambac flowers are processed and used as the main flavouring of jasmine tea.","https://en.wikipedia.org/wiki/Jasminum_sambac"],"rare":["Jasmine sambac flowers usually open between about 6 and 8 p.m. and close the next morning, staying open for 12 to 20 hours.","https://en.wikipedia.org/wiki/Jasminum_sambac"],"epic":["In Hawaii jasmine sambac is called pīkake, meaning peacock. Princess Kaʻiulani adored the flower, often wore it in leis and is credited with naming it.","https://hawaiiverse.com/blogs/news/the-royal-pikake-flower"],"legendary":["Sampaguita blends Tagalog sampaga, jasmine, itself borrowed from Sanskrit campaka, with the Spanish diminutive -ita.","https://en.wikipedia.org/wiki/Jasminum_sambac"]},"sandalwood":{"common":["Only sandalwood's heartwood is fragrant. The scent starts to develop at about 10 years, and trunks are ready to harvest only after about 20 years.","https://en.wikipedia.org/wiki/Santalum_album"],"uncommon":["When World War I cut off sandalwood exports to Europe, the Maharaja of Mysore opened a soap factory in 1916 to use the stockpiled wood. Mysore Sandal Soap is still made today.","https://en.wikipedia.org/wiki/Mysore_Sandal_Soap"],"rare":["Sandalwood is a hemiparasite: its roots latch onto other plants' roots to draw nutrients, and up to 300 species, itself included, can serve as hosts.","https://en.wikipedia.org/wiki/Santalum_album"],"epic":["In Karnataka and Tamil Nadu, sandalwood trees above a set girth belonged to the state until 2001-02. Afterwards private growers could sell the wood only to the forest department.","https://en.wikipedia.org/wiki/Santalum_album"],"legendary":["Over decades, the brigand Veerappan smuggled about 65 tons of sandalwood worth some US$22 million, and in 2000 held film star Rajkumar captive for 108 days.","https://en.wikipedia.org/wiki/Veerappan"]},"sapodilla":{"common":["Chicle, the gum of the sapodilla tree, was the original base of chewing gum. The Chiclets brand takes its name from it.","https://en.wikipedia.org/wiki/Chicle"],"uncommon":["Chicleros cut zig-zag gashes into the sapodilla trunk, catch the dripping latex in small bags, then boil it down until it is thick enough.","https://en.wikipedia.org/wiki/Chicle"],"rare":["In 1869 the exiled Mexican general Santa Anna pitched sapodilla chicle to Thomas Adams as a cheap rubber substitute. It failed as rubber, so the Adams family turned it into chewing gum.","https://engines.egr.uh.edu/episode/963"],"epic":["After Guatemala's 1952 land reform, the Wrigley company, the sole buyer of Guatemalan chicle, stopped buying it, and the government had to set up a large aid programme for growers.","https://en.wikipedia.org/wiki/Chicle"],"legendary":["The Maya chewed sapodilla chicle to stave off hunger and freshen breath, and also used it to fill cavities in teeth.","https://en.wikipedia.org/wiki/Chicle"]},"seabuckthorn":{"common":["Sea buckthorn berries from Ladakh measured about 275 mg of vitamin C per 100 g, against roughly 50 mg in the same weight of orange.","https://www.frontiersin.org/journals/nutrition/articles/10.3389/fnut.2022.1036295/full"],"uncommon":["Sea buckthorn fixes nitrogen through root nodules. In Chinese trials, topsoil under it held 4.45% organic matter, against 0.79% in nearby farmland.","https://topsoil.nserl.purdue.edu/isco/isco12/VolumeIII/SoilImprovementofSeabuckthorn.pdf"],"rare":["The name Hippophae joins the Greek words for horse and light, linked to the ancient Greek habit of feeding the leaves to horses to make their coats shine.","https://en.wikipedia.org/wiki/Hippophae"],"epic":["India's defence research agency set up a factory in Leh, Ladakh, to turn sea buckthorn into a vitamin drink for soldiers serving in extreme cold.","https://en.wikipedia.org/wiki/Hippophae"],"legendary":["Russian research on sea buckthorn began in the 1940s and led to sea buckthorn foods and radiation-protection creams for Russian cosmonauts.","https://www.frontiersin.org/journals/nutrition/articles/10.3389/fnut.2022.1036295/full"]},"seasalt":{"common":["France's salt workers, the paludiers, skim fleur de sel with a wooden rake called a lousse à fleur. Each salt pan yields only about 1 kg a day.","https://en.wikipedia.org/wiki/Fleur_de_sel"],"uncommon":["Fleur de sel can only be collected when the weather is very sunny and dry, with slow, steady winds.","https://en.wikipedia.org/wiki/Fleur_de_sel"],"rare":["Calone, the molecule that gives aquatic perfumes their sea-breeze note, was discovered in 1966 by the drug company Pfizer, and is distantly related to benzodiazepine sedatives.","https://en.wikipedia.org/wiki/Calone"],"epic":["Fleur de sel is often pale grey from marsh clay, and it sometimes carries a faint pink tinge from the microalga Dunaliella salina.","https://en.wikipedia.org/wiki/Fleur_de_sel"],"legendary":["Brittany was exempt from the gabelle salt tax, so smugglers hid its salt in bread loaves and butter pats to sell next door. Some trained dogs to run the border.","https://bcd.bzh/becedia/en/node/65151"]},"seaweed":{"common":["In 1811 French chemist Bernard Courtois discovered iodine in seaweed ash. Humphry Davy described the new element's vapour as a beautiful violet colour.","https://en.wikipedia.org/wiki/Bernard_Courtois"],"uncommon":["Bladder wrack's paired air bladders hold oxygen, carbon dioxide and carbon monoxide from respiration and photosynthesis, floating the fronds up toward the light.","https://www.sciencefocus.com/nature/what-gas-is-in-the-bladders-of-bladder-wrack"],"rare":["From about 1700 to 1820, Irish coastal communities burned seaweed in stone kilns. The ash, called kelp, supplied alkali for soap, glass, dyeing and bleaching.","https://www.ouririshheritage.org/content/archive/topics/miscellaneous/a-brief-history-of-the-kelp-industry-in-fanad"],"epic":["Bladder wrack reached the Baltic Sea less than 8,000 years ago. There it took to cloning itself from detached branches, something never reported anywhere else.","https://en.wikipedia.org/wiki/Fucus_vesiculosus"],"legendary":["In the 1300s King Denis of Portugal, known as the Farmer King, regulated the harvest of seaweeds cast ashore, Fucus among them.","https://seaveg.com/pages/what-is-bladderwrack"]},"shea":{"common":["An estimated 16 million women in rural West Africa collect shea fruits and process them into dried kernels or shea butter.","https://allafrica.com/stories/202601260005.html"],"uncommon":["A shea tree first fruits at 10 to 15 years, reaches full production at 20 to 30, and can keep bearing nuts for up to 200 years.","https://en.wikipedia.org/wiki/Vitellaria"],"rare":["Tamale, the largest city of northern Ghana, takes its name from the Dagomba Tama-yile, meaning home of shea nuts.","https://en.wikipedia.org/wiki/Vitellaria"],"epic":["Explorer Mungo Park wrote that shea butter keeps a whole year without salt and is whiter, firmer and richer in flavour than the best cow's-milk butter.","https://gutenberg.org/cache/epub/5305/pg5305-images.html"],"legendary":["Shea caterpillars feed only on shea leaves. In Burkina Faso they are a seasonal food: 100 g fresh supplies about 150% of a woman's daily protein need.","https://link.springer.com/article/10.1007/s12571-019-00994-z"]},"siberianfir":{"common":["Siberian fir is so frost-hardy that it survives temperatures down to about −50 °C in the taiga east of the Volga.","https://en.wikipedia.org/wiki/Abies_sibirica"],"uncommon":["Siberian fir is the most widely distributed fir in the world, growing from near sea level in the northern taiga high into the mountains.","https://www.conifers.org/pi/Abies_sibirica.php"],"rare":["Like all firs, Siberian fir holds its cones upright on the branches like candles, and they fall apart on the tree to release their winged seeds.","https://en.wikipedia.org/wiki/Fir"],"epic":["Siberian fir rarely lives beyond 150 to 200 years, because rot sets into its wood.","https://www.conifers.org/pi/Abies_sibirica.php"],"legendary":["The tallest Siberian fir on record is not in Siberia: a cultivated tree at Punkaharju, Finland, measured 40.5 m in July 2012.","https://www.conifers.org/pi/Abies_sibirica.php"]},"sichuan":{"common":["Sichuan pepper is no relative of black pepper: it comes from Zanthoxylum shrubs in the rue family, Rutaceae, which also includes citrus.","https://en.wikipedia.org/wiki/Sichuan_pepper"],"uncommon":["Paired with chillies, Sichuan pepper creates málà, Chinese for numb-spiciness, the signature flavour of Sichuan cooking.","https://en.wikipedia.org/wiki/Sichuan_pepper"],"rare":["From 1968 to 2005 the US banned Sichuan pepper imports because they could carry citrus canker. Later imports had to be heated for about 10 minutes at 60 °C.","https://en.wikipedia.org/wiki/Sichuan_pepper"],"epic":["Zanthoxylum comes from Greek xanthos, yellow, and xylon, wood. Its Z should be an X, but botanical naming rules do not allow the spelling to be corrected.","https://en.wikipedia.org/wiki/Zanthoxylum"],"legendary":["The tingle of Sichuan pepper resembles a vibration of about 50 hertz, the kind picked up by the skin's RA1 touch receptors.","https://en.wikipedia.org/wiki/Sichuan_pepper"]},"spikenard":{"common":["When Mary of Bethany anointed Jesus with a pound of spikenard, Judas valued it at 300 denarii, about a year's wages for a labourer.","https://www.christianity.com/wiki/bible/what-is-spikenard-in-the-bible.html"],"uncommon":["Spikenard grows at about 3,000 to 5,000 m in the Himalayas, mainly from Kumaon through Nepal and Sikkim to Bhutan.","https://en.wikipedia.org/wiki/Nardostachys_jatamansi"],"rare":["Spikenard, a member of the honeysuckle family, is considered endangered because of overharvesting of its roots, overgrazing and habitat loss.","https://en.wikipedia.org/wiki/Nardostachys_jatamansi"],"epic":["Pliny the Elder's Natural History lists several nards: Indian nard, a stinking nard unfit for perfume, and a false nard used to adulterate the real thing.","https://en.wikipedia.org/wiki/Spikenard"],"legendary":["In Iberian art St Joseph holds a spikenard branch, and in 2013 the Vatican said Pope Francis's coat of arms includes spikenard for that reason.","https://en.wikipedia.org/wiki/Spikenard"]},"staranise":{"common":["Star anise is a core ingredient of Chinese five-spice powder and a major flavour in phở, the Vietnamese noodle soup.","https://en.wikipedia.org/wiki/Illicium_verum"],"uncommon":["Star anise is rich in shikimic acid, the starting material for the flu drug Tamiflu, and until 2012 Roche used up to 90% of the world's star anise crop to make it.","https://en.wikipedia.org/wiki/Illicium_verum"],"rare":["Japanese star anise looks similar but is highly toxic, containing the neurotoxin anisatin. In Japan it has been burned as incense instead.","https://en.wikipedia.org/wiki/Illicium_verum"],"epic":["The genus name Illicium comes from the Latin illicio, meaning to entice or to seduce, while the species name verum means true.","https://en.wikipedia.org/wiki/Illicium_verum"],"legendary":["Anethole, which makes up about 87% of star anise oil, is about 13 times sweeter than sugar.","https://en.wikipedia.org/wiki/Anethole"]},"stephanotis":{"common":["Its waxy, scented blooms are a bridal bouquet staple, earning stephanotis the names bride's flower and Hawaiian wedding flower.","https://en.wikipedia.org/wiki/Marsdenia_floribunda"],"uncommon":["The name Stephanotis comes from the Greek stephanōtís, roughly fit for a crown, from stephanos, crown.","https://en.wikipedia.org/wiki/Stephanotis"],"rare":["Sold as Madagascar jasmine, stephanotis is no jasmine: it belongs to the dogbane family and can form large plum-like pods of seeds on fluffy parachutes that drift on the wind.","https://en.wikipedia.org/wiki/Marsdenia_floribunda"],"epic":["French botanist Louis-Marie Aubert du Petit-Thouars described the genus Stephanotis in 1806 in his Genera Nova Madagascariensia.","https://en.wikipedia.org/wiki/Stephanotis"],"legendary":["Its current genus, Marsdenia, named by Robert Brown in 1810, honours William Marsden, a plant collector and Secretary of the Admiralty.","https://en.wikipedia.org/wiki/Marsdenia"]},"strawberry":{"common":["Each seed on a strawberry is an achene, a tiny fruit of its own. Achenes are about 1% of the fresh weight yet supply 11% of its polyphenols.","https://en.wikipedia.org/wiki/Garden_strawberry"],"uncommon":["In 1712 Louis XIV sent the army engineer Amédée-François Frézier to spy in Chile. He brought back Chilean strawberry plants, which crossed in France with a Virginian species to create today's strawberry.","https://fruit.umn.edu/spy-botanist-strawberry"],"rare":["In 1766 Antoine Nicolas Duchesne, working in the gardens of the Palace of Versailles, found that the garden strawberry was a hybrid of Chilean and Virginian species.","https://en.wikipedia.org/wiki/Garden_strawberry"],"epic":["The species name ananassa, like the old English name pine strawberry, means pineapple, a reference to the fruit's flavour.","https://en.wikipedia.org/wiki/Garden_strawberry"],"legendary":["Garden strawberries are octoploid: each cell carries 8 sets of 7 chromosomes, 56 in all, where humans carry just 2 sets.","https://en.wikipedia.org/wiki/Garden_strawberry"]},"styrax":{"common":["Turkish harvesters strip about a quarter of the trunk to collect the thick sap from June to September, then soften it in boiling water and press it.","https://en.wikipedia.org/wiki/Liquidambar_orientalis"],"uncommon":["Ancient Egyptians used oriental sweetgum oil in embalming, and amphorae of it from sunken Phoenician ships show it was traded across the Mediterranean.","https://en.wikipedia.org/wiki/Liquidambar_orientalis"],"rare":["Turkey's pure oriental sweetgum forests cover 1,348 ha, down from 6,000 to 7,000 ha in the 1940s. The species is listed as endangered.","https://en.wikipedia.org/wiki/Liquidambar_orientalis"],"epic":["Styrene is named after storax. In 1839 Eduard Simon distilled it from the balsam as styrol and saw it harden into a solid later shown to be polystyrene.","https://en.wikipedia.org/wiki/Styrene"],"legendary":["Herodotus wrote that frankincense trees in Arabia were guarded by small winged serpents, and that harvesters drove them off by burning storax.","https://lexundria.com/hdt/3.107/mcly"]},"sugarcane":{"common":["By tonnage, sugarcane is the world's largest crop: 1.92 billion tonnes were harvested in 2022, 38% of it in Brazil.","https://en.wikipedia.org/wiki/Sugarcane"],"uncommon":["Persians and Greeks who reached India were amazed by sugar cane. Strabo recorded that reeds in India yield honey without bees.","https://en.wikipedia.org/wiki/Sugarcane"],"rare":["Sugarcane was first domesticated by Papuans in New Guinea, where selective breeding is dated to about 6,000 years ago.","https://en.wikipedia.org/wiki/Sugarcane"],"epic":["Columbus carried sugarcane to the Caribbean on his second voyage, and the first harvest on Hispaniola came in 1501.","https://en.wikipedia.org/wiki/Sugarcane"],"legendary":["In Mauritius, sugar factories generate over 100 kWh of electricity from each tonne of bagasse, the fibre left after the cane is crushed.","https://en.wikipedia.org/wiki/Sugarcane"]},"sweetpea":{"common":["Sweet pea seeds are toxic if eaten in quantity: they contain beta-aminopropionitrile, which disrupts collagen and causes scurvy-like symptoms.","https://en.wikipedia.org/wiki/Lathyrus_odoratus"],"uncommon":["Henry Eckford set up sweet pea trial fields in Wem, Shropshire, in 1888, and by 1901 had introduced 115 of the 264 cultivars then grown.","https://en.wikipedia.org/wiki/Lathyrus_odoratus"],"rare":["Franciscan monk Francesco Cupani first recorded the sweet pea in Sicily in his Hortus Catholicus of 1696, then is believed to have sent seed to English botanists.","https://en.wikipedia.org/wiki/Lathyrus_odoratus"],"epic":["In 1905 Bateson, Saunders and Punnett crossed sweet peas and found flower colour and pollen shape inherited together, the first experimental evidence of genetic linkage.","https://en.wikipedia.org/wiki/Genetic_linkage"],"legendary":["In the mid-19th century only 5 sweet pea cultivars existed. The UK National Collection, begun in Bognor Regis in 1991, now holds about 1,300.","https://en.wikipedia.org/wiki/Lathyrus_odoratus"]},"tagetes":{"common":["In the Andes Tagetes minuta is huacatay, a culinary herb whose paste flavours ocopa, a popular Peruvian potato dish.","https://en.wikipedia.org/wiki/Tagetes_minuta"],"uncommon":["Farmers grow Tagetes minuta as a green manure crop and as a bio-fumigant to control selected species of soil nematodes.","https://en.wikipedia.org/wiki/Tagetes_minuta"],"rare":["Despite its species name minuta, meaning small, this marigold grows 0.6 to 2 m tall.","https://en.wikipedia.org/wiki/Tagetes_minuta"],"epic":["In South Africa Tagetes minuta is called khakibos or khaki weed: it is thought to have arrived in imported fodder for British Army horses during the Anglo-Boer War of 1899 to 1902.","https://pza.sanbi.org/node/11929"],"legendary":["Marigold oil distilled from Tagetes minuta is used not only in perfume but also by the tobacco and soft drink industries.","https://en.wikipedia.org/wiki/Tagetes_minuta"]},"taifrose":{"common":["Over 500 million roses are picked in Taif each year between late March and April, on up to 860 local farms.","https://www.aramcolife.com/en/publications/the-arabian-sun/articles/2022/week-21-articles/taifs-flowers-a-blooming-industry"],"uncommon":["Taif roses are picked from daybreak, and harvesting stops by early morning, before the sun's heat cuts their oil to about half.","https://www.aramcolife.com/en/publications/the-arabian-sun/articles/2022/week-21-articles/taifs-flowers-a-blooming-industry"],"rare":["Twice a year the interior of the Kaaba in Mecca is washed with Zamzam water perfumed with Taif rose, oud and musk, splashed on the floor and wiped with palm leaves.","https://en.wikipedia.org/wiki/Kaaba"],"epic":["Rose bushes are not native to Taif. Legend says the Ottomans brought seedlings from the Levant for a Mecca nobleman, who planted them on cooler Al Hada mountain.","https://www.trtworld.com/magazine/taif-saudi-arabias-city-of-roses-blooms-anew-17632304"],"legendary":["A Taif still fills three bottles of distillate. The first, called bride's water, goes into beauty products; the second is for cooking and the third for drinking.","https://www.aramcolife.com/en/publications/the-arabian-sun/articles/2022/week-21-articles/taifs-flowers-a-blooming-industry"]},"tarragon":{"common":["Tarragon is one of the four fines herbes of French cooking.","https://en.wikipedia.org/wiki/Tarragon"],"uncommon":["French tarragon is shy to flower and rarely sets viable seed, so gardeners grow it by root division or cuttings; tarragon sold as seed is usually Russian tarragon.","https://www.rhs.org.uk/herbs/tarragon"],"rare":["Its species name dracunculus means little dragon, apparently for its coiled roots, and in Swedish and Dutch the plant is simply called dragon.","https://en.wikipedia.org/wiki/Tarragon"],"epic":["Tarkhuna, a carbonated soft drink named after the herb, is made from sugar, carbonated water and tarragon leaves.","https://en.wikipedia.org/wiki/Tarragon"],"legendary":["Fresh tarragon holds about 2,900 mg/kg of estragole. A risk estimate puts concern at about 130 g of leaves a day for an adult; a typical dish uses about 5 g.","https://en.wikipedia.org/wiki/Tarragon"]},"tea":{"common":["After plain drinking water, tea is the most widely consumed drink in the world.","https://en.wikipedia.org/wiki/Tea"],"uncommon":["In 1848 botanist Robert Fortune, sometimes disguised as a Chinese merchant, took tea plants and tea makers from China to India for the East India Company in glass Wardian cases.","https://en.wikipedia.org/wiki/Robert_Fortune"],"rare":["Chinese legend credits the mythical Shennong, said to have a transparent body, with finding tea when leaves from burning twigs drifted into his boiling cauldron.","https://en.wikipedia.org/wiki/Shennong"],"epic":["Pressed tea bricks served as currency in Tibet, Mongolia and Central Asia, and Siberians used them as edible money until World War II.","https://en.wikipedia.org/wiki/Tea_brick"],"legendary":["Leaves found at the tomb of Han Emperor Jing near Xi'an, identified by caffeine and theanine, show the Han court drank tea about 2,100 years ago.","https://www.nature.com/articles/srep18955"]},"teak":{"common":["Myanmar has the world's largest captive elephant population, about 5,500 in 2018, and most worked in logging. One elephant can drag around twenty one-tonne logs a day.","https://blog.nature.org/2018/07/16/saving-myanmars-timber-elephants/"],"uncommon":["Natural oils make teak resistant to termites and pests, and navies laid it on ship decks, including the US battleship USS Missouri.","https://en.wikipedia.org/wiki/Teak"],"rare":["Nilambur in Kerala, India, has the world's oldest teak plantation, and Tree No. 23 in its Conolly's plot is the oldest planted teak on Earth.","https://en.wikipedia.org/wiki/Teak"],"epic":["Teak has been used for boatbuilding for over 2,000 years: its wood has turned up in excavations at Berenice in Egypt.","https://en.wikipedia.org/wiki/Teak"],"legendary":["Teak was used in building the Kaaba in Mecca, whose roof is held up by 49 pieces of teak.","https://en.wikipedia.org/wiki/Teak"]},"teatree":{"common":["The name tea tree probably comes from Captain James Cook, who described a shrub used to make an infusion to drink in place of tea.","https://en.wikipedia.org/wiki/Tea_tree_oil"],"uncommon":["International standard ISO 4730 defines tea tree oil as the terpinen-4-ol type: that compound must make up 35 to 48% of the oil.","https://en.wikipedia.org/wiki/Tea_tree_oil"],"rare":["Tea tree oil, first studied as an antiseptic by chemist Arthur Penfold in the 1920s, was used during World War II to treat skin lesions in munitions factory workers.","https://en.wikipedia.org/wiki/Tea_tree_oil"],"epic":["Cats and dogs have died after high doses of tea tree oil were applied to their skin, so the oil should be kept away from pets.","https://en.wikipedia.org/wiki/Tea_tree_oil"],"legendary":["A 2018 US National Institute of Environmental Health Sciences study found four tea tree oil constituents, including eucalyptol, to be endocrine disruptors.","https://en.wikipedia.org/wiki/Tea_tree_oil"]},"thyme":{"common":["In the Middle Ages thyme was believed to give courage, so women often gave knights and warriors leaving for battle gifts that included thyme leaves.","https://en.wikipedia.org/wiki/Thyme"],"uncommon":["The ancient Greeks added thyme to their baths and burned it as incense in their temples.","https://en.wikipedia.org/wiki/Thyme"],"rare":["Ancient Egyptians used common thyme, Thymus vulgaris, in embalming their dead.","https://en.wikipedia.org/wiki/Thyme"],"epic":["Thymol, thyme's main aroma molecule, was first isolated in 1719 by German chemist Caspar Neumann. In the 1910s it was used in the US to treat hookworm infection.","https://en.wikipedia.org/wiki/Thymol"],"legendary":["The grayling's genus name, Thymallus, comes from the faint smell of thyme said to rise from the fish's flesh.","https://en.wikipedia.org/wiki/Thyme"]},"tiare":{"common":["In parts of the Pacific a tiaré flower tucked behind the left ear means the wearer is taken, while one behind the right ear means they are available.","https://en.wikipedia.org/wiki/Gardenia_taitensis"],"uncommon":["Monoï de Tahiti, protected by an appellation of origin since 1992, must steep at least 10 tiaré flowers per litre of refined coconut oil for at least 10 days.","https://www.ieom.fr/IMG/pdf/ne3_industrie_du_monoi_en_pf__fevrier2008_.pdf"],"rare":["Naturalists on Captain Cook's Pacific expedition collected tiaré in Tahiti but misidentified it as the common gardenia, Gardenia jasminoides.","https://en.wikipedia.org/wiki/Gardenia_taitensis"],"epic":["Tiaré is considered an aboriginal introduction to French Polynesia and the Cook Islands: early Polynesian settlers, not nature, brought it to the islands.","https://en.wikipedia.org/wiki/Gardenia_taitensis"],"legendary":["In Tonga an infusion of the tiaré shrub's bark is dripped into the nose, eyes and mouth as a traditional treatment for ghost sickness.","https://en.wikipedia.org/wiki/Gardenia_taitensis"]},"tobacco":{"common":["French ambassador Jean Nicot gave tobacco leaves to Catherine de' Medici to cure her migraines. Linnaeus named the genus Nicotiana after him, and nicotine takes its name from the plant.","https://en.wikipedia.org/wiki/Jean_Nicot"],"uncommon":["In colonial Virginia tobacco served as currency: notes for inspected tobacco paid debts, fees and taxes, and are seen as precursors of the US dollar.","https://www.worldhistory.org/article/1681/tobacco--colonial-american-economy"],"rare":["Cuban cigar rollers listened to a lector reading aloud as they worked. The Count of Monte Cristo was such a favourite that a brand founded in 1935 took its name.","https://en.wikipedia.org/wiki/Montecristo_(cigar)"],"epic":["Rodrigo de Jerez, a sailor on Columbus's 1492 voyage, took up smoking in the Americas. Back in Spain the Inquisition reportedly imprisoned him for 7 years for the habit.","https://en.wikipedia.org/wiki/Rodrigo_de_Jerez"],"legendary":["Tobacco hornworm caterpillars move nicotine from the leaves they eat into their blood and exhale it through their spiracles, a toxic breath that deters wolf spiders.","https://www.mpg.de/7685417/caterpillars-deter-spiders-with-nicotine"]},"tonka":{"common":["The US FDA banned tonka beans as a food ingredient in 1954 after coumarin caused liver damage in animals. Cinnamon, which also contains coumarin, was never banned.","https://daily.jstor.org/tonka-bean-the-tale-of-a-contested-commodity/"],"uncommon":["Coumarin was first isolated from tonka beans in 1820 by A. Vogel of Munich, who mistook it for benzoic acid. Its name comes from coumarou, French for the tonka bean.","https://en.wikipedia.org/wiki/Coumarin"],"rare":["To cure tonka beans, producers soak them in rum for about 24 hours and dry them; white coumarin crystals then show beneath the seed skin.","https://gernot-katzers-spice-pages.com/engl/Dipt_odo.html"],"epic":["William Perkin first made coumarin in a lab in 1868, and Houbigant's Fougère Royale of 1882 put it into perfume, helping define the fougère family.","https://en.wikipedia.org/wiki/Coumarin"],"legendary":["Radiocarbon dating of tonka tree stumps left by loggers near Manaus showed the species can live beyond 1,000 years; an age of about 1,400 years has been claimed.","https://en.wikipedia.org/wiki/Tonka_bean"]},"truffle":{"common":["In 2007 Macau casino owner Stanley Ho paid $330,000 for a single 1.5 kg Italian white truffle at an auction held in Macau, Hong Kong and Florence.","https://en.wikipedia.org/wiki/Tuber_magnatum"],"uncommon":["Many white truffle hunters around Alba prefer to search at night, when fewer people and animals are around to distract their dogs.","https://www.finedininglovers.com/article/digest-dark-side-white-truffle"],"rare":["Truffle hunting and extraction in Italy, done by tartufai with trained dogs, was added to UNESCO's list of the Intangible Cultural Heritage of Humanity in 2021.","https://ich.unesco.org/en/RL/truffle-hunting-and-extraction-in-italy-traditional-knowledge-and-practice-01395"],"epic":["In 2019 a four-year-old orchard in Nouvelle-Aquitaine, France, yielded 3 white truffles, which INRAE hailed as a global first in controlled white truffle production.","https://www.inrae.fr/en/news/controlled-production-white-truffles-made-france-global-first"],"legendary":["The Roman poet Juvenal wrote that truffles came from a lightning bolt Jupiter hurled at the earth, and many ancients believed they grew where lightning had struck.","https://tartufo.com/en/tales-and-the-cultural-history-of-the-truffle/"]},"tuberose":{"common":["In India tuberose is called rajnigandha, meaning fragrance of the night, a name earned by the heady scent its waxy white flowers pour out after dark.","https://flowersofindia.net/catalog/slides/Rajnigandha.html"],"uncommon":["Tuberose is not a rose. Its name comes from the Latin tuberosa, meaning swollen or tuberous, a reference to its root system.","https://en.wikipedia.org/wiki/Polianthes_tuberosa"],"rare":["Tuberose, believed native to central and southern Mexico, is no longer found in the wild, probably because the Aztecs domesticated it.","https://en.wikipedia.org/wiki/Polianthes_tuberosa"],"epic":["In 1885 Oscar Wilde and poet Marc-André Raffalovich argued in letters to The Pall Mall Gazette over whether tuberose should be said as tube rose or in three syllables.","https://en.wikipedia.org/wiki/Polianthes_tuberosa"],"legendary":["The Aztecs called tuberose omixochitl, which suggests bone flower, and linked it to Xochipilli, god of flowers. In Spanish it became flor de hueso.","https://nahuatl.wired-humanities.org/node/200099"]},"tulip":{"common":["At the height of Dutch tulip mania in the 1630s, a single prized tulip bulb was sold for as much as 10,000 guilders.","https://en.wikipedia.org/wiki/Tulip"],"uncommon":["During the Dutch Hunger Winter of 1944 to 1945, soup kitchens often served soup made from sugar beets, potato peels and tulip bulbs.","https://en.wikipedia.org/wiki/Dutch_famine_of_1944–1945"],"rare":["The word tulip may come from Ottoman Turkish tülbend, muslin or gauze, and perhaps ultimately Persian dulband, turban, after the flower's turban-like shape.","https://en.wikipedia.org/wiki/Tulip"],"epic":["The flamed petals prized in tulip mania came from a virus spread by aphids, shown by bulb experiments Dorothy Cayley began in 1928. The virus also weakened the bulbs.","https://en.wikipedia.org/wiki/Tulip_breaking_virus"],"legendary":["During the Ottoman Tulip Era under Ahmed III, tulip-time garden parties were lit by thousands of lamps and by tortoises ambling through the beds with candles on their backs.","https://ebsco.com/research-starters/arts-and-entertainment/tulip-age"]},"turmeric":{"common":["Turmeric is approved as a food colour in the European Union and other countries under the code E100, lending its yellow to curries, mustards and more.","https://en.wikipedia.org/wiki/Turmeric"],"uncommon":["In Bengal the gaye holud ceremony is part of wedding celebrations, and in Tamil Nadu and Andhra Pradesh a dried turmeric tuber on a string can form the bride's thali necklace.","https://en.wikipedia.org/wiki/Turmeric"],"rare":["Paper soaked in turmeric is a chemist's pH indicator: it stays yellow in acidic and neutral solutions and turns reddish-brown in alkaline ones.","https://en.wikipedia.org/wiki/Turmeric"],"epic":["Traces of turmeric were found at Farmana, a Harappan site in India dating to between 2600 and 2200 BCE, and in a merchant's tomb at Megiddo in Israel.","https://en.wikipedia.org/wiki/Turmeric"],"legendary":["In Bangladesh, turmeric was found adulterated with lead chromate, a bright yellow pigment, with contamination up to 500 times the national limit.","https://en.wikipedia.org/wiki/Turmeric"]},"vanilla":{"common":["Measured by weight, vanilla is the world's second most expensive spice after saffron, because growing and curing the pods takes so much labour.","https://en.wikipedia.org/wiki/Vanilla"],"uncommon":["In 1841 Edmond Albius, a 12-year-old enslaved boy on Réunion, worked out how to hand-pollinate vanilla flowers, yet he died poor in 1880.","https://linnean.org/news/2019/10/16/edmond-albius"],"rare":["Each vanilla flower lasts about one day, sometimes less, so growers must check the vines daily and pollinate every open bloom in time.","https://en.wikipedia.org/wiki/Vanilla"],"epic":["The Totonac people of Mexico were among the first to domesticate vanilla. When the Aztecs invaded the Totonacs in 1427, they developed a taste for the pods.","https://en.wikipedia.org/wiki/Vanilla"],"legendary":["By 1874 vanillin, vanilla's key flavour molecule, was being made from glycosides in pine tree sap, and today some is made from lignin, a polymer found in wood.","https://en.wikipedia.org/wiki/Vanilla"]},"vanuatusandal":{"common":["Young Vanuatu sandalwood trees are semi-parasitic: their roots tap into nearby host plants and drink their sap.","https://en.wikipedia.org/wiki/Santalum_austrocaledonicum"],"uncommon":["When sandalwood traders reached New Caledonia in the 1840s, they took about 8,000 tonnes of the wood from its islands in the first 15 years.","https://en.wikipedia.org/wiki/Santalum_austrocaledonicum"],"rare":["Trader Peter Dillon learned of Erromango's large sandalwood reserves in 1825, but his trade goods were not enough to persuade islanders to cut the timber for him.","https://en.wikipedia.org/wiki/Erromango"],"epic":["Samuel Henry's crew cut up to 4 tonnes of sandalwood a day on Erromango, and nearly a hundred of his Tongan labourers died harvesting it. By 1865 the island's supply was exhausted.","https://en.wikipedia.org/wiki/Erromango"],"legendary":["In 1830 King Kamehameha III of Hawaii sent two ships with 479 men to seize Erromango's sandalwood. One ship exploded at anchor, and only 20 Hawaiians made it home.","https://en.wikipedia.org/wiki/Erromango"]},"verbena":{"common":["Lemon verbena's leaves give a lemon flavour to herbal teas, jams, puddings, marinades and liqueurs, with no citrus fruit involved.","https://en.wikipedia.org/wiki/Aloysia_citrodora"],"uncommon":["Citral, a lemon-scented molecule, makes up about 30 to 35% of lemon verbena oil, with nerol and geraniol as other major components.","https://en.wikipedia.org/wiki/Aloysia_citrodora"],"rare":["Lemon verbena's genus name, Aloysia, honours Maria Luisa of Parma, the Italian princess who married King Carlos IV of Spain.","https://plants.ces.ncsu.edu/plants/aloysia-citriodora/common-name/lemon-beebrush/"],"epic":["Verbena essential oil is skin-sensitising and phototoxic, so the EU bans verbena oils, other than the absolute, as fragrance ingredients.","https://en.wikipedia.org/wiki/Aloysia_citrodora"],"legendary":["The Spanish and Portuguese brought lemon verbena from South America to Europe in the 17th century, and French botanist Philibert Commerson collected it in Buenos Aires around 1767.","https://en.wikipedia.org/wiki/Aloysia_citrodora"]},"vetiver":{"common":["Vetiver roots grow 2 to 4 m straight down, deeper than some tree roots, so hedges of the grass are planted to hold slopes, riverbanks and railway embankments against erosion.","https://en.wikipedia.org/wiki/Chrysopogon_zizanioides"],"uncommon":["In India mats woven from vetiver roots are hung in doorways and kept wet, cooling the air that passes through and filling the room with a fresh scent.","https://en.wikipedia.org/wiki/Chrysopogon_zizanioides"],"rare":["Lucien Ganot brought vetiver processing to Haiti in the 1940s, and Pierre Léger's plant ran 44 stills, each taking a tonne of roots. Haiti became the world's largest producer.","https://en.wikipedia.org/wiki/Chrysopogon_zizanioides"],"epic":["Stem borer moths lay their eggs on vetiver, but the plant's hairy leaves stop the hatched larvae from moving onto them, so they fall and die.","https://en.wikipedia.org/wiki/Chrysopogon_zizanioides"],"legendary":["DNA profiling shows that nearly all vetiver grown worldwide is essentially the same sterile cultivated plant, which is why hedges of it rarely spread out of control.","https://en.wikipedia.org/wiki/Chrysopogon_zizanioides"]},"violet":{"common":["The violet was a favourite flower in ancient Greece and became the symbol of Athens.","https://en.wikipedia.org/wiki/Viola_odorata"],"uncommon":["Violets play hide and seek: their ionones first stimulate our smell receptors, then briefly switch them off, so the scent seems to vanish and return moments later.","https://sciencebase.com/science-blog/the-fading-scent-of-violets.html"],"rare":["In Greek myth Persephone was gathering violets and other flowers when Hades abducted her. The Greek word ion, for violet, later gave ionones their name.","https://en.wikipedia.org/wiki/Viola_odorata"],"epic":["By the late 1950s, production of true violet flower extract had almost disappeared, so perfumers rebuilt the flower in the lab, while violet leaf absolute is still widely used.","https://en.wikipedia.org/wiki/Viola_odorata"],"legendary":["Sweet violet contains a peptide, vodo-C1, that in lab tests acts on the body's CB2 cannabinoid receptor, a target shared with compounds from cannabis.","https://en.wikipedia.org/wiki/Viola_odorata"]},"waterlily":{"common":["Claude Monet painted about 250 oil paintings of the water lilies in his garden pond at Giverny, the main focus of the last 31 years of his life.","https://en.wikipedia.org/wiki/Water_Lilies_(Monet_series)"],"uncommon":["Nymphaea nouchali is the national flower of both Bangladesh, where it is called shapla, and Sri Lanka, where a pale blue form is known as nil mānel.","https://en.wikipedia.org/wiki/Nymphaea_nouchali"],"rare":["In Bangladesh the water lily's stems, called shapla, are a regular vegetable cooked as shaplar data with mustard seeds and spices, though the plant is otherwise poisonous.","https://en.wikipedia.org/wiki/Nymphaea_nouchali"],"epic":["Sri Lankan Buddhist lore counts this blue water lily among the 108 auspicious signs on the footprint of Prince Siddhartha.","https://en.wikipedia.org/wiki/Nymphaea_nouchali"],"legendary":["Designer Clare Waight Keller embroidered this water lily into Meghan Markle's 2018 wedding veil to represent Sri Lanka and Bangladesh among Commonwealth flowers.","https://en.wikipedia.org/wiki/Nymphaea_nouchali"]},"watermelon":{"common":["The largest watermelon on record was grown in Tennessee in 2013 and weighed 159 kg; the fruit itself is about 91% water.","https://en.wikipedia.org/wiki/Watermelon"],"uncommon":["China is the world's leading watermelon producer, growing about 64% of the roughly 105 million tonnes harvested worldwide in 2023.","https://en.wikipedia.org/wiki/Watermelon"],"rare":["Watermelons depend on bees: the USDA recommends at least one beehive per acre of crop, rising to three hives per acre for seedless varieties.","https://en.wikipedia.org/wiki/Watermelon"],"epic":["Watermelon was cultivated in Egypt by 2000 BC, and an image of what seems to be one on a tray has been found in an Egyptian tomb.","https://en.wikipedia.org/wiki/Watermelon"],"legendary":["A 2021 genome study suggests a melon from the Kordofan region of Sudan may be the wild ancestor of today's domesticated watermelons.","https://en.wikipedia.org/wiki/Watermelon"]},"whisky":{"common":["The word whisky comes from Gaelic uisge beatha, a translation of the Latin aqua vitae, meaning water of life.","https://en.wikipedia.org/wiki/Whisky"],"uncommon":["Islay malts taste smoky because the malted barley is dried over burning peat. The island, a principal whisky region, has nine distilleries.","https://en.wikipedia.org/wiki/Whisky"],"rare":["The first written evidence of Scotch whisky is a 1495 Exchequer Rolls entry giving Friar John Cor malt, by order of the king, to make aquavitae: enough for about 500 bottles.","https://en.wikipedia.org/wiki/Whisky"],"epic":["In 2011 Islay's Ardbeg distillery sent vials of spirit and oak particles to the International Space Station to study how they interact in orbit. They came back in 2014.","https://en.wikipedia.org/wiki/Ardbeg_distillery"],"legendary":["In 1941 the SS Politician ran aground off Eriskay with 22,000 cases of whisky. Islanders spirited bottles away at night, 19 men were jailed, and the tale became Whisky Galore.","https://en.wikipedia.org/wiki/SS_Politician"]},"wisteria":{"common":["Wisteria's brown, velvety, bean-like seed pods look edible but are poisonous, and they hang on the vine until winter.","https://en.wikipedia.org/wiki/Wisteria_floribunda"],"uncommon":["A wisteria in Sierra Madre, California, bought for 75 cents in 1894, now covers over an acre and weighs over 250 tons; Guinness named it the largest blossoming plant in 1990.","https://en.wikipedia.org/wiki/Sierra_Madre_Wisteria"],"rare":["Japanese wisteria's stems twine clockwise as they climb, and with support the vine can reach more than 30 m.","https://en.wikipedia.org/wiki/Wisteria_floribunda"],"epic":["The great wisteria of Ashikaga, dated to 1870, covered about 1,990 square metres by May 2008, a vast purple ceiling grown from a single plant.","https://en.wikipedia.org/wiki/Wisteria_floribunda"],"legendary":["Ushijima-no-fuji, a Japanese wisteria said to be 1,200 years old, is a special natural monument; in the Meiji period its flower clusters hung about 3 m long.","https://en.wikipedia.org/wiki/Wisteria_floribunda"]},"ylang":{"common":["In Indonesia ylang-ylang flowers are spread on the bed of newlywed couples.","https://en.wikipedia.org/wiki/Cananga_odorata"],"uncommon":["Ylang-ylang oil is steam-distilled from the flowers and split into grades, extra, 1, 2 or 3, according to when each part of the distillate is collected.","https://en.wikipedia.org/wiki/Cananga_odorata"],"rare":["Ylang-ylang is the Spanish spelling of the Tagalog name ilang-ilang. It is often said to mean flower of flowers, but that is a common mistranslation.","https://en.wikipedia.org/wiki/Cananga_odorata"],"epic":["Victorian Macassar hair oil, often scented with ylang-ylang, stained chair backs so badly that the antimacassar cloth was invented. Byron praised the incomparable oil in Don Juan.","https://en.wikipedia.org/wiki/Macassar_oil"],"legendary":["In 1998 ylang-ylang essential oil made up 29% of the Comoros' annual exports, making one flower a pillar of an island nation's economy.","https://en.wikipedia.org/wiki/Cananga_odorata"]},"yuzu":{"common":["On the winter solstice many Japanese take yuzuyu, a hot bath with whole yuzu fruits floating in it, a custom dating back to at least the early 18th century.","https://en.wikipedia.org/wiki/Yuzu"],"uncommon":["Yuzu kosho is a spicy Japanese condiment of green or yellow yuzu zest, chili and salt, and yuzu juice is a key ingredient of the citrus sauce ponzu.","https://en.wikipedia.org/wiki/Yuzu"],"rare":["Yuzu trees commonly bristle with many large thorns, so growers have bred cultivars such as 'No 5', with few or no thorns, and Hana, with smaller ones.","https://en.wikipedia.org/wiki/Yuzu"],"epic":["A Japanese saying runs: peaches and chestnuts take three years, persimmons eight, and the great fool yuzu eighteen, a nod to how long a seedling yuzu takes to fruit.","https://dime.jp/genre/1138405/"],"legendary":["Yuzu is believed to be a natural cross of a mandarin and the ichang papeda from central China. Introduced to Japan during the Tang dynasty, it survives winters down to -7 °C.","https://en.wikipedia.org/wiki/Yuzu"]},"hyraceum":{"common":["The rock hyrax looks like a big guinea pig, but its teeth, toes and skull resemble an elephant's, and two of its incisors grow into small tusks.","https://animals.sandiegozoo.org/node/233"],"uncommon":["South African healers use hyraceum against epilepsy, and in a 2007 study 4 of 14 samples bound the brain receptor targeted by diazepam.","https://en.wikipedia.org/wiki/Hyraceum"],"rare":["Male rock hyraxes sing songs whose syllable order follows syntax-like rules, and a 2012 study in Israel found those rules differ by region, like dialects.","https://cris.haifa.ac.il/en/publications/syntactic-structure-and-geographical-dialects-in-the-songs-of-mal/"],"epic":["Layered hyrax middens trap pollen and stable isotopes, giving scientists continuous climate records for southern Africa spanning the last 50,000 years.","https://cordis.europa.eu/project/id/258657"],"legendary":["A traditional reading makes Hispania Phoenician for 'island of the hyrax', as sailors took Iberia's many rabbits for the hyraxes they knew.","https://www.wiktionary.com/wiki/Hispania"]},"castoreum":{"common":["The US FDA lists castoreum as generally recognised as safe, and it has been used to flavour vanilla, strawberry and raspberry foods, yet total US use in all forms is only about 292 pounds a year.","https://www.snopes.com/fact-check/castoreum"],"uncommon":["Castoreum was long valued for pain and inflammation; its effect came from salicin, the aspirin-like compound beavers take in from the willow bark they eat.","https://www.the-scientist.com/the-quest-for-pain-relief-48945"],"rare":["Trappers dabbed castoreum on a twig or mud beside their traps because its smell draws beavers in, and a 1964 account blamed the lure for exhausting beaver numbers.","https://dchp.arts.ubc.ca/entries/castoreum"],"epic":["Aesop, Pliny and medieval bestiaries claimed that a hunted beaver bites off its testicles, the supposed source of castoreum, and throws them to the hunter.","https://bestiary.ca/beasts/beastsource152.htm"],"legendary":["Beavers were wiped out in Sweden in the 19th century, partly for castoreum used in medicine; animals brought from Norway in the 1920s grew to about 100,000.","https://www.thelocal.se/20130915/50250"]},"baobab":{"common":["Its squat trunk and root-like branches earned the baobab the name 'upside-down tree', and one tale says God planted it that way.","https://pza.sanbi.org/node/9652"],"uncommon":["Baobab flowers open in the late afternoon, are pollinated by fruit bats at night and fall within 24 hours, turning brown and smelling unpleasant.","https://pza.sanbi.org/node/9652"],"rare":["In June 2008 the EU authorised dried baobab fruit pulp as a novel food ingredient, after an application from the trade group PhytoTrade Africa.","https://www.legislation.gov.uk/eudn/2008/575/data.xht"],"epic":["A 2018 study found that 9 of the 13 oldest and 5 of the 6 largest African baobabs had died, or lost their oldest stems, in about 12 years.","https://nosamsresearch.whoi.edu/node/2886"],"legendary":["Chapman's Baobab near Gweta, 25 m round, served passing explorers and traders as a post office and navigation beacon until it fell on 7 January 2016.","https://en.wikipedia.org/wiki/Gweta"]},"cashew":{"common":["The cashew nut is the true fruit, a kidney-shaped drupe hanging below the fleshy cashew apple, which grows from the swollen flower stalk.","https://en.wikipedia.org/wiki/Cashew"],"uncommon":["Cashew shells hold irritant anacardic acids, as the tree belongs to the poison ivy family, so the nuts are roasted at high heat and never sold in the shell.","https://www.ipm.org/amomentofscience/why-cashews-arent-sold-in-the-shell/"],"rare":["Native to northeastern Brazil, the cashew was taken by Portuguese explorers to Goa in India and then to Mozambique in the 16th century.","https://www.echocommunity.org/resources/7393c8aa-0842-4787-a247-b57e2d6036b8"],"epic":["In 1973 Mozambique processed 210,000 tonnes of cashews, second only to India, a level the country has only approached again in the mid-2020s.","https://clubofmozambique.com/news/mozambique-cashew-production-nears-record-highs-set-50-years-ago-285577/"],"legendary":["A cashew at Pirangi do Norte, Brazil, covers about 8,500 m² because its branches take root where they touch the ground and grow into clone trunks.","https://www.guinnessworldrecords.com/world-records/113603-largest-cashew-nut-tree"]},"clementine":{"common":["Clementines are seedless unless bees bring pollen from other citrus, and in 2009 a California grower threatened beekeepers with legal action over seedy fruit.","https://www.nbclosangeles.com/news/oddities/tangerine-growers-tell-beekeepers-to-buzz-off/1892893/?amp=1"],"uncommon":["Under Corsica's 2007 IGP rules, clementines must be hand-picked with their leaves still attached, and colouring treatments are banned.","https://www.france.fr/en/article/corsican-clementine/"],"rare":["The clementine is a hybrid of a mandarin tree pollinated by a sweet orange, and its name copies the '-ine' ending of the French 'mandarine'.","https://www.laculturegenerale.com/origine-clementine/"],"epic":["Cold-pressed clementine peel oil is about 88 to 89% limonene, with myrcene next at about 4% and linalool around 1%.","https://avesis.istanbul.edu.tr/yayin/116dad9b-a7ac-49de-8e4f-2700033f61fa/volatiles-in-turkish-clementine-citrus-clementina-hort-peel"],"legendary":["In 2014 scientists sequenced a haploid clementine as the reference genome for citrus, revealing how mandarins, pummelos and oranges interbred during domestication.","https://www.citrusgenomedb.org/pub/9553"]},"marula":{"common":["Amarula, a South African cream liqueur made with marula fruit, was first marketed in 1989 and carries an elephant as its emblem.","https://en.wikipedia.org/wiki/Amarula"],"uncommon":["Marula pulp holds more vitamin C than most fruits, with studies measuring from 62 mg to over 400 mg per 100 g.","https://research.wur.nl/en/publications/a-review-of-the-proximate-composition-and-nutritional-value-of-ma"],"rare":["Marula trees are either male or female, and in folk medicine bark from a female tree is taken in pregnancy for a girl and from a male tree for a boy.","https://pza.sanbi.org/node/10927"],"epic":["At Pomongwe Cave in Zimbabwe, people ate an estimated 24 million marula fruits, and marula has been a food since at least 10,000 BC.","https://www.krugerpark.co.za/africa_marula.html"],"legendary":["A 2006 study found an elephant would need about 1.9 litres of ethanol, over 1,400 fermented marulas eaten at once, to get tipsy, so the drunk-elephant tale is a myth.","https://www.bristol.ac.uk/news/2006/11363083475.html"]},"kaffirlime":{"common":["The leaves, used fresh or dried, give Thai tom yum soup its characteristic flavour and also go into curries, stews and sauces across Southeast Asia.","https://www.botanischetuinen.nl/en/plant_en/2613/thai-lime-or-makrut-lime-or-mauritius-papeda"],"uncommon":["Its leaf stalk is so broadly winged that it is almost as large and wide as the leaf blade itself, giving each leaf a double, hourglass look.","https://citrusvariety.ucr.edu/crc2454"],"rare":["Its major traditional use seems to have been as an insecticide: the fruit was used to wash the head and treat the feet to kill land leeches. One of its English names is leech-lime.","https://uses.plantnet-project.org/en/Citrus_hystrix_(PROSEA)"],"epic":["Cabuyao, a city in Laguna in the Philippines, takes its name from kabuyaw, the local word for Citrus hystrix trees that grew around its old wharf.","https://en.wikipedia.org/wiki/Cabuyao"],"legendary":["A 2023 study found the citronellal in kaffir lime leaf oil is 100% the (-) form, with none of its mirror-image (+) twin detected.","https://www.mdpi.com/1420-3049/28/3/1381"]},"matcha":{"common":["In the 16th century Uji growers began covering tea fields with reed screens, which gives matcha its vivid dark green colour and strong umami taste.","https://artsandculture.google.com/story/a-walk-through-the-800-year-history-of-japanese-tea-kyoto-prefecture/fwWRJAlX1cVVKQ?hl=en"],"uncommon":["A traditional granite mill turns so slowly that it produces only about 40 g of matcha in an hour.","https://global.tokichi.jp/blogs/life-with-tea/matcha-processing-difference"],"rare":["The seaweed-like aroma of tencha, the shaded leaf ground into matcha, is linked to dimethyl sulfide together with pyrazines and beta-ionone.","https://www.frontiersin.org/journals/nutrition/articles/10.3389/fnut.2023.1153983/pdf"],"epic":["A stone in Uji carries a poem in which the monk Myoe gives villagers tea seeds from Mt Toga and tells them to plant them in his horse's hoofprints.","https://www.pref.kyoto.jp/kyotoyamashiro/pdf/ujicha_yamashiro_english2.pdf"],"legendary":["Jars of Uji tea carried to the shogun in Edo made even daimyo step aside. The children's song Zui zui zukkorobashi is thought to be about the procession.","https://ec.yamamotoyama.co.jp/en/blogs/column/reading237"]},"kewra":{"common":["Kewra water, the hydrosol left from distilling the flowers, perfumes biryani and sweets such as rasgulla, gulab jamun and ras malai.","https://fraterworks.com/a/library/kewra"],"uncommon":["Pluckers in Ganjam gather the spiky male flowers before dawn, because the flower loses its strength once the sun is up and hot.","https://www.etvbharat.com/en/state/indias-fragrant-empire-how-ganjams-kewda-industry-smells-good-inspite-of-cyclones-salinity-and-market-pressures-enn25112201127"],"rare":["Kewda oil is dominated by 2-phenylethyl methyl ether, at about 65 to 75%, with terpinen-4-ol next at about 12 to 20%.","https://en.wikipedia.org/wiki/Kewra"],"epic":["In Hindu myth the ketaki flower lied for Brahma about reaching the top of Shiva's pillar of fire, so Shiva barred it from ever being offered in his worship.","https://ecoheritage.cpreec.org/?p=1877"],"legendary":["Rooh kewda, the pure oil, sells for about US$7,000 a kilo, and roughly a thousand flowers are needed for a single ounce.","https://en.wikipedia.org/wiki/Ganjam_Kewda_Rooh"]},"dragonfruit":{"common":["Dragon fruit grows on a fast, climbing cactus that clings to trees and walls with aerial roots; it is native to southern Mexico and Central America.","https://www.gardenia.net/plant/hylocereus-undatus"],"uncommon":["Its flowers open at night and can reach 36 cm long; moths and bats are good pollinators, and growers often pollinate them by hand.","https://ask.ifas.ufl.edu/publication/HS303/pdf"],"rare":["Binh Thuan farmers light their cactus rows at night to trigger off-season flowering; switching to compact fluorescent lamps cut costs by up to US$485 a hectare.","https://www.unep.org/news-and-stories/story/viet-nam-dragon-fruit-orchards-bloom-new-light"],"epic":["The French brought dragon fruit to Vietnam in the 19th century, and it stayed a garden plant until commercial planting began in Binh Thuan in the early 1980s.","https://ap.fftc.org.tw/node/1598"],"legendary":["In the early 1990s, one researcher claimed, a single kilogram of dragon fruit in Vietnam cost enough to buy a bicycle.","https://saigoneer.com/natural-selection/26016-thanh-long-how-dragon-fruit-proves-beauty-is-only-skin-deep"]},"ginseng":{"common":["The name ginseng comes from the Chinese jen-shen, plant-man, after the root's human shape, and the genus name Panax from the Greek for a cure-all.","https://examine.com/supplements/panax-ginseng/faq/what-is-the-history-and-etymology-of-panax-ginseng"],"uncommon":["After a harvest, a ginseng field must rest for up to 10 years, so Geumsan farmers rotate in rice or green manure crops.","https://www.korean-culture.org/eng/webzine/201907/sub02.html"],"rare":["Geumsan legend says that about 1,500 years ago a scholar named Kang prayed in a cave on Jinaksan for his sick mother and was shown the healing root in a dream.","https://www.hansik.or.kr/magazines/list/magazineDetail/60/3396"],"epic":["Selling Korean red ginseng was a government monopoly from 1899 until 1996, and the Cheong-Kwan-Jang brand name means officially government approved.","https://www.koreajoongangdaily.com/business/the-tumultuous-history-of-a-tiny-healthy-root/11681183"],"legendary":["In 1716 a Jesuit at Kahnawake, helped by a Mohawk woman and a drawing of Chinese ginseng, found the plant in Canada; the hunt that followed nearly wiped it out there.","https://www.biographi.ca/en/bio/lafitau_joseph_francois_3E.html"]},"thanaka":{"common":["Thanaka paste is worn on the face in circles, stripes or leaf shapes; it gives a cooling feel and protects the skin against sunburn.","https://en.wikipedia.org/wiki/Thanaka"],"uncommon":["Thanaka trees must grow for at least 35 years before they are harvested for good-quality cuttings.","https://jddonline.com/articles/dermatology/S1545961614P0306X"],"rare":["Ko Taung Bo village in Sagaing is one of Myanmar's main suppliers of kyauk pyin, the round stone slabs for grinding thanaka, cut from a mountain about 2.5 miles away.","https://www.irrawaddy.com/?p=48494"],"epic":["The earliest written mention of thanaka is in a 14th-century poem attributed to a Mon-speaking consort of King Razadarit.","https://en.wikipedia.org/wiki/Thanaka"],"legendary":["Thanaka bark contains marmesin, a compound that absorbs a wide range of UV-A light, with its peak at 335 nm.","https://mdpi-res.com/d_attachment/cosmetics/cosmetics-08-00068/article_deploy/cosmetics-08-00068-v4.pdf"]},"iliahi":{"common":["Hawaii exported sandalwood to China from about 1792 to 1843, so Chinese people called the islands Tan Heung Shan, the Fragrant Sandalwood Hills.","https://en.wikipedia.org/wiki/Chinese_immigration_to_Hawaii"],"uncommon":["Iliahi is a root parasite: it grows special roots called haustoria that tap into nearby host plants to take extra nutrients.","https://ntbg.org/database/plants/detail/santalum-paniculatum"],"rare":["Hawaiians dug pits in the forest to the size of a ship's hold and filled them with logs, so traders knew when there was a full cargo to haul down.","https://imagesofoldhawaii.com/lua-na-moku-%ca%bbiliahi-sandalwood-pit/"],"epic":["Commoners carried the logs down mountain trails on their backs, sometimes cutting by torchlight; the calluses earned them the name kua leho, callous back.","https://keolamagazine.com/land/the-story-of-iliahi/"],"legendary":["Hawaii's first written law, in December 1826, was a sandalwood tax: each man owed half a picul (about 67 lb) of wood or 4 Spanish dollars.","https://the.honoluluadvertiser.com/article/2006/Apr/14/il/FP604140306.html"]},"niaouli":{"common":["Niaouli's trunk is wrapped in many layers of brownish-white bark that peels away in thin, paper-like sheets, which is why its cousins are called paperbarks.","https://plant-directory.ifas.ufl.edu/site/assets/files/1197/invasiveplants_melaleuca.pdf"],"uncommon":["The pharmacy oil Gomenol, a rectified niaouli oil, is named after Gomen in New Caledonia, where Jules Prevet began production; it was trademarked in 1893.","https://blog.soin-et-nature.com/en/essential-oil-of-niaouli-the-essence-of-gomen-which-gave-gomenol/"],"rare":["Niaouli resprouts vigorously from buds under its bark after bushfires and has been recorded flowering within weeks of being burnt.","https://en.wikipedia.org/wiki/Melaleuca_quinquenervia"],"epic":["In Florida, where it escaped as the punk tree, a single tree can release about 20 million seeds a year; it covered an estimated 500,000 acres by 1993.","https://en.wikipedia.org/wiki/List_of_invasive_species_in_the_Everglades"],"legendary":["Melaleuca seed was scattered by airplane over the Everglades in a bid to help dry out the swamps, and the tree became one of Florida's worst invaders.","https://en.wikipedia.org/wiki/List_of_invasive_species_in_the_Everglades"]},"agave":{"common":["Tequila became Mexico's first appellation of origin in 1974. It may only be made from blue agave grown in set areas of five states: Jalisco, Guanajuato, Michoacán, Nayarit and Tamaulipas.","https://www.wipo.int/en/web/ip-advantage/w/stories/liquid-gold-from-the-agave"],"uncommon":["Ripe agave hearts, or pinas, average about 32 kg, and a 1-litre bottle of 100% agave tequila takes about 7 kg of them.","https://www.diffordsguide.com/encyclopedia/991/bundle/tequila-how-is-tequila-made-and-what-from"],"rare":["Blue agave flowers open at night for long-nosed bats, and bat expert Rodrigo Medellín has urged tequila makers to let 5% of plants flower. In 2016 three bat-friendly agave spirits went on sale in the US.","https://www.mentalfloss.com/animals/surprising-role-bats-play-making-your-margarita"],"epic":["Long before tequila was distilled in the 16th century, agave in this region had been used for at least 2,000 years to make fermented drinks and cloth.","https://whc.unesco.org/en/list/1209"],"legendary":["In 2008 UNAM physicists vaporised 80-proof tequila blanco and heated it to 800 °C, growing thin films of real diamond crystals on silicon and steel.","https://phys.org/news145255770.html"]},"banana":{"common":["Botanically a banana is a berry, and the plant that bears it is not a tree but the largest herbaceous flowering plant, usually about 5 m tall.","https://en.wikipedia.org/wiki/Banana"],"uncommon":["Isoamyl acetate is the main banana ester behind candy flavour; the fruit it is said to mimic, the Gros Michel, was wiped out commercially by Panama disease by the 1960s.","https://www.sciencefriday.com/articles/why-dont-banana-candies-taste-like-real-bananas/"],"rare":["An average banana holds about 15 Bq of natural potassium-40, giving roughly 0.1 microsieverts, a dose scientists use as a yardstick called the banana equivalent dose.","https://ionactive.co.uk/resource-hub/guidance/radioactive-bananas-banana-equivalent-dose"],"epic":["Machala crowns a Reina Mundial del Banano, a World Banana Queen; in 2025 the pageant drew 21 candidates from banana-growing and banana-eating countries.","https://www.expreso.ec/ocio/reina-mundial-del-banano-2025-alba-saura-se-lleva-la-corona-espana-257925.html"],"legendary":["Under ultraviolet light ripening bananas glow bright blue, as chlorophyll breaks down into fluorescent compounds in the peel, a 2008 finding from Innsbruck and Columbia.","https://www.sciencedaily.com/releases/2008/10/081020093454.htm"]},"blueberry":{"common":["Wild blueberry fields are pruned by burning or mowing on a two-year cycle: the plants regrow from underground rhizomes and give their best crop in the second year.","https://cdn.dal.ca/content/dam/dalhousie/images/sites/wild-blueberry/pdfs/Pruning%20Wild%20Blueberries.pdf"],"uncommon":["Dolbeau-Mistassini calls itself the world capital of the wild bleuet and has held a blueberry festival every year since 1960.","https://crwflags.com/FOTW/flags/ca-qcdmi.html"],"rare":["Bumblebees buzz blueberry flowers to shake out pollen, which honeybees cannot do. Vermont researchers copied the buzz with electric toothbrushes, then brushed the pollen onto over 5,000 flowers.","https://www.uvm.edu/news/gund/secret-better-berries-wild-bees"],"epic":["Mi'kmaq people use lowbush blueberry leaves and roots for rheumatism, and Algonquin and Cree people use the leaf tea for women's and infant health in pregnancy.","https://thecanadianencyclopedia.ca/en/article/blueberry"],"legendary":["A blueberry's pigments are dark red; its blue comes from a thin wax bloom of tiny crystals that scatter blue and UV light, a 2024 Bristol finding.","https://bristol.ac.uk/news/2024/february-/blueberries.html"]},"acai":{"common":["An açaí berry is only about 25 mm in circumference with pulp 1 mm thick or less: the seed makes up roughly 60 to 80% of the fruit.","https://en.wikipedia.org/wiki/A%C3%A7a%C3%AD_palm"],"uncommon":["At Belém's Ver-o-Peso, the açaí market opens in the small hours: trading starts around 2 a.m. and peaks about 4:30, with boats arriving after up to 30 hours on the rivers.","https://www.360meridianos.com/feira-do-acai-belem/"],"rare":["Kissing bugs drawn to baskets of fruit can be blended into fresh açaí and pass on Chagas disease; a 10-second dip in boiling water has been mandatory since 2012.","https://www.scidev.net/global/news/a-a-fruit-can-transmit-chagas-disease/"],"epic":["The word açaí comes from the Tupian ïwasa'i, usually translated as the fruit that cries or expels water.","https://en.wikipedia.org/wiki/A%C3%A7a%C3%AD_palm"],"legendary":["A Belém legend tells of Iaçã, whose grief over her lost child brought forth the palm's dark fruit; the drink açaí is said to be her name spelled backwards.","https://portalamazonia.com/amazonia-de-a-a-z/l/lenda-do-acai/"]},"feijoa":{"common":["The genus Feijoa honours the Portuguese naturalist João da Silva Feijó, and the species name sellowiana honours Friedrich Sellow, who first collected it in southern Brazil.","https://en.wikipedia.org/wiki/Feijoa"],"uncommon":["Feijoa's fleshy petals are sweet and edible, and in its native range birds that feast on them are thought to carry its pollen from flower to flower.","https://growables.org/information/TropicalFruit/PineappleGuavaPopenoe.htm"],"rare":["Feijoa's aroma comes mainly from methyl benzoate and related compounds, giving the fruit a scent often likened to a fine perfume.","https://en.wikipedia.org/wiki/Feijoa"],"epic":["In Uruguay feijoa was mostly grown as an ornamental, and trees more than 100 years old still bear fruit on old estancias, in parks and in gardens.","https://www.gub.uy/ministerio-educacion-cultura/comunicacion/noticias/tiempo-guayabos"],"legendary":["Most feijoa breeding abroad began with plants Édouard André took to France; in 2015 Uruguay, where it grows wild, imported seven New Zealand cultivars to test.","https://inia.uy/sites/default/files/publications/2024-10/Revista-INIA-65-Junio-2021-13.pdf"]},"lichen":{"common":["Iceland moss is a lichen: a fungus that builds the body, living with an alga that makes sugar by photosynthesis. It has no roots and takes its water from rain and mist.","https://perlan.is/articles/iceland-moss"],"uncommon":["The European Medicines Agency recognises Iceland moss as a traditional soothing remedy for mouth and throat irritation with dry cough, and for temporary loss of appetite.","https://www.ema.europa.eu/es/medicines/herbal/lichen-islandicus"],"rare":["A law from 1280 banned gathering fjallagrös, Iceland moss, on someone else's land, and those caught faced stiff penalties.","https://grapevine.is/society/article/2015/07/27/a-cure-for-whatever-ails-you/"],"epic":["In 2005 two lichen species rode ESA's Foton-M2 capsule and sat exposed to open space for 14.6 days. All samples survived and could still photosynthesise afterwards.","https://www.universetoday.com/articles/lichen-can-survive-in-space"],"legendary":["Lichen starch can be turned into sugar and distilled. In 1869, 17 Scandinavian lichen distilleries reportedly produced 1,120,100 litres of alcohol.","https://anbg.gov.au/lichen/lichens-people.html"]},"paprika":{"common":["Paprika is a Hungarian diminutive of Serbo-Croatian papar, pepper. The earliest Hungarian dictionary entry, from 1604, called the peppers Török-bors, Turkish pepper.","https://en.wikipedia.org/wiki/Paprika"],"uncommon":["In the 1800s, Szeged women made sweet paprika by cutting the hot membranes out of the pods by hand and washing the seeds before drying and milling.","https://www.pastemagazine.com/food/paprika/hungarys-paprika-women"],"rare":["Szeged paprika pods post-ripen for about two weeks after picking, then are dried from about 80% water to below 10% before milling.","https://www.dfat.gov.au/sites/default/files/114f.pdf"],"epic":["In 1994 some Hungarian paprika was cut with red lead to deepen its colour and add weight. Dozens of people fell ill and several died.","https://lead.org.au/lanv3n3/lanv3n3-6.html"],"legendary":["In 1932 Albert Szent-Györgyi turned to Szeged paprika for vitamin C, and in a week his team extracted over 3 lb (1.3 kg) of pure crystals. He won the 1937 Nobel Prize.","https://profiles.nlm.nih.gov/spotlight/wg/feature/szeged"]},"absinthe":{"common":["Absinthe was nicknamed la fée verte, the Green Fairy, and ordered as une verte for its pale green colour. Its critics called it the Green Demon.","https://www.sciencehistory.org/stories/magazine/the-devil-in-a-little-green-bottle-a-history-of-absinthe/"],"uncommon":["Water turns clear absinthe milky because anethole, the oily anise molecule, dissolves in strong alcohol but not in water, so it falls out as tiny droplets.","https://www.chemistry.bristol.ac.uk/motm/anethole/anetholeh.htm"],"rare":["In August 1905 labourer Jean Lanfray shot his pregnant wife and two daughters in Commugny after drinking absinthe and wine. A petition against absinthe soon gathered 82,000 signatures.","https://en.wikipedia.org/wiki/Jean_Lanfray"],"epic":["During the Swiss ban, between 60 and 80 clandestine distilleries kept making absinthe in the Val-de-Travers, while local authorities reportedly turned a blind eye.","https://www.swissinfo.ch/eng/-green-fairy--comes-out-of-hiding/4384894"],"legendary":["When lightning set the Pernod plant at Pontarlier ablaze in 1901, about a million litres of absinthe ran into the Doubs. Two days later the Loue spring, over 15 km away, smelled of anise.","https://www.showcaves.com/english/fr/karst/Pernod.html"]},"wine":{"common":["Tartaric acid in jar shards from Gadachrili Gora and Shulaveris Gora, about 50 km south of Tbilisi, shows grape wine was made there around 6000 to 5000 BC.","https://www.sci.news/archaeology/worlds-oldest-wine-georgia-05427.html"],"uncommon":["Georgia's qvevri method, fermenting and ageing wine in large egg-shaped clay jars buried in the ground, was added to UNESCO's intangible heritage list in 2013.","https://eurasianet.org/georgias-underground-wine-tradition-gets-unesco-protection"],"rare":["Saperavi, Kakheti's leading red grape, has red flesh as well as red skin, which is rare in grapes. Its name comes from a Georgian word for paint or dye.","https://bubblyprofessor.com/2024/03/22/five-fast-facts-about-saperavi/"],"epic":["In March 2006 Russia banned Georgian wine, citing contamination, although it bought about 80% of Georgian wine sales. The ban was lifted by the end of 2013.","https://en.wikipedia.org/wiki/2006_Russian_ban_of_Moldovan_and_Georgian_wines"],"legendary":["Georgian tradition holds that St Nino, who brought Christianity to Georgia, received a cross of grapevines in a dream and bound it with strands of her own hair.","https://www.oca.org/saints/lives/1003/01/14/100191-saint-nino-nina-equal-of-the-apostles-enlightener-of-georgia"]},"marzipan":{"common":["Under the rules for the protected name, Lübeck Marzipan may contain no more than 30% sugar, and Lübeck Fine Marzipan no more than 10%.","https://en.wikipedia.org/wiki/L%C3%BCbeck_Marzipan"],"uncommon":["Marzipan comes from Italian marzapane, a candy box, from Medieval Latin matapanus, once the name of a coin showing a seated Christ.","https://www.etymonline.com/word/marzipan"],"rare":["The marzipan smell is mainly benzaldehyde, freed when amygdalin in almonds breaks down, with traces of hydrogen cyanide. Bitter almonds hold hundreds of times more amygdalin than sweet ones.","https://mitchell.ucdavis.edu/sites/g/files/dgvnsk916/files/inline-files/Understanding%20the%20Chemistry%20of%20Almond%20Flavor.pdf"],"epic":["Above Café Niederegger in Lübeck, a marzipan museum displays 12 life-size statues made from almond paste, among them the Lübeck-born novelist Thomas Mann.","https://www.atlasobscura.com/places/niederegger-marzipan-museum"],"legendary":["In 1562 Elizabeth I was given marchpane gifts including a model of Old St Paul's Cathedral, a tower with men and artillery, and a chessboard from her Master Cook.","https://nerdalicious.com.au/history/festive-marchpane/"]},"fennel":{"common":["Fennel is one of the aromatics in absinthe, alongside wormwood, hyssop and aniseed. The spirit is typically sold at 68% alcohol and turns cloudy white when water is added.","https://www.britannica.com/topic/absinthe"],"uncommon":["In a study of sweet fennel lines grown in Turkey, trans-anethole made up 92 to 96% of the seed oil, with estragole at about 3%.","https://journals.athmsi.org/index.php/ajtcam/article/view/735"],"rare":["Fennel pollen, shaken by hand from wild fennel flowers in Tuscany and California, ranks among the priciest spices, rivalling saffron. Each flower yields only about a quarter teaspoon.","https://specialtyproduce.com/produce/Fennel_Pollen_Spice_1747.php"],"epic":["In his Natural History, Pliny the Elder wrote that snakes slough their old skin using fennel sap and revive their eyes by rubbing against the plant.","https://bestiary.ca/beasts/beastsource264.htm"],"legendary":["Marathon, the Greek town behind the 490 BCE battle and the run that inspired the race, takes its name from the Greek for fennel, probably because the herb grew there.","https://www.etymonline.com/word/marathon"]},"shiso":{"common":["Traditional umeboshi need only three ingredients: ume, salt and red shiso leaves, which are added during fermentation and give the salty plums their pink colour.","https://www.justonecookbook.com/umeboshi/"],"uncommon":["Perilla grown around Toyohashi, Aichi, is also sold as purple flower spikes. Registered as 'Toyohashi Hanaho', they rank first in Japan by volume at Tokyo's central wholesale market.","https://www.maff.go.jp/e/policies/intel/gi_act/register/250715.html"],"rare":["Perilla contains perilla ketone, which causes atypical interstitial pneumonia in cattle. Flowering plants are the most toxic, and hungry livestock graze them most in autumn.","https://www.aces.edu/blog/topics/farming/perilla-mint-a-toxic-threat-to-livestock/"],"epic":["From the Heian period, oil makers at Oyamazaki near Kyoto pressed perilla seed into lamp oil, and by serving Iwashimizu Hachimangu shrine their guild won exclusive rights to make and sell it.","https://hyakugo.pref.kyoto.lg.jp/eng/?p=276"],"legendary":["Perillartine, a sweetener made from perillaldehyde extracted from perilla, is about 2,000 times as sweet as sucrose and is used mainly in Japan.","https://en.wikipedia.org/wiki/Perillartine"]},"palmarosa":{"common":["Palmarosa is a grass, yet its oil smells floral and rosy: the motia type can contain up to 95% geraniol, with geranyl acetate making up much of the rest.","https://prosea.prota4u.org/view.aspx?id=661"],"uncommon":["In Dharmapuri, Tamil Nadu, about 1.5 tonnes of palmarosa grass go into each kilogram of oil, distilled in some 350 to 400 small units.","https://investmentguruindia.com/newsdetail/palmarosa-industry-in-dharmapuri-tn-hit-hard-by-shrinking-cultivation-weak-market-demand886952"],"rare":["Palmarosa has a near twin, gingergrass. Pull a leaf through your fingers: gingergrass feels rough and sticky, while palmarosa feels smooth and clean.","https://prosea.prota4u.org/view.aspx?id=661"],"epic":["Palmarosa grows wild in six Indian states, and India's oil has long been distilled mostly from wild growths; the country makes about 60 to 70 tonnes a year.","https://dairyknowledge.in/sites/default/files/106_Cymbopogon_martinii.pdf"],"legendary":["Palmarosa oil, the oil most used to adulterate rose oil, was shipped in large copper flasks from Bombay to the Red Sea and on to Constantinople and Kazanlak.","https://www.henriettes-herb.com/eclectic/usdisp/pelargonium.html"]},"citronella":{"common":["Citronella oil was first registered as a pesticide in the US in 1948. It repels rather than kills, masking the scents that draw insects to a meal.","https://npic.orst.edu/factsheets/citronellagen.html"],"uncommon":["Ceylon citronella oil holds about 13% citronellal and 21% geraniol, while the Java type, from a related grass, carries roughly 35% citronellal.","https://dl.nsf.gov.lk/bitstreams/25e892fc-f6ab-4eb4-8306-2f388a242e4a/download"],"rare":["Citronella bug sprays were due to be phased out in Canada by the end of 2014 unless makers supplied new animal toxicity data; Health Canada then reversed course and let them stay.","https://www.peta.org/about-peta/victories/health-canada-re-evaluates-animal-testing-citronella-bug-sprays-following-peta-involvement/"],"epic":["Around 1890 Sri Lanka was the only exporter of citronella oil, with about 50,000 acres in its Southern Province, until Java took the lead after Maha Pangiri grass arrived there in 1899.","https://dl.nsf.gov.lk/bitstreams/25e892fc-f6ab-4eb4-8306-2f388a242e4a/download"],"legendary":["In a 1996 Cornell study of barking dogs, all eight owners said a citronella spray collar cut or stopped barking, while four said electric shock collars had no effect.","https://news.cornell.edu/index%2Ephp/stories/1996/06/citronella-spray-collars-curb-barking-dogs-best"]},"litsea":{"common":["Litsea's lemon scent is mostly citral: in fruit oils from eight Chinese provinces, its two forms, neral and geranial, made up 79 to 87% of the oil.","https://www.mdpi.com/1420-3049/17/6/7057/htm"],"uncommon":["Natural citral from litsea is used mainly in flavours and to fortify lemon oil. The trees grow wild in six provinces of southern China and are harvested in July and August.","https://jp.givaudan.com/node/585466"],"rare":["Taiwan's Atayal people call the dried fruit maqaw and grind it as a spice; a signature dish is fresh catfish wrapped in bamboo leaves with salt and maqaw.","https://www.fondazioneslowfood.com/en/ark-of-taste-slow-food/maqaw-mountain-pepper/"],"epic":["Litsea oil is a commercial source of citral, which chemists turn into ionones for perfumery and which was formerly used to make vitamin A.","https://prosea.prota4u.org/view.aspx?id=665"],"legendary":["The Dayak Kenyah of East Kalimantan use litsea fruit and bark as a tonic, for fever and stomach-ache, and as an antidote for drunkenness.","https://prosea.prota4u.org/view.aspx?id=665"]},"tomatoleaf":{"common":["Botanically a fruit, the tomato became a vegetable in law: in 1893 the US Supreme Court ruled unanimously that it counted as one under a tariff on imported vegetables.","https://en.wikipedia.org/wiki/Nix_v._Hedden"],"uncommon":["A tomato plant's smell comes from tiny hairs called trichomes on its stems and leaves. Their tips hold oils that release scent when crushed, helping to deter pests.","https://www.hortidaily.com/article/9330447/why-do-tomato-plants-smell-like-that/"],"rare":["Perfumers rebuild tomato leaf mainly with 2-isobutylthiazole, a green, faintly sulfurous molecule first identified in 1971; a natural tomato leaf absolute exists but is rare.","https://premierepeau.com/pages/glossary-terms/tomato-leaf"],"epic":["Solanum pimpinellifolium, a wild tomato that hybridizes freely with the garden kind, grows on the coast from northern Peru southward and bears fruits under 1 cm across.","https://solanaceaesource.myspecies.info/taxonomy/term/108944/descriptions"],"legendary":["Seeds of the wild Galápagos tomato will not sprout untreated. UC Davis tomato scientists found a trip through a giant tortoise's gut worked, but it was too cumbersome, so they used bleach.","https://tgrc.ucdavis.edu/sites/g/files/dgvnsk13916/files/inline-files/Rick-and-Borgnino-1977.pdf"]},"mignonette":{"common":["Mignonette is French for little darling, a pet name for a plant that is straggly and plain to look at but sweetly scented.","https://hartley-botanic.co.uk/magazine/mignonette"],"uncommon":["Napoleon is said to have sent mignonette seed to Empress Josephine from his Egyptian campaign in 1798, and her circle made it a fashionable plant for balconies.","https://hartley-botanic.co.uk/magazine/mignonette"],"rare":["Reseda green, colour 6011 in the German RAL standard, is a greyish green named after mignonette leaves. Before World War I the French Army tested and rejected reseda green uniforms.","https://en.wikipedia.org/wiki/Reseda_green"],"epic":["Mignonette was first grown in Britain in 1752, when Philip Miller raised it at Chelsea from seed sent to him from Leiden.","https://hartley-botanic.co.uk/magazine/mignonette"],"legendary":["Pliny described reseda, a healing plant near Rimini: healers laid it on inflammations chanting 'Reseda, allay this disease' three times, spitting on the ground after each.","https://wordhistories.net/2016/10/01/reseda/"]},"cassie":{"common":["A cassie bloom is not one flower: each fluffy golden ball packs 50 to 60 tiny flowers together.","https://prosea.prota4u.org/view.aspx?id=651"],"uncommon":["Seed from Santo Domingo germinated in the Farnese Gardens in Rome in 1611, and the species name farnesiana honours Odoardo Farnese, whose family kept the gardens.","https://en.wikipedia.org/wiki/Vachellia_farnesiana"],"rare":["One kilogram of cassie flowers gives only 1 to 4 g of absolute, and world output of the absolute is in the order of 100 kg a year.","https://prosea.prota4u.org/view.aspx?id=651"],"epic":["Cassie branches are brittle, so pickers in France work from trestles, gathering flowers one to three times a week and only when they are dry.","https://prosea.prota4u.org/view.aspx?id=651"],"legendary":["Farnesol, a C15 alcohol used in perfumery, takes its name from the Farnese acacia, Acacia farnesiana, whose flowers it was obtained from.","https://Dictionary.Com/browse/farnesol"]},"camellia":{"common":["The garden camellia shares its genus with tea: every cup of tea is brewed from the leaves of Camellia sinensis.","https://en.wikipedia.org/wiki/Camellia"],"uncommon":["The living camellia bloom is nearly scentless, at most faintly green and waxy, so no absolute exists and every camellia perfume note is an accord built from aroma molecules.","https://premierepeau.com/pages/glossary-terms/camellia"],"rare":["About three million camellia trees are said to grow wild on Izu Oshima, south of Tokyo, where their seed oil was recorded as a local speciality in the 1830s.","https://web-japan.org/niponica/niponica22/en/feature/feature08-2.html"],"epic":["Camellias bloom in the cold months when few insects fly, so they rely on birds: Japanese white-eyes sip their nectar and carry the pollen from flower to flower.","https://www.birdlife.org/news/2022/02/01/the-special-relationship-between-camellia-flowers-and-white-eyes/"],"legendary":["Camellias drop their flowers whole, which in Japan were likened to a samurai's severed head, and folklore says old camellia trees can become a ghostly spirit, the Furutsubaki-no-rei.","https://en.wikipedia.org/wiki/Camellia_japonica"]},"zdravetz":{"common":["Zdravetz means health in Bulgarian, a fitting name for a plant used in Balkan folk medicine for centuries.","https://premierepeau.com/pages/glossary-terms/geranium-macrorrhizum-zdravetz"],"uncommon":["Geranium comes from the Greek geranos, crane, and macrorrhizum means large root, after the plant's thick aromatic rhizome.","https://giardinocapracotta.unimol.it/en/?p=3221"],"rare":["Steam distilling zdravetz leaves, stems and flowers yields only about 0.1 to 0.3% essential oil.","https://premierepeau.com/pages/glossary-terms/geranium-macrorrhizum-zdravetz"],"epic":["During the Communist era Bulgaria invested heavily in zdravetz oil as an export product, distilling it in state-run distilleries in the Rhodope Mountains.","https://premierepeau.com/pages/glossary-terms/geranium-macrorrhizum-zdravetz"],"legendary":["In the Bulgarian village of Vasiljovo, the priest blesses people after prayer by sprinkling them with a cross-shaped bouquet of wild geranium and basil.","https://bulgariandialectology.berkeley.edu/thematic-content/rituals-plants"]},"pittosporum":{"common":["Pittosporum tobira is called Japanese mock orange because its white flowers smell first of orange blossom, though heavier and more narcotic.","https://premierepeau.com/pages/glossary-terms/pittosporum"],"uncommon":["Pittosporum comes from the Greek pitta, pitch, and sporos, seed, after the sticky resinous coating around its seeds.","https://en.wikipedia.org/wiki/Pittosporum_tobira"],"rare":["Distilling pittosporum flowers yields only about 0.05 to 0.17% oil and no perfume-grade extract is sold, so perfumers rebuild the scent from headspace analysis.","https://premierepeau.com/pages/glossary-terms/pittosporum"],"epic":["The genus name Pittosporum was coined by Joseph Banks and Daniel Solander during Captain Cook's first Pacific voyage of 1769 to 1770.","https://premierepeau.com/pages/glossary-terms/pittosporum"],"legendary":["Its Japanese name tobera is thought to come from tobira no ki, door tree: cut branches smell foul, so at Setsubun they were hung in doorways with sardine heads.","https://en.wikipedia.org/wiki/Pittosporum_tobira"]},"khella":{"common":["Dried khella flower clusters are still sold in Middle Eastern markets, where their woody stems serve as toothpicks.","https://www.avogel-health.ch/en/plant-encyclopaedia/ammi_visnaga.php"],"uncommon":["Egyptian folk healers used khella for kidney and bladder stones, which were common there because of widespread bilharzia.","https://www.avogel-health.ch/en/plant-encyclopaedia/ammi_visnaga.php"],"rare":["Chemists first made amiodarone, an antiarrhythmic heart drug, as a derivative of khellin, the active ingredient extracted from khella.","https://blog.nus.edu.sg/phcdgs/category/topicdrug-classes/antiarrhythmic-drugs"],"epic":["Khella appears among the remedies of the Ebers Papyrus and was known in ancient times as Pharaoh's bread; ancient Egyptians drank its fruit decoction for renal colic.","https://pmc.ncbi.nlm.nih.gov/articles/PMC7024292"],"legendary":["In 1965 Roger Altounyan traced khella's asthma effect to khellin, leading to the drug sodium cromoglycate; he was the model for Roger, the ship's boy in Swallows and Amazons.","https://en.wikipedia.org/wiki/Roger_Altounyan"]},"cucumber":{"common":["A cucumber is almost all water: 100 g of the immature fruit holds about 96 g of it.","https://uses.plantnet-project.org/en/Cucumis_sativus_(PROSEA)"],"uncommon":["Greenhouse European cucumbers set fruit without pollination. If bees get in and pollinate them, the fruit forms seeds, grows misshapen and turns bitter.","https://ask.ifas.ufl.edu/publication/CV268"],"rare":["The molecule credited as the essence of cucumber, (E,Z)-2,6-nonadienal, also turns up in bread crust and freshly cut watermelon.","https://en.wikipedia.org/wiki/Trans,cis-2,6-Nonadienal"],"epic":["In Irian Jaya, western New Guinea, travellers have carried ripe cucumbers on long journeys on foot to relieve their thirst.","https://uses.plantnet-project.org/en/Cucumis_sativus_(PROSEA)"],"legendary":["Researchers found the Latin word cucumis was used only for snake melon; recognisable cucumbers appear in European manuscripts only from around 1300 CE.","https://www.botany.one/the-fashionably-late-arrival-of-cucumbers-in-europe-bad11/"]},"nectarine":{"common":["A nectarine is a peach with no fuzz: the same species, with the smooth skin caused by a recessive allele on one chromosome.","https://fruitgrowersnews.com/article/grower-finds-nectarine-growing-on-peach-tree/"],"uncommon":["Nectarine began in the 1610s as an English adjective meaning like nectar, the Greek gods' drink, and named the smooth peach from the 1660s.","https://www.etymonline.com/word/nectarine"],"rare":["A 1988 analysis of nectarine aroma identified 33 volatile compounds, with lactones as the main class, peaking in gamma- and delta-decalactone.","https://portal.fis.tum.de/en/publications/investigation-of-volatile-constituents-in-nectarines-1-analytical/"],"epic":["Radiocarbon dates on ancient pits show the peach, parent of the nectarine, split from its wild ancestors at least 7,500 years ago in China's lower Yangtze Valley.","https://www.iol.co.za/news/ancient-pits-reveal-origin-of-peach-1747903"],"legendary":["Charles Darwin recorded peach branches that suddenly bore nectarines by bud variation, and fruits that were partly nectarine and partly peach.","https://hackernoon.com/on-bud-variation-and-on-certain-anomalous-modes-of-reproduction-and-variation"]},"cranberry":{"common":["Most cranberries are harvested by flooding the bogs and marshes, which makes the berries float so they can be scooped up from the surface.","https://www.uscranberries.com/about-cranberries/"],"uncommon":["European settlers called them crane-berries because the flowers reminded them of a crane's head, neck and bill.","https://www.rhs.org.uk/advice/grow-your-own/features/fascinating-facts-cranberries"],"rare":["In 1667 New Englanders sent a gift to appease King Charles II that included ten barrels of cranberries.","https://www.rhs.org.uk/advice/grow-your-own/features/fascinating-facts-cranberries"],"epic":["After a herbicide warning on 9 November 1959, fresh cranberry sales fell 73% and President Eisenhower's Thanksgiving dinner served applesauce instead.","https://en.wikipedia.org/wiki/Cranberry_scare_of_1959"],"legendary":["In the 1840s one-legged New Jersey grower John Webb, unable to carry barrels from his attic, poured berries down the stairs; the best ones bounced to the bottom.","https://jerseybites.com/cranberries-the-pine-barrens-and-john-peg-leg-webb/"]},"tamarind":{"common":["Tamarind pulp is an ingredient in some brands of Worcestershire sauce and barbecue sauce.","https://growables.com/information/TropicalFruit/TamarindMorton.htm"],"uncommon":["Persians and Arabs called the pulp tamar hindi, Indian date, and the species name indica wrongly suggests an Indian origin: the tree is native to tropical Africa.","https://growables.com/information/TropicalFruit/TamarindMorton.htm"],"rare":["Mixed with sea water, tamarind pulp cleans silver, copper and brass.","https://growables.com/information/TropicalFruit/TamarindMorton.htm"],"epic":["To some Burmese the tamarind is the dwelling place of the rain god, and an old belief holds it is harmful to sleep or tie a horse beneath one.","https://growables.com/information/TropicalFruit/TamarindMorton.htm"],"legendary":["A popular legend says chewing leaves of the tamarind tree beside the tomb of the musician Tansen in Gwalior, India, improves your singing voice.","https://www.sahapediaexperiences.org/index.php/blog/dastaan-e-maqbara-mausoleums-poets-and-musicians"]},"cactus":{"common":["Mexico's national emblem shows an eagle with a snake standing on a nopal cactus, the sign that led the Aztecs to found Tenochtitlan in about 1325.","https://embamex.sre.gob.mx/reinounido/images/stories/PDF/Meet_Mexico/2_meetmexico-symbolsofmexico.pdf"],"uncommon":["In Mexico the prickly pear fruit is called tuna, and in markets it is sold peeled and de-spined; the fruits are berries about the size of kiwi fruits.","https://clacs.ku.edu/prickly-pear"],"rare":["Prickly pear is the most cold-tolerant of all lowland cacti, and has spread almost worldwide wherever the climate allows.","https://clacs.ku.edu/prickly-pear"],"epic":["Red dye from cochineal insects living on prickly pear became Spain's second most valuable export after silver; one pound takes about 70,000 insects.","https://blogs.ifas.ufl.edu/lakeco/?p=4009"],"legendary":["In 1936 Boonarga, Queensland, opened a hall named in honour of the cactoblastis moth, which helped clear prickly pear that had covered an estimated 23 million ha by 1920.","https://en.wikipedia.org/wiki/Cactoblastis_Memorial_Hall"]},"marshmallow":{"common":["Early marshmallows used a gooey substance from the roots of the marsh mallow plant mixed with sugar and egg whites; today they are made of sugars, corn syrup and gelatin.","https://garden.rcp.ac.uk/viewPlant?plantId=80"],"uncommon":["Ancient Egyptians were the first to make a sweet from the plant, mixing marshmallow sap with nuts and honey, a dish reserved for the nobility.","https://www.mentalfloss.com/food/candy/long-sweet-history-marshmallows"],"rare":["The Greek physician Dioscorides recommended marsh mallow for bee and wasp stings; the name Althaea comes from the Greek word for healing.","https://garden.rcp.ac.uk/viewPlant?plantId=80"],"epic":["Alex Doumak patented the extrusion process for marshmallows in 1954, allowing cheap mass production and turning an expensive confection into an everyday sweet.","https://en.wikipedia.org/wiki/Doumak"],"legendary":["The Girl Scout credited with s'mores, Loretta Scott Crew, seems to be fictional; a 1925 Somemore recipe by Cookie Moore used 16 marshmallows and 4 Hershey bars.","https://www.nationalgeographic.com/history/article/who-invented-smores-real-history"]},"wheat":{"common":["Wheat is grown on about 215 million hectares every year, more land than any other staple food crop, and is eaten by some 2.5 billion people.","https://archive.wheat.org/wheat-in-the-world/"],"uncommon":["Norman Borlaug bred short, sturdy dwarf wheat in Mexico from 1944, then lifted harvests in India and Pakistan in the 1960s. He won the 1970 Nobel Peace Prize.","https://www.nobelprize.org/prizes/peace/1970/borlaug/speedread/"],"rare":["Bread wheat carries six copies of each of its seven chromosomes, 42 in all, from an ancient cross with goat grass. Its 17 billion base pairs are about five times the human genome.","https://www.cshl.edu/bread-wheats-large-and-complex-genome-is-revealed"],"epic":["In 1997 a DNA study of 1,362 wild einkorn lines traced cultivated einkorn to Karacadağ in Turkey, a mountain about 30 km from Göbekli Tepe. Farmed grain there dates back 10,200 to 10,500 years.","https://sciencenorway.no/agriculture--fisheries-archaeology-forskningno/on-the-track-of-the-worlds-first-farmer/1448265"],"legendary":["In 1897 Kew's director William Thiselton-Dyer sowed 3,000-year-old wheat from an Egyptian tomb to test tales of sprouting mummy grain. After three months the grains had crumbled to powder.","https://www.historytoday.com/archive/myth-mummy-wheat"]},"fenugreek":{"common":["In Indian cooking fenugreek is called methi: the fresh leaves go into dishes like aloo methi, and the bitter seeds are often roasted first to soften their bite.","https://en.wikipedia.org/wiki/Fenugreek"],"uncommon":["Fenugreek was fenograecum in Old English, from Latin faenugraecum, literally Greek hay: faenum (hay) plus Graecum (Greek).","https://www.etymonline.com/word/fenugreek"],"rare":["Fenugreek seeds contain diosgenin, a compound used as a starting material for making oral contraceptives.","https://en.wikipedia.org/wiki/Fenugreek_production_in_India"],"epic":["Charred fenugreek seeds from Tell Halal in Iraq are carbon dated to about 4000 BC, and dried seeds were found in the tomb of Tutankhamun.","https://en.wikipedia.org/wiki/Fenugreek"],"legendary":["From 2005 a maple syrup smell kept drifting over New York City. In 2009 the city traced it to a New Jersey flavour plant processing fenugreek seeds, rich in maple-scented sotolone.","https://www.scientificamerican.com/blog/news-blog/mystery-of-nyc-maple-syrup-smell-so-2009-02-05/"]},"galangal":{"common":["Fresh galangal is the galangal of choice in Thai food: thin slices flavour tom khaa, the coconut-milk cousin of tom yam, and the ground rhizome goes into most curry pastes.","https://gernot-katzers-spice-pages.com/engl/Alpi_gal.html"],"uncommon":["Poland's Żołądkowa Gorzka, a bitter vodka whose name means roughly bitter vodka for the stomach, is flavoured with galangal.","https://blog.herbsociety.org/galanga-herb-of-the-month-an-interesting-but-less-familiar-herb/"],"rare":["The rhizome holds up to 1.5% essential oil. Fresh galangal smells close to fir or pine needles, while dried galangal turns more like cinnamon.","https://gernot-katzers-spice-pages.com/engl/Alpi_gal.html"],"epic":["Galangal was traded along eastern merchant routes from the early Middle Ages, and in the 13th century Marco Polo reported it being produced in southern China and Java.","https://www.kloranebotanical.foundation/en/botany/plant-guides/all-about-galangal"],"legendary":["The Arabs who brought galangal to Europe in the 9th century reportedly also used it to fire up their horses.","https://blog.herbsociety.org/galanga-herb-of-the-month-an-interesting-but-less-familiar-herb/"]},"kanuka":{"common":["Captain Cook and early settlers called kānuka and its lookalike mānuka tea tree, and brewed the green leaves as a substitute for tea.","https://ourwayoflife.co.nz/why-kanuka-is-finally-getting-the-spotlight/"],"uncommon":["Kānuka acts as a nurse plant, sheltering young kauri and podocarps. Because it needs full light, the trees it shelters eventually overtop and replace it.","https://www.tanestrees.org.nz/species-profiles/kanuka/"],"rare":["Kānuka has been called New Zealand's premier fuel wood. One settler's diary records about 40 tons a month shipped from Kawau Island to Auckland.","https://www.tanestrees.org.nz/species-profiles/kanuka/"],"epic":["Kānuka's strong, hard timber was used by Māori for weapons including the taiaha, the tewhatewha and the koikoi, a double-pointed spear.","https://ourwayoflife.co.nz/why-kanuka-is-finally-getting-the-spotlight/"],"legendary":["From 1983 New Zealand kānuka was lumped with Australian burgan. A 2014 revision split it into 10 endemic species, one, Kunzea tenuicaulis, known only from active geothermal fields.","https://blog.pensoft.net/2014/08/28/and-then-there-were-10-unexpected-diversity-in-new-zealand-kanuka-genus-kunzea/"]},"spruce":{"common":["Violin makers from Cremona travelled to the Paneveggio forest in Trentino for its resonant Norway spruce, and legend says Stradivari himself searched it for trees.","https://www.visittrentino.info/en/guide/nature/beautiful-places/the-violins-forest_md_2248"],"uncommon":["Black spruce cones can stay on the tree for many years. The heat of a forest fire opens them and releases the seed, letting the species reseed burned land.","https://www.gov.nl.ca/fal/public-education/forestry/our-forest/treespecies/bspruce/"],"rare":["In 1848 John Bacon Curtis of Maine made State of Maine Pure Spruce Gum from spruce resin, the first successful commercial chewing gum in the US. His factory later made 1,800 boxes a day.","https://www.maine.gov/sos/maineatlas/explore-the-atlas/spruce-gum"],"epic":["Spruce comes from Pruce, Middle English for Prussia. Spruce meant goods Hanseatic merchants shipped from the Baltic, like beer, boards and chests, and the tree took the name by the 1660s.","https://www.etymonline.com/word/spruce"],"legendary":["Old Tjikko, a spruce on Fulufjället in Sweden, is a clone about 9,565 years old. Its trunk is a few hundred years old, but it keeps re-rooting from its branches and survived cold spells as a bush under snow.","https://sverigesnationalparker.se/en/choose-park---list/fulufjallet-national-park/experience/the-worlds-oldest-trees"]},"laurel":{"common":["In Greek myth the nymph Daphne fled Apollo and was turned into a laurel tree, which he made evergreen and wore as a wreath. In Rome, laurel crowned victorious commanders in triumph.","https://en.wikipedia.org/wiki/Laurel_wreath"],"uncommon":["A Turkish producer says Türkiye supplies about 90% of the world's bay leaves. Unlike seasonal crops, the leaves can be harvested in all 12 months of the year.","https://hurriyetdailynews.com/turkiye-caters-to-90-pct-of-worlds-bay-leaf-needs-189016"],"rare":["Laureate comes from Latin laureatus, crowned with laurel. It honoured poets from the late 14th century, and Nobel Prize winners have been called laureates since 1947.","https://www.etymonline.com/word/laureate"],"epic":["In Turkey's Hatay province, laurel berries are crushed and boiled in water, and the oil that floats to the top is skimmed off. It froths well and goes into locally made soaps.","https://www.fao.org/4/y1797e/y1797e19.htm"],"legendary":["Suetonius wrote that Emperor Tiberius was immoderately afraid of thunder and wore a laurel wreath whenever the sky looked stormy, because laurel was said never to be struck by lightning.","https://lexundria.com/suet_tib/69/r"]},"camphor":{"common":["Camphor is burned in aarti, usually at the end of a Hindu puja, and it is also used in place of mothballs to keep insects away.","https://en.wikipedia.org/wiki/Camphor"],"uncommon":["From 1910 to 1916, Taiwan produced roughly 56% of the world's camphor every year, much of it for military use.","https://taiwantoday.tw/AMP/Culture/Top-News/24403/Old-camphor-kingdom-comes-alive"],"rare":["From the mid-19th century camphor was used to make celluloid, which George Eastman turned into photographic film by 1889. Flammable celluloid film was replaced by triacetate from 1951.","https://taiwantoday.tw/AMP/Culture/Top-News/24403/Old-camphor-kingdom-comes-alive"],"epic":["The camphor tree at Kamo Hachiman Shrine in Kagoshima, Japan, is about 1,500 years old, around 30 m tall and 24.2 m around the trunk, believed to be the largest camphor tree in Japan.","https://www.visit-kyushu.com/en/spots/kamo-no-okusu-camphor-tree/"],"legendary":["A Tang dynasty recipe for ice cream included camphor, which the Chinese called dragon's brain perfume. In ancient Egypt camphor was also used to flavour bread.","https://en.wikipedia.org/wiki/Camphor"]},"cassia":{"common":["Cassia is the most popular cinnamon sold in North America. Its sticks are very hard and made of one thick layer, while true Ceylon cinnamon rolls into many thin layers.","https://en.wikipedia.org/wiki/Cinnamomum_cassia"],"uncommon":["Văn Yên in Vietnam's Yên Bái province grows cassia on up to 16,000 hectares and yields about 6,000 tonnes of dried bark and 300 tonnes of essential oil a year.","https://vietnamnews.vn/life-style/1249803/van-yen-finds-fortune-in-cinnamon.html"],"rare":["Cassia holds more coumarin than low-coumarin Ceylon cinnamon. Germany's risk agency BfR says about 2 g of cassia a day already reaches the tolerable coumarin intake for a 60 kg adult.","https://www.bfr.bund.de/en/press-release/cassia-cinnamon-with-high-coumarin-contents-to-be-consumed-in-moderation/"],"epic":["In Exodus the holy anointing oil blends 500 shekels of cassia and 500 of liquid myrrh with 250 each of cinnamon and aromatic cane in a hin, about 3.5 litres, of olive oil.","https://biblia.com/bible/esv/exodus/30/23-25"],"legendary":["Herodotus wrote that Arabians gathered cassia from a shallow lake guarded by winged creatures like bats, covering themselves in ox-hides so the beasts could not attack their eyes.","https://www.livius.org/sources/content/herodotus/the-edges-of-the-earth/"]},"driftwood":{"common":["While it floats, driftwood gives shelter and food to birds and fish. Shipworms, gribbles and bacteria break it down, and logs washed ashore can become the base of sand dunes.","https://en.wikipedia.org/wiki/Driftwood"],"uncommon":["North of the tree line, Arctic driftwood was the main wood for many Inuit. Kayak frames were built from it, and they sorted driftwood into seven types.","https://en.wikipedia.org/wiki/Driftwood"],"rare":["A 30-foot mountain hemlock log has floated upright in Oregon's Crater Lake since at least 1896. Between July and October 1938 it drifted 62.1 miles.","https://nps.gov/crla/learn/nature/theoldman.htm"],"epic":["Tree rings of driftwood pines found in Greenland, Iceland, Svalbard and the Faroes traced 91% of the dated pines to Siberia's Yenisei and Angara rivers, much of it from logging and timber rafting.","https://www.climatology.uni-mainz.de/files/2012/03/Hellmann_2015_AAAR.pdf"],"legendary":["Lars Vilks built a large driftwood sculpture, Nimis, illegally in Sweden's Kullaberg reserve. Amid the legal fight he declared the area the Republic of Ladonia in 1996; it has over 20,000 citizens.","https://www.thelocal.com/20191202/adventcalendar-the-micronation-in-a-southern-swedish-natio/"]},"mitti":{"common":["The smell of rain on dry ground is called petrichor, a word coined in 1964 by CSIRO scientists Isabel Joy Bear and Richard Thomas from Greek petra, stone, and ichor, the blood of the gods.","https://www.csiro.au/en/news/all/articles/2015/march/the-smell-of-rain-how-our-scientists-invented-a-new-word"],"uncommon":["Kannauj distillers once used mud from the banks of the Ganges. Today they fill their copper degs with fragments of broken clay pots and the clay cups called kulhads.","https://www.outlooktraveller.com/experiences/heritage/petrichor-in-a-bottle"],"rare":["In about 600 high-speed camera experiments, MIT researchers saw raindrops trap air bubbles on porous soil that burst out as aerosols, most in light and moderate rain, possibly how petrichor reaches the air.","https://news.mit.edu/2015/rainfall-can-release-aerosols-0114"],"epic":["When CSIRO named petrichor in 1964, the source of the smell was still unknown to science, yet Indian perfumers had long captured it in sandalwood oil as matti ka attar, earth perfume.","https://www.csiro.au/en/news/all/articles/2015/march/the-smell-of-rain-how-our-scientists-invented-a-new-word"],"legendary":["Geosmin, the earthy smell, is made by Streptomyces soil bacteria only when they form spores. It lures springtails, which eat the bacteria and spread the spores on their bodies and in their droppings.","https://www.lunduniversity.lu.se/article/story-behind-earthy-smell-spring"]},"samphire":{"common":["Sea fennel was once eaten raw or kept in vinegar aboard sailing ships to protect sailors from scurvy, and crews gave it the name sea fennel.","https://patrimoine-iroise.fr/naturel/flore/criste.php?lang=en"],"uncommon":["Rock samphire was picked on Dover's cliffs in May, pickled in brine and sent to London to eat with meat. The samphire sold today is usually marsh samphire, an unrelated salt-marsh plant.","https://www.samphirehoe.com/about-samphire-hoe/name/"],"rare":["Though sea fennel is abundant on the Breton coast, a 2010 Finistère decree limits wild picking to what one hand can hold, and selling it needs a permit from the prefecture.","https://patrimoine-iroise.fr/naturel/flore/criste.php?lang=en"],"epic":["King Lear describes a man halfway down Dover's cliff who gathers samphire, dreadful trade. In 1994 land built from Channel Tunnel works beside Shakespeare Cliff was named Samphire Hoe.","https://www.samphirehoe.com/about-samphire-hoe/name/"],"legendary":["On 18 June 1576 John Pantridge fell about 170 feet from the cliffs at Freshwater on the Isle of Wight while gathering rock samphire, and broke his neck.","https://goldhillmuseum.org.uk/tudor-accident-of-the-month-gathering-rock-samphire/"]},"grass":{"common":["The smell of cut grass is a distress signal: damaged leaves release green leaf volatiles, which in some cases can be detected more than a mile away.","https://www.livescience.com/65400-why-freshly-cut-grass-smells-good.html"],"uncommon":["Kentucky bluegrass, Poa pratensis, is probably of Eurasian origin; it seems to have reached central Kentucky before the first European settlers did.","https://kyatlas.com/phys-bluegrass.html"],"rare":["Lawns cover about 40 million acres (16.3 million ha) of the contiguous United States, so every mowing releases a huge cloud of green leaf volatiles.","https://www.livescience.com/65400-why-freshly-cut-grass-smells-good.html"],"epic":["Edwin Budding of Stroud patented the lawn mower in 1830, adapting the rotary blades used to finish woollen cloth; his machine began replacing the scythe.","https://collection.sciencemuseumgroup.org.uk/objects/co38796/buddings-patent-lawn-mower-1832-lawn-mower"],"legendary":["Hornworm saliva flips a leaf's green odour from (Z)-3-hexenal to (E)-2-hexenal, which lures egg-eating Geocoris bugs; in field tests egg losses rose from 8% to 24%.","https://www.mpg.de/619030/pressRelease20100816"]},"ivy":{"common":["Ivy does not feed on the trees it climbs: it has its own roots in the soil and climbs only to reach more sunlight.","https://woodlandtrust.org.uk/trees-woods-and-wildlife/plants/wild-flowers/ivy/"],"uncommon":["Ivy symbolised fidelity, so priests gave ivy wreaths to newlyweds, and bridal bouquets still often include a sprig.","https://woodlandtrust.org.uk/trees-woods-and-wildlife/plants/wild-flowers/ivy/"],"rare":["The ivy bee, which gathers pollen mainly from ivy and flies until November, was first recorded in the UK in Dorset in 2001 and has spread across southern England and Wales.","https://www.buglife.org.uk/bugs/bug-directory/ivy-bee/"],"epic":["The bush in the proverb good wine needs no bush was a bunch of ivy hung outside taverns as a vintner's sign; the phrase is first recorded in Shakespeare's As You Like It in 1623.","https://wordhistories.net/2017/12/02/good-wine-needs-no-bush/"],"legendary":["Ivy rootlets secrete a glue of uniform nanoparticles about 70 nm wide, University of Tennessee researchers found in 2008; Darwin had noted the yellowish secretion in 1876.","https://www.nanowerk.com/spotlight/spotid=5119.php"]},"gooseberry":{"common":["The gooseberry grows on a prickly shrub whose spiny branches made it useful as a protective hedge; its green or reddish berries go into jams, jellies and desserts.","https://giardinocapracotta.unimol.it/en/collezione-botanica/ribes-uva-crispa-l/"],"uncommon":["To play gooseberry, to be the unwanted third person with a couple, began as a term for a 19th-century chaperone and is in print by 1837.","https://www.phrases.org.uk/meanings/play-gooseberry.html"],"rare":["Old gooseberry was a medieval name for the Devil, and to play old gooseberry, recorded in 1796, meant to break up a riot by force.","https://www.phrases.org.uk/meanings/play-gooseberry.html"],"epic":["Gooseberries and currants host white pine blister rust, which kills white pines, so the US banned growing them in 1911; the federal ban was lifted in 1966.","https://bangordailynews.com/2021/08/16/homestead/growing-currants-and-gooseberries-is-illegal-in-maine-and-theres-a-good-reason-for-it/"],"legendary":["The heaviest gooseberry on record, a yellow Millennium berry grown by Graeme Watson, weighed 65.3 g at the 2025 Egton Bridge show, beating his own 2019 record.","https://egtongooseberryshow.org.uk/"]},"cubeb":{"common":["Cubeb is called tailed pepper because its dried berries keep their stalks; it is grown mostly on Java and Sumatra, hence another name, Java pepper.","https://earthpedia.earth.com/plant-encyclopedia/angiosperms/piperaceae/piper-cubeba"],"uncommon":["Cubeb berries from Java are one of the ten botanicals vapour-infused into Bombay Sapphire gin, alongside West African grains of paradise.","https://bombaysapphire.com/us/en/products/bombay-sapphire/"],"rare":["The Smithsonian holds a pack of Marshall's medicated cigarettes, made in New York after 1941, whose active ingredient was cubebs, sold for throat irritation and congestion from colds.","https://si.edu/object/marshalls-med-cigarettes:nmah_737859"],"epic":["Around 1640 a king of Portugal reportedly banned the sale of cubeb to promote black pepper, and its use in European cooking fell sharply afterwards.","https://en.wikipedia.org/wiki/Piper_cubeba"],"legendary":["Europeans came to see cubeb as repulsive to demons: in the late 17th century Ludovico Sinistrari put it in an incense meant to drive away an incubus.","https://en.wikipedia.org/wiki/Piper_cubeba"]},"bluetansy":{"common":["Blue tansy has yellow flower heads, yet its oil is deep midnight blue, coloured by chamazulene, a molecule that forms from matricin during distillation.","https://www.givaudan.com/print/2738351"],"uncommon":["Wild blue tansy populations around the Mediterranean declined from overharvesting, so the plant was reintroduced and is now cultivated in Morocco.","https://www.givaudan.com/print/2738351"],"rare":["A 2023 study found antifungal activity in blue tansy oil from northern Morocco against Fusarium oxysporum f. sp. albedinis, the fungus behind Bayoud disease of date palms.","https://doaj.org/article/32b7aaa2fd4f4677a717d7aa91e0083f"],"epic":["Because dried tansy flowers keep their shape, the plant was likely used to preserve corpses, a form of embalming, in the Middle Ages.","https://mecklenburghsquaregarden.org.uk/tansy/"],"legendary":["The genus name Tanacetum comes from the Greek athanasia, immortality; in myth Zeus had tansy added to Ganymede's drink to make him immortal as cupbearer to the gods.","https://mecklenburghsquaregarden.org.uk/tansy/"]},"marjoram":{"common":["Marjoram is closely related to oregano but milder, tasting a bit like thyme and oregano combined; confusingly, wild marjoram is another name for oregano.","https://www.cooksinfo.com/marjoram"],"uncommon":["Marjoram is used a lot commercially in making sausages, which is why its German name is Wurstkraut, from Wurst, sausage.","https://www.cooksinfo.com/marjoram"],"rare":["Egypt is the world's fifth-largest marjoram exporter; in 2012 it exported about 2,370 tonnes, around 13.6% of that year's marjoram production.","https://ejar.journals.ekb.eg/article_153556.html"],"epic":["In King Lear, Act 4, Scene 6, the mad king demands the password and Edgar answers Sweet marjoram, to which Lear replies Pass.","https://shakespeare.folger.edu/shakespeares-works/king-lear/act-4-scene-6/"],"legendary":["In Greek myth Amaracus, royal perfumer to King Cinyras of Cyprus, fell while carrying ointments and was turned into marjoram; his sister Myrrha also became an aromatic plant.","https://en.wikipedia.org/wiki/Amaracus"]},"hyssop":{"common":["Hyssop is part of the official recipe of Chartreuse liqueur and a key ingredient in many absinthe formulations.","https://en.wikipedia.org/wiki/Hyssopus_officinalis"],"uncommon":["The hyssop of the Bible, used to sprinkle blood at Passover, may not be this plant at all: researchers suggest other herbs, such as Syrian oregano.","https://en.wikipedia.org/wiki/Hyssopus_officinalis"],"rare":["Two ketones in hyssop oil, pinocamphone and isopinocamphone, make it neurotoxic: it caused convulsions in rats at 0.13 g/kg, and seizures are reported in people.","https://www.drugs.com/npp/hyssop.html"],"epic":["Besides religious rituals, hyssop was used in ancient times as an insecticide, an insect repellent and a treatment against lice.","https://www.drugs.com/npp/hyssop.html"],"legendary":["The 1st-century scribe Chairemon wrote that Egyptian priests ate their bread with finely chopped hyssop, claiming it removed most of the bread's force.","https://www.philipharland.com/Blog/2024/05/egyptian-perspectives-chairemon-on-egyptian-priests-first-century-ce/"]},"melissa":{"common":["Melissa is Greek for honey bee, after the plant's bee-attracting flowers; bees were once thought never to leave a garden where it grew.","https://en.wikipedia.org/wiki/Lemon_balm"],"uncommon":["The Tudors scattered lemon balm leaves across their floors, and from the 18th century balm water, Aqua Melissa, was drunk as a healthy beverage.","https://en.wikipedia.org/wiki/Lemon_balm"],"rare":["Distilling fresh lemon balm gives only about 0.014% oil, so the true oil is extremely expensive and its scent is often suggested with cheap lemon, lemongrass and citronella oils.","https://www.fao.org/4/x5043e/x5043E0I.HTM"],"epic":["Carmelite water, an alcoholic extract of lemon balm and other herbs, was first made in the 14th century by Carmelite nuns of the Abbey of St Just and sold as Eau de Carmes.","https://en.wikipedia.org/wiki/Carmelite_Water"],"legendary":["French producers reported that world output of melissa oil in 1988 was no more than 50 pounds, yet sales of over 1,000 pounds were recorded.","https://www.edenbotanicals.com/melissa-lemon-balm-organic.html"]},"wintergreen":{"common":["American wintergreen keeps its red berries through winter, and in some areas the plant is an important winter food for white-tailed deer.","https://en.wikipedia.org/wiki/Gaultheria_procumbens"],"uncommon":["Wintergreen oil from Nepal is more than 99.5% methyl salicylate, so a single molecule makes up nearly the whole scent.","https://www.mdpi.com/2223-7747/11/8/1090"],"rare":["American wintergreen leaves have to be fermented for at least three days before they give a significant amount of essential oil.","https://en.wikipedia.org/wiki/Gaultheria_procumbens"],"epic":["One teaspoon (5 mL) of pure oil of wintergreen equals about 7,000 mg of aspirin, or 22 adult tablets, an amount that can be fatal to young children.","https://www.msdmanuals.com/home/injuries-and-poisoning/poisoning/aspirin-poisoning"],"legendary":["Crunching a wintergreen Life Saver makes a tiny flash of mostly ultraviolet light; the wintergreen flavouring absorbs it and glows visible blue.","https://www.thetakeout.com/2087268/why-wintergreen-lifesavers-spark-according-to-science"]},"cabreuva":{"common":["Drill into a cabreúva trunk and it exudes an aromatic balm, an oily liquid once burned as incense and used to scent clothes and repel insects.","https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/1139716/1/Especies-Arboreas-Brasileiras-vol-1-Cabriuva.pdf"],"uncommon":["Steam-distilled cabreúva heartwood gives about 3 to 5% oil, 40 to 60% of it nerolidol, a woody-floral molecule perfumers use in flower reconstructions.","https://premierepeau.com/pages/glossary-terms/cabreuva"],"rare":["Of 100 Brazilian tree species profiled by Embrapa, young cabreúva is among the three slowest-growing, and some people believe it flowers only every 7 years.","https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/1139716/1/Especies-Arboreas-Brasileiras-vol-1-Cabriuva.pdf"],"epic":["The town of Cabreúva in São Paulo state takes its name from the cabreúva, a large one of which stood where early settlers built a chapel.","https://biblioteca.ibge.gov.br/visualizacao/dtb/saopaulo/cabreuva.pdf"],"legendary":["Cabreúva comes from the Tupi caburé-yba, which means owl tree.","https://biblioteca.ibge.gov.br/visualizacao/dtb/saopaulo/cabreuva.pdf"]},"sweetgrass":{"common":["Polish Żubrówka vodka is poured through bundles of dry bison grass from the Białowieża Forest, and each bottle carries a single blade of the grass.","https://atlasobscura.com/foods/bison-grass-vodka-zubrowka"],"uncommon":["Dried, braided sweetgrass is burned as incense or smudge; its fragrant smoke is used for purification and to carry prayers, and Cheyenne, Blackfeet and Lakota used it in the Sun Dance.","https://plants.sc.egov.usda.gov/DocumentLibrary/plantguide/pdf/pg_hiod.pdf"],"rare":["The Cheyenne mixed sweetgrass with pineapple weed as a perfume, and the Blackfeet kept braids with their clothes as a sachet and used it as a hair rinse.","https://plants.sc.egov.usda.gov/DocumentLibrary/plantguide/pdf/pg_hiod.pdf"],"epic":["Because bison grass contains coumarin, the US FDA banned it; Żubrówka returned to the US in late 2010, after more than 30 years, with a coumarin-free recipe.","https://atlasobscura.com/foods/bison-grass-vodka-zubrowka"],"legendary":["Some Native American peoples used sweetgrass against insects; in 2015 USDA chemists found coumarin and phytol in its oil, and in one test the distilled oil matched DEET.","https://www.smithsonianmag.com/science-nature/this-sweet-smelling-herb-can-ward-away-mosquitoes-180956291/"]},"lovage":{"common":["Germans call lovage Maggikraut, Maggi herb, after Maggi seasoning sauce, a condiment very popular in the 1960s and 1970s whose flavour it recalls.","https://gernot-katzers-spice-pages.com/engl/Levi_off.html"],"uncommon":["The love in lovage is folk etymology: most European names come from the Latin ligusticum apium, Ligurian celery, because it grew plentifully in Liguria.","https://gernot-katzers-spice-pages.com/engl/Levi_off.html"],"rare":["Chapter 70 of the Capitulare de villis, Charlemagne's rules for royal estates from around 800 AD, recommends growing lovage.","https://en.wikipedia.org/wiki/Lovage"],"epic":["Lovage was a common Roman flavouring and appears in over 100 recipes in the Apicius cookbook of about the 4th century CE.","https://premierepeau.com/pages/glossary-terms/lovage-root-oil"],"legendary":["In Cornwall, lovage cordial added to brandy became a winter drink; it was first used to mask the salty taste of slightly spoiled smuggled brandy.","https://en.wikipedia.org/wiki/Lovage"]},"blacklime":{"common":["Black limes are fresh limes blanched in salt water and dried until hard, traditionally in the sun. Finished, they feel light and hollow and keep for up to two years.","https://www.finedininglovers.com/article/what-is-black-dried-lime"],"uncommon":["Called limu Omani because they were first made in Oman, black limes are a staple in Iran, Iraq and the Gulf, and flavour Bahrain's signature rice dish, chicken machboos.","https://www.finedininglovers.com/article/what-is-black-dried-lime"],"rare":["By the early 1970s limes were Oman's most valuable export after oil: in 1971 they earned 333,300 rials, against 118,000 for dates.","https://www.apsnet.org/publications/plantdisease/backissues/Documents/1991Articles/PlantDisease75n06_546.pdf"],"epic":["Witches' broom disease, caused by mycoplasma-like microbes living in the sap tubes, spread through Oman's lime groves; by 1987 thousands of trees had been killed.","https://gd.eppo.int/reporting/article-5725"],"legendary":["Omanis credit Sinbad the Sailor, said to hail from the Batinah coast, with carrying sun-dried limes on his boat, which may have helped his voyages succeed.","https://www.apsnet.org/publications/plantdisease/backissues/Documents/1991Articles/PlantDisease75n06_546.pdf"]},"cajeput":{"common":["Cajeput takes its name from the Malay kayu putih, meaning white wood, after the tree's white, papery, flaky bark.","https://www.nparks.gov.sg/florafaunaweb/flora/3/0/3019"],"uncommon":["On Buru, family teams strip cajeput leaves from young regrowth by machete into 20 kg baskets; a skilled cutter can fill seven baskets a day.","https://prosea.prota4u.org/view.aspx?id=666"],"rare":["Cajeput is the only one of about 250 Melaleuca species that grows naturally west of Wallace's Line, the boundary between Asian and Australian wildlife.","https://prosea.prota4u.org/view.aspx?id=666"],"epic":["The species was first formally described in 1809 in the Pharmacopoeia of the Royal College of Physicians of London, citing Rumphius's 1747 Herbarium Amboinense.","https://en.wikipedia.org/wiki/Melaleuca_cajuputi"],"legendary":["In 1831, as cholera reached Britain, J.M.W. Turner pencilled a remedy on a sketch: 25 drops of cajeput oil in a glass of water, and 50 more if not relieved in 5 minutes.","https://www.tate.org.uk/art/research/content/1134082?project=1"]},"ravintsara":{"common":["Ravintsara roughly means good leaf in Malagasy. The tree is the camphor laurel, which was probably brought to Madagascar in the 19th century.","https://christiankull.net/2025/10/15/volatility-madagascar-chanelle-adams/"],"uncommon":["Ravintsara comes from the camphor tree, but Madagascar's trees are a 1,8-cineole chemotype: low in camphor and high in cineole.","https://christiankull.net/2025/10/15/volatility-madagascar-chanelle-adams/"],"rare":["For years, aromatherapy books wrote about ravensara oil when they were really describing ravintsara, which comes from the camphor tree rather than Madagascar's own Ravensara.","https://roberttisserand.com/2010/02/ravensara-rant/"],"epic":["Seeds from the offspring of a camphor tree that survived the Hiroshima bomb reached Kew's Millennium Seed Bank in 2021, and one seedling now grows at Wakehurst in England.","https://www.kew.org/read-and-watch/hiroshima-green-legacy"],"legendary":["The camphor tree that gives ravintsara is a restricted invasive weed in Queensland, Australia, where it is replacing native blue gums, one of the koala's favourite food trees.","https://weeds.brisbane.qld.gov.au/weeds/camphor-laurel"]},"pandan":{"common":["Pandan chiffon cake, popular in Singapore, uses pandan leaf in place of vanilla; a local newspaper mentioned it as early as 1972.","https://eresources.nlb.gov.sg/infopedia/articles/SIP_2021-11-15_140111.html?s=Plants"],"uncommon":["Pandan's rice-like scent comes from 2-acetyl-1-pyrroline, the molecule behind basmati and jasmine rice; the leaves hold roughly 50 to 100 times more of it than rice.","https://premierepeau.com/pages/glossary-terms/pandan-leaf"],"rare":["Pandan extracts have shown some repelling effect on cockroaches, and taxi drivers use the leaves to keep insects away.","https://eresources.nlb.gov.sg/infopedia/articles/SIP_2021-11-15_140111.html?s=Plants"],"epic":["Of about 700 Pandanus species, pandan is the only one with scented leaves.","https://blogs.reading.ac.uk/tropical-biodiversity/2013/01/pandanus-amaryllifolius"],"legendary":["Pandan seems unknown in the wild, and the flowers and fruits of its common small form have never been recorded; it spreads only by suckers and cuttings in gardens.","https://blogs.reading.ac.uk/tropical-biodiversity/2013/01/pandanus-amaryllifolius"]},"yarrow":{"common":["Yarrow's genus Achillea is named after Achilles, who in legend used the plant to heal wounds after learning its powers from the centaur Chiron.","https://garden.rcp.ac.uk/viewPlant?plantId=18"],"uncommon":["Yarrow oil's blue azulenes are not in the fresh herb: they form during steam distillation from compounds such as achillicin.","https://ema.europa.eu/en/documents/herbal-report/draft-assessment-report-achillea-millefolium-l-flos_en.pdf"],"rare":["Gerard's 1633 herbal held that sniffing yarrow brings on a nosebleed that stops migraines, and Culpeper wrote that it was called Nose-bleed.","https://garden.rcp.ac.uk/viewPlant?plantId=18"],"epic":["The I Ching was traditionally consulted with 50 yarrow stalks, one set aside at the start; this method is over a thousand years older than the three-coin method.","https://en.wikipedia.org/wiki/I_Ching_divination"],"legendary":["Plaque on the teeth of Neanderthals from El Sidrón, Spain, held traces of bitter yarrow and chamomile, hinting that they chose the plants as medicine.","https://www.sci.news/othersciences/anthropology/article00476.html"]},"plumblossom":{"common":["The ume of Japanese plum blossom is really the Japanese apricot, a crop that has been highly valued in Japan for about 1,300 years.","https://www.fao.org/giahs/giahs-around-the-world/japan-minabe-system/en"],"uncommon":["In the Minabe-Tanabe ume system, ume trees feed Japanese honeybees with nectar and the bees pollinate the trees; about 70% of local workers are in ume-related jobs.","https://www.fao.org/giahs/giahs-around-the-world/japan-minabe-system/en"],"rare":["Taiwan's government named the plum blossom its national flower on 21 July 1964; its five petals stand for the five branches of government.","https://english.president.gov.tw/Page/98"],"epic":["Japan's era name Reiwa comes from the preface to 32 poems written at a plum blossom viewing party hosted by Otomo no Tabito in Dazaifu in 730.","https://www.chuo-u.ac.jp/english/features/2019/06/59990/"],"legendary":["Legend says Sugawara no Michizane's plum tree missed him so much after he was sent to Dazaifu that it flew there overnight from Kyoto; it is the Tobiume by the shrine.","https://www.dazaifu-japan-heritage.jp/en/bunkazai/detail.php?cId=336"]},"opoponax":{"common":["Opoponax is also sold as sweet myrrh or scented myrrh. It is the resin of Commiphora guidottii, a shrub of Somalia and Ethiopia, and Somalia has exported it since ancient times.","https://en.wikipedia.org/wiki/Opopanax_(perfumery)"],"uncommon":["In Somalia scented myrrh is added to cattle feed to improve milk production, and it is used as a home remedy for stomach complaints and wounds.","https://llifle.com/Encyclopedia/TREES/Family/Burseraceae/33350/Commiphora_guidottii"],"rare":["Opopanax first named the sun-dried stem juice of Hercules' all-heal, a herb of Greece, Turkey and Iran with a strong unpleasant odour, taken for asthma and spasms. Perfumers later gave the name to sweet myrrh.","https://en.wikipedia.org/wiki/Opopanax_chironium"],"epic":["Gum haggar, a related resin also sold as opoponax, kept cattle ticks away for up to 5 hours in lab tests, while true myrrh did nothing. Germacrene-D was among its active compounds.","https://libra.unine.ch/handle/123456789/12482"],"legendary":["Scented myrrh was a long-standing Somali export, yet botanists credited the wrong tree until 1991, when Mats Thulin and Per Claeson showed it comes from Commiphora guidottii, not C. erythraea.","https://link.springer.com/article/10.1007/BF02930711"]},"copal":{"common":["Copal is burned on Day of the Dead altars across Mexico. Its smoke is believed to mark the path that the souls of the dead follow back to the offering.","https://liverpool.ac.uk/languages-cultures-and-film/events/iblaw-2023/dia-de-muertos"],"uncommon":["Copal harvesters cut the trunk with a sharp metal wedge, steer the resin into maguey leaves or bottles, and reopen the cut every three days from August to October.","https://www.mdpi.com/1999-4907/16/5/801"],"rare":["The word copal comes from Nahuatl copalli. In Eastern Huasteca Nahuatl the resin is called iezzo cuahuitl, the blood of trees.","https://aztecglyphs.wired-humanities.org/content/copalli-mdz37r"],"epic":["Archaeologists studied 313 copal objects from 61 offerings at Tenochtitlan's Great Temple, including human figurines with copal cores coated in stucco and dressed in paper clothes.","https://www.redalyc.org/pdf/943/94326949006.pdf"],"legendary":["Aztec tribute records list 8,000 packages of wild copal wrapped in maize leaves, plus 400 baskets of white copal bars, sent from today's Guerrero to Tenochtitlan every 80 days.","https://www.redalyc.org/pdf/943/94326949006.pdf"]},"dragonsblood":{"common":["Dragon's blood is the dark red resin of the Socotra dragon tree, which grows only on Yemen's Socotra archipelago. Its dense crown is shaped like an upturned umbrella up to 12 m across.","https://en.wikipedia.org/wiki/Dracaena_cinnabari"],"uncommon":["On Socotra the resin has been used to dye wool, glue pottery, freshen breath and colour lips as a lipstick.","https://en.wikipedia.org/wiki/Dracaena_cinnabari"],"rare":["Dragon's blood appears among Socotra's goods in the 1st-century Periplus, and in the 18th century Italian violin makers used it to tint their varnish.","https://socotra.info/dragons-blood-resin-from-socotra.html"],"epic":["An Indian legend tells of a dragon, standing for Brahma, biting an elephant, standing for Shiva, and drinking its blood. The falling elephant crushed the dragon, and their mixed blood became the resin.","https://daily.jstor.org/plant-of-the-month-the-dragon-tree"],"legendary":["A 2021 drone survey of Firmihin, the last dragon tree forest, counted 35,542 living trees with an average age near 290 years. Goats eat the seedlings, so almost none are young.","https://www.mdpi.com/1999-4907/14/4/766"]},"redwood":{"common":["Coast redwoods can grow to 112 m tall with a base 7 m wide, yet each starts from a seed about the size of a tomato seed.","https://www.nps.gov/redw/learn/nature/about-the-trees.htm"],"uncommon":["In California's dry summers, fog supplies about 40% of the water a coast redwood takes in, which helps it survive until the rains return.","https://www.nps.gov/redw/learn/nature/about-the-trees.htm"],"rare":["Hyperion, found in 2006 and called the tallest tree in the world, stands in a closed area. Trespassers risk a fine or jail, and the park says a view of it doesn't match its hype.","https://www.nps.gov/redw/planyourvisit/hyperion.htm"],"epic":["Burls at a redwood's base can sprout after damage, so a fallen giant or its stump may be ringed by a perfect circle of new trees called a fairy ring.","https://www.nps.gov/articles/000/coast-redwood.htm"],"legendary":["The coast redwood genome, sequenced in 2019, holds 27 billion base pairs, nearly nine times the human genome, and the tree carries six sets of chromosomes.","https://www.ucdavis.edu/news/coast-redwood-and-giant-sequoia-mega-genomes-sequenced"]},"deodar":{"common":["The deodar is the national tree of Pakistan and the state tree of India's Himachal Pradesh. It can reach 40 to 50 m, exceptionally about 60 m.","https://en.wikipedia.org/wiki/Cedrus_deodara"],"uncommon":["Deodar comes from the Sanskrit devadaru, from deva, god, and daru, wood or tree. Hindus revere the tree, and its timber was used to build temples.","https://en.wikipedia.org/wiki/Cedrus_deodara"],"rare":["Srinagar's houseboats are built entirely of deodar, which can stay in water for long periods. They began in the 1850s, when British visitors were refused permission to own land.","https://edition.cnn.com/travel/article/srinagar-houseboats-india-cmd"],"epic":["Oil distilled from deodar heartwood is used as an insect repellent on the feet of livestock, especially cattle, camels and horses.","https://www.mq.edu.au/__data/assets/pdf_file/0010/1257229/Plant-of-the-week-Cedrus-deodara-Himalayan-Cedar.pdf"],"legendary":["Chaini Kothi, a 400-year-old tower of deodar and stone in Himachal, stands 35 m tall even after losing two storeys in the 1905 Kangra earthquake. Its ladder is cut from a single deodar log.","https://livehistoryindia.com/story/places/chaini-kothi-himachals-towering-edifice"]},"asafoetida":{"common":["Its foul raw smell earned asafoetida the English nickname devil's dung, and the German name Teufelsdreck means the same. Its odour comes mainly from sulfur compounds also found in garlic and cooked onion.","https://en.wikipedia.org/wiki/Asafoetida"],"uncommon":["Hing lends a savoury, onion-garlic taste, so Hare Krishna devotees, who avoid onion and garlic, cook with it instead. It is also a staple of Jain and Brahmin kitchens.","https://en.wikipedia.org/wiki/Asafoetida"],"rare":["India is the largest consumer of asafoetida yet never grew it, importing about 1,200 tonnes a year. Cultivation only began in 2020, at Kwaring village in Himachal Pradesh's Lahaul valley.","https://www.theweek.in/news/india/2020/10/20/in-a-first-india-starts-cultivation-asafoetida-cold-deserts-himachal-pradesh.amp.html"],"epic":["Mothers hung bags of asafoetida around children's necks to ward off disease. In 1912 a Texas newspaper reported San Angelo residents using the bags as a precaution against spinal meningitis.","https://texascooppower.com/making-a-stink/"],"legendary":["Romans used asafoetida as a cheaper substitute for silphium, a prized resin that went extinct in the 1st century AD. Pliny wrote that the last stem found was sent to Emperor Nero.","https://www.tastesofhistory.co.uk/post/a-brief-history-of-foods-the-mysterious-silphium"]},"wasabi":{"common":["Fresh wasabi is hard to get outside Japan, so most sushi restaurants serve kona wasabi, a powder of horseradish and mustard. The burn of all three comes from the same compound, allyl isothiocyanate.","https://en.wikipedia.org/wiki/Wasabi"],"uncommon":["Water wasabi grows with its roots in flowing spring water, ideally at 10 to 13 °C and rich in oxygen. It dislikes direct sun and suffers heat damage when air tops 28 °C.","https://en.wikipedia.org/wiki/Wasabi"],"rare":["Wasabi farming began in Utogi, near Shizuoka, in the Edo period. Legend says shogun Tokugawa Ieyasu found its wasabi so delicious that he banned growing it outside the village.","https://taiken.co/single/the-birthplace-of-wasabi-utougi/"],"epic":["The wooden water wheels at Daio Wasabi Farm in Azumino, Nagano, were built in 1989 for Akira Kurosawa's film Dreams and have been left standing among the fields.","https://www.japan-guide.com/e/e6056.html"],"legendary":["A Japanese team won the 2011 Ig Nobel Prize in Chemistry for an alarm that sprays wasabi odour into the air to wake sleepers in a fire, designed for people with hearing impairments.","https://www.japanfs.org/en/news/archives/news_id031527.html"]},"blackcardamom":{"common":["Black cardamom is not ripe green cardamom. It comes from a different plant in the ginger family, Amomum subulatum, with larger dark brown pods and a smoky, menthol-tinged flavour.","https://www.masterclass.com/articles/black-cardamom-vs-green"],"uncommon":["Farmers dry the pods in a bhatti, a kiln heated by a wood fire, for 25 to 40 hours. It takes about 2.5 kg of fuelwood to make 1 kg of dried pods, and the smoke gives them their flavour.","https://research.usq.edu.au/download/93df9b0918af535c0516ba99811b5b558068be007ca1fabc882e883f6d4abf5c/3310726/2013%20Postharvest%20Processing%20of%20Large%20Cardamom%20in%20the%20Eastern%20Himalaya%20-a%20review.pdf"],"rare":["A 2013 review put Nepal's share of world large cardamom at 52%, ahead of India at 37% and Bhutan at 11%. About 90% of Nepal's crop is exported to India.","https://research.usq.edu.au/download/93df9b0918af535c0516ba99811b5b558068be007ca1fabc882e883f6d4abf5c/3310726/2013%20Postharvest%20Processing%20of%20Large%20Cardamom%20in%20the%20Eastern%20Himalaya%20-a%20review.pdf"],"epic":["Sikkim was the world's top grower until 2003-04. Since then viral diseases called chirke and foorkey and warmer winters have hit the crop, and farmers are moving it to higher ground.","https://www.downtoearth.org.in/climate-change/rise-after-the-fall-61505"],"legendary":["Only a native bumblebee pollinates large cardamom well. A 2007 Sikkim study found honeybees raid the flowers for pollen without pollinating them, leaving 70% of the flowers unpollinated.","https://www.downtoearth.org.in/amp/story/environment/polen-theft-by-honeybees-hits-sikkims-cardamom-yield-6700"]},"nigella":{"common":["Nigella's small black seeds top some naan breads, such as Persian nân-e barbari, and are worked into majdouleh, a braided string cheese from the Middle East.","https://en.wikipedia.org/wiki/Nigella_sativa"],"uncommon":["Despite names like black cumin, nigella belongs to the buttercup family, Ranunculaceae. The annual herb grows 20 to 90 cm tall, and its seeds are only 1 to 3 mm long.","https://pmc.ncbi.nlm.nih.gov/articles/PMC10353664/"],"rare":["A hadith in Sahih al-Bukhari quotes the Prophet Muhammad saying black cumin is healing for all diseases except as-sam, which he explains means death.","https://sunnah.com/bukhari:5687"],"epic":["The Hebrew word qetsach in Isaiah 28 is often identified as black cumin. The verse says it is not threshed with a heavy sledge but beaten out with a rod, as its small seeds are easily crushed.","https://biblehub.com/hebrew/7100.htm"],"legendary":["Nigella seeds were found at several ancient Egyptian sites, including the tomb of Tutankhamun, and in a Hittite flask from Turkey dating to the second millennium BC.","https://en.wikipedia.org/wiki/Nigella_sativa"]},"sunflower":{"common":["Young sunflowers turn from east to west during the day and swing back overnight. Once they bloom they stop and face east, warming faster and drawing five times as many pollinating insects.","https://www.sciencedaily.com/releases/2016/08/160804152431.htm"],"uncommon":["The tallest sunflower on record, named Clover, measured 10.90 m in a Fort Wayne, Indiana backyard in 2025, beating a 9.17 m record from Germany that had stood since 2014.","https://www.guinnessworldrecords.com/news/2025/9/tallest-sunflower-as-high-as-a-three-storey-house-topples-decade-old-record"],"rare":["In 1829 Danila Bokarev, a self-taught serf, used a wooden press to squeeze oil from sunflower seeds in Alekseyevka, Voronezh province, and the trade made the poor village prosperous.","https://zn.ua/science/metamorfozy_zolotogo_tsvetka.html"],"epic":["Alan Turing was fascinated by the Fibonacci spirals in sunflower heads but died before finishing his work. In 2016 a citizen science project in his honour analysed over 500 sunflowers.","https://www.manchester.ac.uk/discover/news/turings-sunflowers-growing-alan-turings-legacy"],"legendary":["Grown on floating rafts in a pond near the Chernobyl reactor, sunflowers soaked up 95% of the radioactive strontium and caesium in the water, the US company Phytotech reported.","https://indiaenvironmentportal.org.in/news-clippings/a-flowery-tale"]},"cottoncandy":{"common":["Cotton candy's machine was co-invented by William Morrison, who qualified as a dentist in Tennessee in 1890, and confectioner John C. Wharton; their first working model ran in 1897.","https://www.historyhit.com/the-unlikely-story-of-the-dentist-who-invented-cotton-candy/"],"uncommon":["The treat goes by fairy floss in Australia, candy floss in Britain and India, Papa's Beard (barbe à papa) in France and Old Lady's Hair in Greece.","https://www.smithsonianmag.com/smart-news/people-worlds-fair-paid-half-admission-box-cotton-candy-180961332/"],"rare":["Ethyl maltol, patented by Pfizer in 1969, smells of caramel, jam and cotton candy. It entered perfumery in Mugler's Angel in 1992 and now anchors sugary gourmand scents.","https://en.wikipedia.org/wiki/Ethyl_maltol"],"epic":["At the 1904 St. Louis World's Fair, fairy floss sold for 25 cents a box, half the fair's entry fee, and its inventors still sold more than 65,000 boxes.","https://www.smithsonianmag.com/smart-news/people-worlds-fair-paid-half-admission-box-cotton-candy-180961332/"],"legendary":["Vanderbilt engineer Leon Bellan adapted cotton candy machines to spin fibre networks that template artificial capillaries; in a 2016 study, cells fed by them stayed alive for over a week.","https://my.vanderbilt.edu/vinsenews/?p=980"]},"daphne":{"common":["Winter daphne opens its flowers in late winter, and the scent is so strong that a couple of cut flowers can perfume a whole room.","https://dunsmuirbotanicalgardens.org/woodland-plants-a-g/winter-daphne/"],"uncommon":["Every part of winter daphne, from roots and bark to flowers and seeds, is rated highly poisonous; the suspected culprit is a diterpenoid, likely mezerein, and the sap can irritate skin.","https://plants.ces.ncsu.edu/plants/daphne-odora/"],"rare":["Its Japanese name, jinchōge (沈丁花), joins jinkō, agarwood, for the scent with chōji, clove, for the look of the flower.","https://hosho.ees.hokudai.ac.jp/tsuyu/top/plt/daphne/daphne/odo.html"],"epic":["Only male plants are thought to have reached Japan, before the mid-Muromachi era, so the winter daphnes in Japanese gardens are likely all male.","https://hosho.ees.hokudai.ac.jp/tsuyu/top/plt/daphne/daphne/odo.html"],"legendary":["An early Chinese herbal tells of a monk asleep below a cliff on Mount Lu who smelled it in a dream, then climbed to find it. He named it shuixiang, sleeping scent, later ruixiang, lucky scent.","https://bugwomanlondon.com/2018/12/12/wednesday-weed-winter-daphne/"]},"passionflower":{"common":["Christian missionaries in South America saw symbols of Christ's crucifixion in the flower's parts, which is why it is called the passion flower.","https://tnhomeandfarm.com/tn-living/tn-history/tennessee-state-flower/"],"uncommon":["In 1919 Tennessee let its schoolchildren pick the state flower, and they chose the passion flower; since 1973 it has been the official state wildflower.","https://tnhomeandfarm.com/tn-living/tn-history/tennessee-state-flower/"],"rare":["Spanish explorers learned of passionflower in South America in the 16th century; taken to Europe, it entered folk medicine, and it is still sold as a tea or extract for anxiety and sleep.","https://www.nccih.nih.gov/health/passionflower"],"epic":["Some passion vines grow small yellow stipules that look like butterfly eggs about to hatch. Heliconius females avoid laying where eggs already sit, since their caterpillars can be cannibals.","https://en.wikipedia.org/wiki/Gilbertian_mimicry"],"legendary":["The Andean passion flower Passiflora mixta hides its nectar at the bottom of a 7 to 15 cm tube, reached by the sword-billed hummingbird, whose bill is longer than its entire body.","https://en.wikipedia.org/wiki/Passiflora_mixta"]},"redcurrant":{"common":["Red currants hang in drooping strings 4 to 8 cm long, each berry translucent and 8 to 12 mm across; an established bush can give 3 to 4 kg of fruit.","https://en.wikipedia.org/wiki/Redcurrant"],"uncommon":["Currant comes from raisins of Corinth, small dried grapes from Greece. In the 1570s the English gave the name to Ribes berries, which looked similar but are unrelated to grapes.","https://www.etymonline.com/word/currant"],"rare":["White currants are not a separate species: they are a sweeter, less pigmented cultivar of the red currant, Ribes rubrum.","https://en.wikipedia.org/wiki/Redcurrant"],"epic":["Hand-made Bar-le-Duc preserve, first recorded in 1344, keeps its currants whole in a thin syrup; about 200 seeded berries go into each 85 g jar.","https://en.wikipedia.org/wiki/Bar-le-duc_jelly"],"legendary":["In Bar-le-Duc, seeders pierce each currant with a hollow goose quill and pull out its 6 to 8 seeds, leaving the berry whole; the best manage nearly 9 pounds a day.","https://www.saveur.com/article/Kitchen/The-Almost-Lost-Art-of-Bar-Le-Duc/"]},"champagne":{"common":["Champagne's sparkle comes from a second fermentation inside the bottle itself, a method developed in the region from the early 1600s to the 1800s.","https://whc.unesco.org/en/list/1465/"],"uncommon":["In Reims, chalk quarries dug in Gallo-Roman and medieval times became champagne cellars, an underground network still in use and listed by UNESCO in 2015.","https://whc.unesco.org/en/list/1465/"],"rare":["Pouring 100 mL of champagne straight down into an upright flute releases about one million bubbles, according to physicist Gérard Liger-Belair's measurements.","https://knowablemagazine.org/article/food-environment/2021/champagne-bubbles-science"],"epic":["Champagne, a Swiss village of about 750 people in Vaud, cannot put its own name on its still white wine: in 2021 a court upheld the French name's exclusive protection.","https://www.thejakartapost.com/news/2021/04/18/swiss-village-champagne-loses-another-fight-to-get-name-on-wine-.html"],"legendary":["Champagne from a ship that sank around 1840 lay 50 m deep off Finland's Åland islands. Tasted in the 2010s, it first smelled of wet hair, then of fruit, smoke and leather.","https://www.tum.de/en/news-and-events/all-news/press-releases/details/32389"]},"amaryllis":{"common":["Its common name, naked lady, comes from the bare flower stalk: the pink trumpets open in late summer before any leaves appear, and the leaves follow after flowering.","https://pza.sanbi.org/node/9741"],"uncommon":["The big bulbs sold as amaryllis for Christmas are usually Hippeastrum, a South American genus. The true Amaryllis is the South African belladonna lily.","https://pza.sanbi.org/node/9741"],"rare":["In wild fynbos the belladonna lily flowers in large numbers only after a fire, though garden plants bloom almost every year.","https://kumbulanursery.co.za/node/436"],"epic":["The bulbs are very toxic to livestock and people, and the Khoi and San reportedly used the bulb sap as an arrow poison.","https://kumbulanursery.co.za/node/436"],"legendary":["From 1938 botanists argued whether Linnaeus's 1753 Amaryllis was South African or South American. The 1987 International Botanical Congress settled it with a Cape specimen held in London.","https://en.wikipedia.org/wiki/Amaryllis"]},"rangooncreeper":{"common":["Its flowers open white at dusk for hawkmoths, turn pink on the second day and red on the third, when day-flying bees and birds take over.","https://en.wikipedia.org/wiki/Combretum_indicum"],"uncommon":["The flowers have a sweet, fruity aroma that some people compare to Jolly Rancher candies, according to Cornell's Liberty Hyde Bailey Conservatory.","https://conservatory.cals.cornell.edu/?p=621"],"rare":["Its old genus name Quisqualis is Latin for 'Who? What?', a puzzle attributed to botanists who saw a shrub when the plant was young and a rambling vine later.","https://conservatory.cals.cornell.edu/?p=621"],"epic":["In the Philippines, as niog-niogan, it was one of 10 plants in a 1992 health brochure; adults chew 8 to 10 dried seeds against worms, and overdoing it can cause hiccups.","https://stuartxchange.org/Niyog"],"legendary":["Its seeds contain quisqualic acid, among the most potent AMPA receptor agonists known, which neuroscientists use to destroy chosen neurons. Geranium petals carry it too, paralysing Japanese beetles.","https://en.wikipedia.org/wiki/Quisqualic_acid"]},"sake":{"common":["For ginjo sake, each rice grain is polished until 60% or less of it remains; at that point only about 5% of the rice's fat is left.","https://sakestreet.com/en/media/learn-sake-aroma-1"],"uncommon":["Ginjo sake's fruity scent comes from two yeast-made esters: ethyl caproate, which smells of apple, and isoamyl acetate, which smells of banana, both helped by fermenting at 5 to 10 °C.","https://sakestreet.com/en/media/learn-sake-aroma-1"],"rare":["In 1840 brewer Yamamura Tazaemon had oxen haul well water more than 7 km from Nishinomiya to his Uozaki brewery, showing that this Miyamizu water was what made his sake better.","https://www.nippon.com/en/guide-to-japan/gu900138/"],"epic":["By the late Edo period about 80% of the sake drunk in Edo, now Tokyo, came from Nada, shipped there by sea in barrels.","https://www.nippon.com/en/guide-to-japan/gu900138/"],"legendary":["One of Japan's earliest sakes, kuchikamizake, was started by chewing rice so saliva enzymes drove fermentation. It reached up to 7% alcohol, and some Okinawan islands used it in rites until the 1930s.","https://en.wikipedia.org/wiki/Kuchikamizake"]},"tobaccoflower":{"common":["Flowering tobacco's white tubular flowers give off a strong, sweet, jasmine-like scent that is strongest in the evening, aimed at sphinx moths.","https://mastergardener.extension.wisc.edu/files/2015/12/Nicotiana_sylvestris.pdf"],"uncommon":["Victorian gardeners planted woodland tobacco along walkways and paths so that people strolling past could enjoy its fragrance.","https://mastergardener.extension.wisc.edu/files/2015/12/Nicotiana_sylvestris.pdf"],"rare":["Woodland tobacco, native to the Andes of Argentina and Bolivia, is thought to be one of the parents of Nicotiana tabacum, the plant grown for modern tobacco.","https://en.wikipedia.org/wiki/Nicotiana_sylvestris"],"epic":["In 1989 researchers showed that the style proteins Nicotiana alata uses to reject its own pollen are ribonucleases, enzymes that break down RNA.","https://www.nature.com/articles/342955a0"],"legendary":["When hornworm caterpillars attack a wild tobacco in Utah, it opens its flowers at dawn instead of dusk, stops releasing its moth-luring scent and gets pollinated by hummingbirds.","https://www.sciencedaily.com/releases/2010/01/100121135659.htm"]},"aldehydes":{"common":["In 1920 Ernest Beaux showed Coco Chanel his samples in Cannes, and she picked No. 5, the one with an overdose of aldehydes.","https://en.wikipedia.org/wiki/Ernest_Beaux"],"uncommon":["Much of the smell of oranges comes from the aldehydes octanal to undecanal, close cousins of the ones that make No. 5 sparkle.","https://www.chm.bris.ac.uk/motm/octanal/octanalh.htm"],"rare":["A 2012 study of 14,604 people linked a gene variant near OR6A2, a smell receptor that binds aldehydes such as decanal, to finding cilantro soapy.","https://ar5iv.arxiv.org/html/1209.2096"],"epic":["Beaux said No. 5's top note recalled a wartime campaign beyond the Arctic Circle, when lakes and rivers under the midnight sun gave off a scent of extreme freshness.","https://boisdejasmin.com/2013/12/perfumer-ernest-beaux-on-fragrance-masterpieces.html"],"legendary":["The crested auklet of the Bering and Okhotsk seas gives off a tangerine scent made of aldehydes such as octanal and decanal, shown to repel mosquitoes.","https://www.chm.bris.ac.uk/motm/octanal/octanalv.htm"]},"hedione":{"common":["Hedione's first commercial success was Dior's Eau Sauvage, created by Edmond Roudnitska and launched in 1966.","https://en.wikipedia.org/wiki/Methyl_dihydrojasmonate"],"uncommon":["The name Hedione comes from the Greek hedone, meaning pleasure, the same root as the word hedonism.","https://chemistryworld.com/podcasts/hedione/4010435.article"],"rare":["Hedione is a relative of methyl jasmonate, a plant signal: sagebrush releasing it into the air made nearby tomato plants produce defence proteins.","https://www.citedrive.com/en/discovery/interplant-communication-airborne-methyl-jasmonate-induces-synthesis-of-proteinase-inhibitors-in-plant-leaves"],"epic":["Eau Sauvage held 2.5% Hedione in 1966, but as its price fell perfumers used far more, up to 65% in the 1998 perfume Odeur 53.","https://www.chm.bris.ac.uk/motm/hedione/hedioneh.htm"],"legendary":["In 2015 Bochum researchers found Hedione activates VN1R1, a possible human pheromone receptor, and a hormone-linked area of the hypothalamus, more strongly in women.","https://neurosciencenews.com/hedione-olfactory-epithelium-1943/"]},"isoesuper":{"common":["Escentric Molecules' Molecule 01 has just one ingredient: the aroma molecule Iso E Super, diluted.","https://us.escentric.com/pages/faqs"],"uncommon":["Terre d'Hermès is about 55% Iso E Super and Lalique Perles around 80%, far beyond Dior Fahrenheit's early overdose of 1988.","https://www.scentspiracy.com/synthetics/iso-e-super"],"rare":["Iso E Super seems to fade and come back because it binds to smell receptors and lets go slowly, and regular wearers can become partly nose-blind to it.","https://us.escentric.com/pages/faqs"],"epic":["In 1968 Günther Ohloff of Firmenich published the formula for what became Iso E but never patented it; IFF chemists made the same compound in 1973 and got the patent in 1975.","https://en.wikipedia.org/wiki/Tetramethyl_acetyloctahydronaphthalenes"],"legendary":["Most of Iso E Super is a beta isomer that is nearly odourless; its scent comes from a minor gamma isomer, arborone, only a few percent of the mix.","https://en.wikipedia.org/wiki/Tetramethyl_acetyloctahydronaphthalenes"]},"cashmeran":{"common":["The 'cashmere wood' of note lists is cashmeran, a lab molecule whose scent does not exist in nature, so no tree is involved at all.","https://www.artisanparfumeur.com/uk/en_GB/ingredient/cashmeran"],"uncommon":["Cashmeran was discovered by IFF chemist John Hall, who in 1973 also created Iso E Super with James Milton Sanders.","https://en.wikipedia.org/wiki/Cashmeran"],"rare":["Pure cashmeran is a white solid that melts at 27 °C, so a hot summer room is enough to turn it liquid.","https://en.wikipedia.org/wiki/Cashmeran"],"epic":["Cashmeran smells musky, yet IFRA says it is neither primarily a musk nor a member of that chemical family; it is an indanone.","https://premierepeau.com/blogs/news/cashmeran-why-cozy-has-a-molecular-formula-premiere-peau"],"legendary":["IFF accounts say cashmeran was found when chemists analysed an impurity spotted by gas chromatography during work on another fragrance compound.","https://www.scentspiracy.com/fragrance-ingredients/p/cashmeran"]},"coumarin":{"common":["Perkin made coumarin from coal-tar chemicals in 1868, and in 1882 Houbigant's Fougère Royale put it on the market, the model for a whole family of fougère perfumes.","https://www.mcgill.ca/oss/node/10124"],"uncommon":["Cassia cinnamon is rich in coumarin: Germany's BfR said a 15 kg child would pass the tolerable daily intake by eating about 6 small cinnamon star biscuits a day.","https://www.bfr.bund.de/en/press-release/cassia-cinnamon-with-high-coumarin-contents-to-be-consumed-in-moderation/"],"rare":["The name comes from coumarou, French for the tonka bean, which goes back to kumarú, the Old Tupi name for the tonka tree.","https://en.wikipedia.org/wiki/Coumarin"],"epic":["Polish Żubrówka vodka, with a blade of bison grass in each bottle, was banned in the US for over 30 years over coumarin, returning in 2010 with a coumarin-free recipe.","https://atlasobscura.com/foods/bison-grass-vodka-zubrowka"],"legendary":["Mould in sweet clover hay turns coumarin into a blood thinner; bleeding cattle led Wisconsin chemist Karl Link to warfarin, named after WARF and coumarin.","https://www.npr.org/sections/health-shots/2017/08/29/531749974/how-moldy-hay-and-sick-cows-led-to-a-life-saving-drug"]},"galaxolide":{"common":["Galaxolide has been used in fabric softeners and detergents since the 1960s, as well as in fine perfumes.","https://www.analytice.com/en/?p=44142"],"uncommon":["By 1988 more than 6,000 tonnes of Galaxolide were made each year, making it one of the world's highest-tonnage aroma chemicals.","https://scentspiracy.com/fragrance-ingredients/galaxolide-100"],"rare":["Galaxolide is a mix of four isomers, but the strong musk comes from two of them, the 4S forms, which can be detected at 1 nanogram per litre or less.","https://en.wikipedia.org/wiki/Galaxolide"],"epic":["A 2004 study found Galaxolide in 97% of breast milk samples from Massachusetts mothers, and a 2009 study found it in the blood plasma of 91% of participants.","https://en.wikipedia.org/wiki/Galaxolide"],"legendary":["Galaxolide in Lake Erie sediment reportedly doubled every 8 to 16 years, and it turned up in 92% of water samples taken from Lake Michigan.","https://en.wikipedia.org/wiki/Galaxolide"]},"appleblossom":{"common":["A Michigan joint resolution of 1897 made the apple blossom the state flower, citing the state's blossoming orchards and its native fragrant crab apple.","https://zeus-milenia.legislature.mi.gov/documents/mcl/pdf/MCL-2-11.pdf"],"uncommon":["Apple buds open in clusters of six, and the central king blossom opens first. Its fruit is often larger than the others in the cluster.","https://www.uoguelph.ca/research/photo-contest/apple-king-flower-majesty-king-flower-bloom"],"rare":["A well-pollinated apple holds 10 developed seeds. When too few bees visit the blossoms, fruit with few seeds tends to be undersized and lopsided.","https://fruitscout.mgcafe.uky.edu/poor-pollination-apple"],"epic":["On frosty spring nights growers spray apple blossoms with water. As it freezes it releases latent heat, holding the flowers near 0 °C inside a coat of ice.","https://yardandgarden.extension.iastate.edu/article/2025/04/basics-spring-frost-damage-prevention-strawberries-and-apples"],"legendary":["Where bees have vanished in Sichuan's Maoxian county, villagers pollinate apple blossoms by hand with sticks of chicken feathers and cigarette filters, 5 to 10 trees a day.","https://asiangeo.com/?p=24159"]},"peachblossom":{"common":["Delaware named the peach blossom its state flower on 9 May 1895, in a state that had once counted over 800,000 peach trees.","https://www.delawarepublic.org/post/history-matters-delaware-and-peach"],"uncommon":["Japan's Hinamatsuri doll festival on 3 March was formerly called the Peach Festival, Momo no Sekku, and peach blossoms still adorn it as a ward against evil spirits.","https://cotoacademy.com/hinamatsuri/"],"rare":["In Cantonese tradition peach blossoms bring luck in finding love, and one custom is to run three times clockwise around a large peach blossom tree.","https://macaudailytimes.com.mo/made-macao-peach-blossoms-luck.html"],"epic":["In a tale by poet Tao Yuanming (365 to 427), a Wuling fisherman follows a river of blossoming peach trees to a hidden valley of people who fled the Qin wars. No one could find it again.","https://www.metmuseum.org/art/collection/search/853230"],"legendary":["In the 1699 play The Peach Blossom Fan, Li Xiangjun strikes her head on a pillar to refuse becoming a concubine, and her blood on her lover's fan is painted into peach blossoms.","https://en.wikipedia.org/wiki/The_Peach_Blossom_Fan"]},"pearblossom":{"common":["The Bradford pear, a cultivar of Asia's Callery pear, has blossoms likened to rotted fish left in the sun. Ohio, South Carolina and Pennsylvania have banned the trees.","https://npr.org/2024/03/24/1240533947/some-states-want-to-keep-these-pretty-pear-trees-from-blossoming"],"uncommon":["Tang poet Cen Shen likened an eighth-month frontier snowfall to a spring wind arriving overnight and opening ten thousand pear trees in blossom.","https://cn-poetry.com/censhen-poetry/white-snow-song.html"],"rare":["Ewha, the name Emperor Gojong gave a Seoul girls' school in 1887, means pear blossom in Chinese characters. The school, now Ewha Womans University, made the flower its emblem in 1930.","https://evoice.ewha.ac.kr/news/articleView.html?idxno=4031"],"epic":["Under the Tang dynasty, an area of Chang'an called the Pear Garden trained hundreds of musicians and dancers. Chinese actors have since been called liyuan zidi, children of the pear garden.","https://www.britannica.com/topic/Pear-Garden"],"legendary":["In Gansu's Shichuan orchard each ancient pear tree has its own archive and QR code. One code records a tree about 345 years old, its health, variety and caretaking family.","https://regional.chinadaily.com.cn/gansu/2026-08/25/c_1208303.htm"]},"lemonblossom":{"common":["Lemon flower buds are reddish, and the open flowers are white above and purplish beneath. In Florida the trees bloom from late December to March and may bloom again in June and November.","https://ask.ifas.ufl.edu/publication/HS402"],"uncommon":["In Sicily citrus blossom is called zagara, a word that comes from the Arabic zahr, meaning flower.","https://www.balarm.it/news/chiamateli-fiori-d-arancio-o-zagare-perche-i-fiori-siciliani-sono-il-simbolo-delle-nozze-124212"],"rare":["On the Amalfi Coast lemons are still picked by hand, and farmers carry baskets of up to 70 kg along mountain paths hundreds of metres above the sea.","https://www.fao.org/newsroom/story/the-amalfi-lemon-and-its-layered-resilient-landscape/en"],"epic":["Southern Italian growers still practise forzatura, an ancient water-stress technique that forces lemon trees into an out-of-season bloom, giving verdelli lemons for summer.","https://ishs.org/ishs-article/1458_31/"],"legendary":["Lemon is one of four citrus species found to carry caffeine in its nectar. In a 2013 study, bees fed caffeine were three times as likely to remember a flower's scent 24 hours later.","https://www.livescience.com/27722-caffeine-gives-bees-memory-boost.html"]},"bellflower":{"common":["Campanula is Latin for little bell, after the shape of its flowers, and the common name bellflower has the same origin.","https://en.wikipedia.org/wiki/Campanula"],"uncommon":["The harebell is known as the bluebell of Scotland, and also as witch bells and old man's bell, the old man said to be the devil himself.","https://www.plantlife.org.uk/plants-and-fungi/harebell/"],"rare":["Bellflowers push pollen out on hairs along the style. An insect's touch makes cells at their base lose water and the hairs retract; only then does the stigma become receptive.","https://www.indefenseofplants.com/blog/tag/hairbell"],"epic":["The harebell carpenter bee, just 5 to 6 mm long, rests inside bellflowers overnight or in wet weather, and males mate with females inside the flowers.","https://www.edphillipswildlife.com/the-harebell-carpenter-bee-chelostoma"],"legendary":["Rampion, Campanula rapunculus, was once eaten for its leaves and fleshy roots. In the fairy tale, Rapunzel is named after the rampion her mother craved while pregnant.","https://www.botanischetuinen.nl/en/plant_en/229/rampion-bellflower"]},"bluebell":{"common":["The UK is home to about half of the world's bluebell population, and the flowers' distinctive scent draws bees beneath the trees in April and May.","https://www.plantlife.org.uk/plants-and-fungi/bluebell/"],"uncommon":["Bluebells are a common indicator of ancient woodland, so a wood carpeted with them is likely to date back to at least 1600.","https://en.wikipedia.org/wiki/Bluebell_wood"],"rare":["Bluebell root sap was used to glue feathers onto arrows in the Middle Ages and to stiffen ruffs in Tudor times.","https://www.plantlife.org.uk/plants-and-fungi/bluebell/"],"epic":["Non-scripta means unlettered: the name sets the bluebell apart from the mythical hyacinth, on whose petals Apollo wrote AI AI, alas, in grief for the dying Hyacinthus.","https://www.plantlife.org.uk/plants-and-fungi/bluebell/"],"legendary":["Plantlife barred the bluebell from its county flowers vote because it had been by far the top choice in an earlier poll for the nation's favourite flower.","https://en.wikipedia.org/wiki/Hyacinthoides_non-scripta"]},"wallflower":{"common":["The plant was called wallflower by the 1570s because it grows on old walls. By 1820 the word also meant someone who sits by the wall at a party without a dance partner.","https://www.etymonline.com/word/wallflower"],"uncommon":["Wallflower's old genus name Cheiranthus means hand flower, a nod to how often it was carried in nosegays and tussie-mussies.","https://www.monticello.org/encyclopedia/erysimum-cheiri-cv-paris-market-wallflower"],"rare":["In a poem by Robert Herrick, a young woman climbs a wall to slip away to her lover, her silk cord gives way and she falls, and Love turns her into the flower of the wall.","https://luminarium.org/sevenlit/herrick/wallflower.htm"],"epic":["While serving as US president, Thomas Jefferson sent his daughter Martha a bundle of wallflowers in 1806, and in 1807 he ordered wallflower seed from Philadelphia nurseryman Bernard McMahon.","https://www.monticello.org/encyclopedia/erysimum-cheiri-cv-paris-market-wallflower"],"legendary":["Wallflowers are mustard-family plants that also make cardenolides, the heart toxins best known from foxglove. Research suggests the genus gained this second defence only 2 to 4 million years ago.","https://www.newswise.com/articles/wallflowers-could-lead-to-new-drugs"]},"goldenrod":{"common":["Goldenrod is often blamed for hay fever, but the real cause is ragweed, which blooms at the same time. Goldenrod's flowers are worked by bees, wasps, flies and butterflies.","https://en.wikipedia.org/wiki/Solidago_canadensis"],"uncommon":["Nebraska made goldenrod its official state flower on April 4, 1895, to represent the spirit of its pioneers. Goldenrod is also the state flower of Kentucky.","https://www.wowt.com/2026/04/04/today-history-april-4-nebraska-adopts-state-flower/"],"rare":["Canadian goldenrod is invasive in eastern China. Local news reported that invasive plants including it had wiped out 30 native plant species in Shanghai by 2004.","https://en.wikipedia.org/wiki/Solidago_canadensis"],"epic":["Goldenrod gall fly larvae spend winter inside round galls on goldenrod stems. They survive freezing by building up sorbitol and glycerol, while chickadees and woodpeckers peck the galls open to eat them.","https://en.wikipedia.org/wiki/Goldenrod_gall_fly"],"legendary":["At his Fort Myers, Florida lab, Thomas Edison tested about 17,000 plants as a source of rubber and settled on goldenrod, growing plants about 15 feet tall. A goldenrod variety is named after him.","https://www.edisonfordwinterestates.org/edison-research-laboratory-goldenrod-project/"]},"babysbreath":{"common":["Florists call baby's breath gyp and use its clouds of tiny white flowers as a backdrop for larger blooms. It is a staple of US corsages and a major part of Peru's flower exports.","https://en.wikipedia.org/wiki/Gypsophila_paniculata"],"uncommon":["The name Gypsophila means chalk-loving. In the wild, baby's breath grows on the steppes of central and eastern Europe in dry, sandy, stony places, often on limy soils.","https://en.wikipedia.org/wiki/Gypsophila_paniculata"],"rare":["Baby's breath snaps off at ground level and rolls like a tumbleweed, scattering seed. It escapes mainly from discarded flower arrangements, and each plant can release 10,000 seeds or more.","https://mda.state.mn.us/plants/pestmanagement/weedcontrol/wom/wotm201703baby"],"epic":["Researchers traced the unpleasant smell of baby's breath flowers to two methylbutyric acids. In one cultivar they were absent in buds and peaked when the flowers fully opened.","https://dx.doi.org/10.2503/jjshs.74.139"],"legendary":["On Michigan's Sleeping Bear Dunes, invasive baby's breath sinks a taproot up to 10 feet into the sand and spreads about 14,000 seeds a year, crowding out the threatened Pitcher's thistle.","https://www.gvsu.edu/gvmagazinearchive/research-fall-2016-433.htm"]},"callalily":{"common":["Despite its names, the calla lily is neither a true arum nor a true lily. Its white blooms became a symbol of purity and a fixture of bridal bouquets.","https://pza.sanbi.org/node/11125"],"uncommon":["South Africans have called it the pig lily since at least 1844, from Dutch varklelie. One 1883 writer guessed pigs love its roots; another theory is that the curled spathe looks like a pig's ear.","https://dsae.co.za/entry/piglily/e05631"],"rare":["Raw calla lily makes the throat swell because it is packed with microscopic calcium oxalate crystals. Traditionally the plant is boiled before it is eaten.","https://pza.sanbi.org/node/11125"],"epic":["Calla lily reached Europe very early: it is illustrated in a 1664 account of the Royal Garden in Paris, and Cape governor Simon van der Stel sent it to Europe before 1697.","https://pza.sanbi.org/node/11125"],"legendary":["Since 1926 Irish republicans have worn the Easter Lily, a calla lily-shaped badge introduced by Cumann na mBan for fighters who died in the 1916 Easter Rising or were executed after it.","https://en.wikipedia.org/wiki/Easter_Lily_(badge)"]},"poppy":{"common":["Canadian doctor and poet John McCrae wrote In Flanders Fields in 1915 after seeing poppies near a cemetery at Ypres, and the red poppy became the flower of remembrance.","https://growwild.kew.org/plants/common-poppy"],"uncommon":["Corn poppies make no nectar, yet a UK study ranked them top for pollen per flower among meadow wildflowers. Each flower may last only a single day.","https://growwild.kew.org/plants/common-poppy"],"rare":["Corn poppy seeds have been recorded as still viable after 80 years in undisturbed soil. When battle churned the fields of Flanders, millions of dormant seeds sprang to life.","https://growwild.kew.org/plants/common-poppy"],"epic":["Morphine, taken from the opium poppy by German apothecary apprentice Friedrich Sertürner, was the first alkaloid ever isolated from a plant. He first named it after Morpheus, Greek god of dreams.","https://www.the-hospitalist.org/hospitalist/article/123203/morphines-modest-origin/"],"legendary":["In 2009 Tasmania's attorney general said wallabies were eating opium poppies, getting as high as a kite and going around in circles, making crop circles in the fields. Australia grows about half the world's legal opium.","https://www.australiangeographic.com.au/?p=22767"]},"kowhai":{"common":["Kōwhai is the Māori word for yellow, and the tree's golden blooms are widely regarded as one of New Zealand's unofficial national flowers. They appear on the country's stamps and coins.","https://en.wikipedia.org/wiki/K%C5%8Dwhai"],"uncommon":["Kōwhai flowering is staggered from July to November, feeding tūī, kererū and bellbirds for much of the season. Its yellow flowers are thought to be an adaptation to bird pollination.","https://en.wikipedia.org/wiki/K%C5%8Dwhai"],"rare":["For Māori, the flowering of kōwhai signalled when to plant kūmara (sweet potato) and when to harvest kina, the sea urchin. Its flowers also gave a yellow dye.","https://en.wikipedia.org/wiki/K%C5%8Dwhai"],"epic":["Meghan Markle's 5-metre silk tulle wedding veil carried a flower for each of the 53 Commonwealth countries. New Zealand was represented by kōwhai, Sophora microphylla.","https://www.royal.uk/wedding-dress-bridesmaids%E2%80%99-dresses-and-page-boys-uniforms"],"legendary":["Kōwhai seeds can float and still germinate after time in seawater. Its relatives grow in Chile, Réunion and Gough Island, and Easter Island's toromiro is closer kin to New Zealand kōwhai than to Chile's.","https://blog.tepapa.govt.nz/2017/08/30/kowhais-global-family-tree/"]},"clover":{"common":["Four-leaf clovers are usually put at about 1 in 10,000, though a Swiss count of 5.7 million clovers found one for every 5,076 three-leaf ones.","https://www.mentalfloss.com/science/plants/how-rare-are-four-leaf-clovers"],"uncommon":["Rhizobium bacteria in white clover's root nodules fix nitrogen from the air. A pasture with 20% clover can gain 100 to 200 kg of nitrogen per hectare a year, feeding the grass.","https://teagasc.ie/news--events/daily/white-clover-is-a-second-half-player/"],"rare":["In 1988 Ireland's National Botanic Gardens examined 243 shamrocks sent in by the public: 46% were yellow clover, 35% white clover, and most of the rest black medick, wood sorrel or red clover.","https://www.smithsonianmag.com/arts-culture/no-one-really-knows-what-shamrock-180954578/"],"epic":["White clover can release hydrogen cyanide to deter grazers. A 2022 study by 287 scientists sampling 110,000 plants in 160 cities found city clover usually makes less of it than rural clover.","https://www.washington.edu/news/2022/03/18/urbanization-is-driving-evolution-of-plants-globally-study-finds/"],"legendary":["In 2024 Guinness confirmed a 63-leaf white clover grown by Yoshiharu Watanabe in Nasushiobara, Japan, who had cross-pollinated clovers since 2012. The old record was 56 leaves.","https://www.guinnessworldrecords.com/news/2024/6/record-breaking-63-leaf-clover-grown-by-japanese-man-770312"]},"cedarleaf":{"common":["Sold as arborvitae, Latin for tree of life, eastern white cedar is a staple hedge plant with more than 300 named garden cultivars.","https://en.wikipedia.org/wiki/Thuja_occidentalis"],"uncommon":["Thujone, the compound long blamed for absinthe's effects, takes its name from this tree's genus, Thuja. Absinthe holds only traces of it, while arborvitae, sage and wormwood carry more.","https://en.wikipedia.org/wiki/Thujone"],"rare":["In the winter of 1535 to 1536 scurvy killed 25 of Jacques Cartier's 110 men near Quebec. Domagaya showed them annedda, a brew of bark and twigs believed to be eastern white cedar, which saved the survivors.","https://parks.canada.ca/lhn-nhs/qc/cartierbrebeuf/culture/histoire-history/evenement-event/cartier/c"],"epic":["On bare rock near Grand Portage, Minnesota, grows Manido Gizhigans, Ojibwe for Spirit Little Cedar Tree. The explorer La Verendrye wrote of it as a mature tree in 1731, and paddlers still leave tobacco there.","https://www.paddlinglight.com/articles/trip-reports/manido-gizhigans-spirit-little-cedar-tree-the-witch-tree"],"legendary":["Living and long-dead cliff cedars on Flowerpot Island, Ontario, have yielded a tree-ring record 2,787 years long, starting around 798 BC, the longest from eastern North America.","https://www.ldeo.columbia.edu/res/fac/trl/downloads/Publications/2004_Buckley_Bruce.pdf"]},"witchhazel":{"common":["Witch hazel started as a remedy brewed by New England's Native Americans. A 1915 Dickinson's label claimed the distillate treated sprains, neuralgia, rheumatism and bruises.","https://www.ctexplored.org/witch-hazel-connecticuts-wonder-shrub/"],"uncommon":["Nearly all the witch hazel used worldwide is distilled by Dickinson Brands in East Hampton, Connecticut. The firm moved there in 1997 from Essex, where it began in 1866.","https://www.ctexplored.org/witch-hazel-connecticuts-wonder-shrub/"],"rare":["The witch in witch hazel likely comes from Old English wych, to bend. Settlers used its forked, flexible branches as divining rods to find underground water.","https://www.scienceworld.ca/stories/ever-wonder-about-witch-hazel/"],"epic":["Witch hazel's woody seed capsules take about a year to ripen, then split open explosively, ejecting their black seeds up to 30 feet (9 m) away.","https://naturewalk.yale.edu/node/424"],"legendary":["Owlet moths feed at witch hazel flowers on cold October nights and are likely its main pollinators. To fly they shiver until their bodies reach about 86 °F (30 °C).","https://vtecostudies.org/blog/field-guide-to-october-2018"]},"santolina":{"common":["Cotton lavender is named for its whitish-grey, fragrant leaves, but it is not a lavender. It belongs to the daisy family, alongside the wormwoods, and bears yellow button flowers in summer.","https://blog.metmuseum.org/cloistersgardens/2012/02/24/evergray/"],"uncommon":["Dried santolina was hung in wardrobes and tucked among linen to keep clothes moths away, which earned it the French nickname garde-robe.","https://www.jardiner-malin.fr/fiche/santoline-santolina.html"],"rare":["Santolina may come from Latin sanctus, holy, and linum, flax, while chamaecyparissus is Greek for ground cypress, though the plant is related to neither.","https://museumsandcastles.wakefield.gov.uk/visit/pontefract-castle/medieval-herb-garden-blogs/cotton-lavender"],"epic":["Oil distilled from santolina at an Italian botanic garden in 2021 and 2022 was 53% to 56% artemisia ketone, followed by camphor at 13% to 16%.","https://www.mdpi.com/2311-7524/11/10/1184"],"legendary":["Renaissance herbalists treated santolina as the female form of southernwood. Andres de Laguna's 16th-century Spanish Dioscorides shows them side by side as Artemisia mas and Artemisia foemina.","https://blog.metmuseum.org/cloistersgardens/2012/02/24/evergray/"]},"fern":{"common":["Paul Parquet's Fougère Royale of 1882, French for royal fern, imagined a fern scent from synthetic coumarin, lavender, geranium and oakmoss, and gave its name to the whole fougère family.","https://boisdejasmin.com/2021/06/fougere-perfumes-and-fragrant-ferns.html"],"uncommon":["Ferns have no flowers or seeds. They spread by spores released from the brownish sori under their fronds, and a single fern can produce up to 20 million of them.","https://www.countrylife.co.uk/gardens/curious-questions-why-were-ferns-considered-magical-243647"],"rare":["The pale undersides of New Zealand's silver fern reflect moonlight, which helped people find bush pathways at night. It has been a national emblem since the 1880s.","https://www.tepapa.govt.nz/significance-silver-fern"],"epic":["Since ferns show no seed, people believed fern seed fell at midnight on Midsummer Eve and made its owner invisible. Shakespeare's Gadshill boasts: we have the receipt of fern seed, we walk invisible.","https://www.countrylife.co.uk/gardens/curious-questions-why-were-ferns-considered-magical-243647"],"legendary":["The New Caledonian fork fern Tmesipteris oblanceolata holds 160.45 billion DNA base pairs, over 50 times the human genome. Unravelled, one cell's DNA would stretch over 100 m.","https://www.kew.org/about-us/press-media/worlds-largest-genome"]},"dill":{"common":["The food industry uses dill mainly for dill pickles, often packing whole seed heads into the jar. The feathery leaves, dill weed, taste stronger than the seeds.","https://herbsociety.org/file_download/inline/0057e7c3-ab18-4301-b46f-fff2ece06d1f"],"uncommon":["Dill was prized enough that from 812 Charlemagne, King of the Franks and Emperor of the Romans, ordered it to be cultivated widely.","https://en.wikipedia.org/wiki/Dill_oil"],"rare":["Dill seeds were nicknamed meetinghouse seeds because people chewed them to get through long church services.","https://herbsociety.org/file_download/inline/0057e7c3-ab18-4301-b46f-fff2ece06d1f"],"epic":["Dill seed holds the most oil while still green, 7 to 9 days after the petals drop, at 2.6% to 3.7%. By 22 to 24 days, when it turns dark grey, that falls to about 1.7%.","https://uses.plantnet-project.org/en/Anethum_graveolens_(PROSEA)"],"legendary":["Gladiators were served meals covered in dill, in the hope that the herb would give them valour and courage.","https://herbsociety.org/file_download/inline/0057e7c3-ab18-4301-b46f-fff2ece06d1f"]},"barley":{"common":["Barley was probably domesticated as early as 10,000 years ago in the Fertile Crescent, and it still ranks fourth among cereals in total grain production.","https://www.encyclopedia.com/food/encyclopedias-almanacs-transcripts-and-maps/barley"],"uncommon":["Robinsons Barley Water was invented at Wimbledon in 1935, and the brand stayed on the tennis courts for 86 years until the partnership ended in 2022.","https://www.sportcal.com/news/sponsorship/robinsons-aeltc-end-wimbledon-partnership-after-86-years"],"rare":["Roman gladiators were nicknamed hordearii, 'barley eaters'. Bones from a gladiator cemetery at Ephesus show they lived on a mostly vegetarian, grain-based diet.","https://www.meduniwien.ac.at/web/en/about-us/news/detailsite/anthropology-unlocks-clues-about-roman-gladiators-eating-habits/"],"epic":["Golden Promise, the dominant barley in Scotland in the 1970s, came from gamma-ray mutation of the variety Maythorpe. Distillers once turned about 400,000 tonnes of it into whisky a year.","https://www.beerandbrewing.com/dictionary/COMO4SK5Y5"],"legendary":["A 1324 decree of Edward II defined the inch as three barleycorns laid end to end. By 1856 British shoemakers spaced sizes one-third of an inch apart, one barleycorn per size.","https://www.satra.com/bulletin/article.php?id=3230"]},"grape":{"common":["Grapes and raisins can cause acute kidney injury in dogs. In 2022 vets named tartaric acid as the likely culprit, after linking cases to homemade playdough made with cream of tartar.","https://www.aspcapro.org/node/104073"],"uncommon":["In 1869 dentist Thomas Welch, a Methodist communion steward in Vineland, New Jersey, heated bottled grape juice to stop it fermenting, giving his church an alcohol-free communion wine.","https://christianhistoryinstitute.org/magazine/article/raise-a-juice-box"],"rare":["Methyl anthranilate gives Concord grapes their flavour. At high doses it hits birds like hot chilli, so USDA scientists studied it as a goose repellent for landfills and airports.","https://csmonitor.com/1994/0907/07132.html"],"epic":["Ephraim Bull bred the Concord grape in Massachusetts in 1849, before plant varieties could be patented. He died poor in 1895, and his gravestone reads 'He sowed, others reaped.'","https://blog.library.si.edu/?p=14903"],"legendary":["Two whole grapes set within 3 mm of each other in a microwave can spit out glowing plasma. A 2019 PNAS study showed the pair focuses microwave energy into a hotspot between them.","https://www.sciencealert.com/we-might-finally-know-why-grapes-burst-into-flames-in-the-microwave"]},"fingerlime":{"common":["Cut a finger lime open and its pulp spills out as caviar-like pearls: its juice vesicles stay whole when the fruit is cut.","https://www.mdnc.org.au/finger-lime-dooja/"],"uncommon":["Finger lime has the widest range of colour of any citrus species, and CSIRO has bred hybrids with fruit from light pink to deep blue-green.","https://en.wikipedia.org/wiki/Citrus_australasica"],"rare":["In California, where fewer than a dozen growers farmed finger limes in 2015, the fruit was sold by the ounce, not the pound: a 1 oz box from Melissa's cost $8.","https://www.freshplaza.com/north-america/article/2150393/finger-lime-one-of-most-expensive-us-fruit-varieties/"],"epic":["First Peoples along Australia's east coast ate finger limes for hydration and used the fruit to treat skin infections and cuts.","https://en.wikipedia.org/wiki/Citrus_australasica"],"legendary":["A peptide found in Australian finger lime punctures the bacterium behind citrus greening and kills it within half an hour, a 2021 PNAS study led by UC Riverside found.","https://www.technologynetworks.com/proteomics/news/peptide-prevents-and-treats-killer-citrus-disease-345352"]},"timut":{"common":["Its citrusy taste earned timur nicknames such as grapefruit pepper and pomelo pepper. In Nepal it seasons pickles and the tangy condiment timur ko chhop.","https://askmeaboutnepal.com/post/timur-the-toothache-berry"],"uncommon":["In Nepal timur is nicknamed the toothache berry: its fruit, branches and thorns were used to ease toothache, young branches served as toothbrushes, and its extracts go into toothpaste.","https://askmeaboutnepal.com/post/timur-the-toothache-berry"],"rare":["More than 90% of Nepal's timur harvest is exported, and distillers send about 90% of their timur oil to India.","https://www.adaptation-undp.org/sites/default/files/resources/2013_dept_of_forests_undp_timur_value_chain_study.pdf"],"epic":["Of more than 130 volatiles in Nepalese timur, only 20 shape its smell. Its grapefruit and tropical notes come from four sulphur compounds, such as 3-mercaptohexanol.","https://agris.fao.org/search/ar/records/65df57e77c7033e84bed813d"],"legendary":["Every June at the Maun Mela on Uttarakhand's Aglar River, villagers release roasted, ground timru bark into the water to stun fish, and thousands gather as they wade in to catch them.","https://www.outlooktraveller.com/amp/story/stay/experiences/heritage/what-is-the-maun-festival-a-deep-dive-into-uttarakhands-150yearold-fishcatching-tradition"]},"beetroot":{"common":["Beets contain betanin, a red pigment some people cannot fully break down. About 10 to 14% of people get pink or red urine, called beeturia, after eating them.","https://health.clevelandclinic.org/beets-turn-poop-and-pee-red"],"uncommon":["In 1747 chemist Andreas Marggraf found that beet sugar matched cane sugar under a microscope. Breeding has since raised beet sugar content from about 2% to as much as 20%.","https://www.ebsco.com/research-starters/history/marggraf-extracts-sugar-beets"],"rare":["Road crews in states such as Kansas and Missouri mix beet juice into salt brine. It helps the salt stick to the road and lowers the freezing point of ice.","https://billypenn.com/2022/01/28/beet-juice-snow-philadelphia-rock-salt-environment-watershed-jim-kenney/"],"epic":["English sugar merchants reportedly offered Franz Karl Achard, who opened the first beet sugar refinery in 1801, 200,000 thalers to call his experiments a failure. He refused.","https://en.wikipedia.org/wiki/Franz_Karl_Achard"],"legendary":["Geosmin, an earthy molecule people can smell at 10 to 20 ng per litre of water, gives beets their taste. Beets grown in sterile soil and tissue culture still made it, so the plant likely makes its own.","https://journals.ashs.org/view/journals/jashs/144/6/article-p429.xml"]},"mushroom":{"common":["Mushrooms are fungi, and fungi are much more closely related to animals than to plants. Like the shells of insects, their cell walls are built with chitin.","https://en.wikipedia.org/wiki/Opisthokont"],"uncommon":["Matsutake means 'pine mushroom': in Japan it grows in partnership with the roots of red pine, and the harvest fell sharply as a pine-killing nematode spread.","https://en.wikipedia.org/wiki/Matsutake"],"rare":["Japan picked 12,000 tons of matsutake in 1941 but only 45 tons in 2024. Imports, mostly from China, now make up over 90% of the matsutake on sale.","https://www.nippon.com/en/japan-data/h02548/japan-relies-on-imports-to-satisfy-craving-for-matsutake-mushrooms.html"],"epic":["The Man'yoshu poetry anthology praises matsutake's fragrance as the smell of autumn, and Edo-period lords such as Tokugawa Mitsukuni went on matsutake hunts.","https://japanroyalservice.com/blog/by-invitation-only-matsutake-hunting-in-the-japanese-autumn"],"legendary":["A single honey fungus in Oregon's Malheur National Forest spans about 9.1 km² and may be 8,000 years old, making it possibly the largest living organism on Earth.","https://en.wikipedia.org/wiki/Armillaria_ostoyae"]},"milk":{"common":["An average dairy cow gives 6 to 8 gallons of milk a day, about 100 glasses, and she only starts producing milk once she has had a calf.","https://www.midwestdairy.com/farm-life/farm-life-faq/"],"uncommon":["Milk looks white because its casein proteins cluster with calcium into tiny micelles that scatter all colours of light. Milk fat from grass-fed cows is yellower, tinted by beta-carotene.","https://www.fonterra.com/cn/en/our-stories/articles/why-is-milk-white.html"],"rare":["Most adults worldwide do not make lactase, the enzyme that digests milk sugar. The gene that keeps it working appears to have spread about 7,500 years ago, between the central Balkans and central Europe.","https://cordis.europa.eu/article/id/31258-got-milk-central-europeans-did-7500-years-ago"],"epic":["Poppaea Sabina, wife of the emperor Nero, was said to have 500 asses milked every day to fill her bath, a story recorded by Roman writers.","https://cts.perseids.org/read/pdlrefwk/viaf88890045/003/perseus-eng1/S.sabina_poppaea_1"],"legendary":["Verghese Kurien, the engineer who led India's White Revolution and helped make it the world's largest milk producer, did not like milk himself.","https://www.bostonglobe.com/metro/obituaries/2012/09/11/leader-india-dairy-revolution-dies/6Ql7HrkMOrsn4YsJBIZwhN/story.html"]},"whippedcream":{"common":["Cream needs about 30 to 36% butterfat to whip, because the fat holds the air bubbles in place. Whisk too long and the fat clumps until the cream turns into butter.","https://en.wikipedia.org/wiki/Whipped_cream"],"uncommon":["Spray-can whipped cream began in the 1930s with Charles Getz, a chemistry student at the University of Illinois. Carbon dioxide changed the cream's taste, so he switched to nitrous oxide.","https://distributedmuseum.illinois.edu/exhibit/aerosol_whip_cream/"],"rare":["Chantilly's steward François Vatel is often credited with the cream, but he took his own life during a 1671 royal feast after roast and fish ran short, and accounts of the feast never mention cream.","https://ville-chantilly.fr/focus-creme-chantilly"],"epic":["16th-century cooks called whipped cream snow: neve di latte, milk snow, in Italy, and a London recipe of 1545 called A Dyschefull of Snow beat cream with egg whites.","https://en.wikipedia.org/wiki/Whipped_cream"],"legendary":["The Chantilly name was first tied to cream around 1784, when the cream served at the prince's rustic play-hamlet in the château park, a retreat for guests like Emperor Joseph II, won praise.","https://ville-chantilly.fr/focus-creme-chantilly"]},"macaron":{"common":["Macaron shells are a meringue of egg white, icing sugar and granulated sugar folded with almond meal, then sandwiched with ganache, buttercream or jam.","https://en.wikipedia.org/wiki/Macaron"],"uncommon":["Macaron and macaroni share a root: both come from the Italian maccarone. English recorded the almond cake as macaroon in the 1610s.","https://www.etymonline.com/word/macaroon"],"rare":["Ladurée's Pierre Desfontaines is credited with the idea, in 1930, of joining two macaron shells around a creamy ganache, the sandwich form now known worldwide.","https://en.wikipedia.org/wiki/Ladur%C3%A9e"],"epic":["In 1793 the Revolution expelled nuns Marie-Élisabeth Morlot and Marguerite Gaillot from their convent. Their almond biscuits sold so well in Nancy they became the Macaron Sisters.","https://www.destination-nancy.com/en/decouvrir-nancy/gastronomie/nancy-passions-sucrees/macaron-de-nancy/"],"legendary":["Legend says an Italian chef of Catherine de' Medici brought macarons to France, but research into her household records found no Italian chefs on her staff.","https://en.wikipedia.org/wiki/Macaron"]},"bread":{"common":["On 30 November 2022 UNESCO added the craft and culture of the French baguette, made from just flour, water, salt and yeast, to its list of intangible cultural heritage.","https://www.wokv.com/news/trending/not-so-crumby-baguette-added-un-cultural-heritage-list/AR4RCG3OSFCKZC672HN52WEPB4"],"uncommon":["Under a 1993 French decree, bread sold as pain de tradition française may contain only bread flour, water, salt and yeast or starter, with no additives, and it must never be frozen.","https://www.cooksinfo.com/french-bread-law-1993"],"rare":["The winner of Paris's yearly Grand Prix de la baguette takes 4,000 euros and becomes one of the bakeries supplying the Élysée Palace, the French president's residence, for a year.","https://english.ahram.org.eg/News/522631.aspx"],"epic":["When Pompeii's Modestus bakery was excavated in 1846, its oven still held 81 carbonised loaves of bread, put in to bake minutes before the eruption of Vesuvius in 79 AD.","https://pompeii.pictures/R7/7%2001%2036.htm"],"legendary":["2-acetyl-1-pyrroline, a molecule behind the smell of freshly baked bread, also scents basmati rice and pandan, and gives the urine of the binturong, or bearcat, its popcorn-like smell.","https://en.wikipedia.org/wiki/2-Acetyl-1-pyrroline"]},"flint":{"common":["Flint throws off sparks of hot material when struck against steel, and with a little tinder it has been used to start fires and to fire early flintlock guns.","https://geology.com/rocks/flint.shtml"],"uncommon":["Norfolk has 127 round church towers, counting ruins. With little good stone for corners, medieval builders made most of them of flint, and a round plan needs no corners.","https://buildingconservation.com/articles/roundtower/roundtower.htm"],"rare":["The name Grime's Graves is Anglo-Saxon: the bumpy landscape of filled-in Neolithic mine shafts was believed to be the work of the god Grim, or Woden.","https://www.english-heritage.org.uk/visit/places/grimes-graves-prehistoric-flint-mine/history/"],"epic":["Flint knappers in Brandon, Suffolk, were the only suppliers of gunflints to Wellington's forces at Waterloo, and millions of flints were made in the town.","https://www.brandon-tc.gov.uk/community/brandon-town-council-20066/history"],"legendary":["A chalk goddess figurine found in a Grime's Graves shaft in 1939 may be a modern fake, amid rumours it was planted to fool the archaeologist who found it, Leslie Armstrong.","https://en.wikipedia.org/wiki/Grime%27s_Graves"]},"sand":{"common":["Glass is sand that has been melted and transformed. Silica sand needs roughly 1,700 °C to melt, so glassmakers add soda ash to lower the melting point and limestone to stabilise it.","https://www.corning.com/worldwide/en/innovation/materials-science/glass/how-glass-made.html"],"uncommon":["Parrotfish bite off coral, grind it in their guts and excrete it as fine white sand, and a single fish can produce hundreds of pounds a year, helping build Hawaii's white beaches.","https://oceanservice.noaa.gov/facts/sand.html"],"rare":["When sand avalanches down California's 200 m Eureka Dune it booms, a loud, nearly monotone rumble at about 70 to 105 Hz carried by waves travelling through the dune.","https://publishing.aip.org/publications/latest-content/physics-of-booming-and-burping-sand-dunes-revealed/"],"epic":["The world uses 50 billion tonnes of sand and gravel a year, the second most exploited resource after water, enough to build a wall 27 m wide and 27 m high around the Earth.","https://news.un.org/en/node/1116972"],"legendary":["To show that the grains of sand are not infinite, Archimedes wrote to King Gelon estimating that filling the whole universe would take about 8 × 10^63 grains.","https://physics.weber.edu/carroll/archimedes/sand.htm"]}}`);export{e as TEXT};
